#!/usr/bin/env python3
"""Read Apple VPN action catalog metadata without running actions or reading profiles.

Usage on a macOS 27 runner:
  python3 probe_apple_vpn_metadata.py --output-dir vpn-metadata
  python3 probe_apple_vpn_metadata.py --database /path/to/Tools-active \
      --output-dir vpn-metadata

This does not launch the Shortcuts GUI, call `shortcuts run`, load private
frameworks, inspect Shortcuts.sqlite, or query NetworkExtension. An optional
--initialize-catalog invokes only `shortcuts list`, with a 45 second timeout and
without exporting workflow names. Missing metadata is never a runtime pass.
"""

from __future__ import annotations

import argparse
import base64
import hashlib
import json
import platform
import plistlib
import shutil
import sqlite3
import subprocess
from datetime import datetime, timezone
from pathlib import Path


ACTION_IDS = (
    "is.workflow.actions.vpn.get",
    "is.workflow.actions.filter.vpns",
    "is.workflow.actions.vpn.set",
    # An optional lookup, not an assumption that a Get Details action exists.
    "is.workflow.actions.properties.vpns",
    "is.workflow.actions.count",
    "is.workflow.actions.getitemfromlist",
    "is.workflow.actions.output",
    "is.workflow.actions.format.date",
    "is.workflow.actions.comment",
    "is.workflow.actions.gettext",
    "is.workflow.actions.setvariable",
    "is.workflow.actions.conditional",
    "is.workflow.actions.date",
    "is.workflow.actions.detect.dictionary",
    "is.workflow.actions.getvalueforkey",
    "is.workflow.actions.showresult",
    "is.workflow.actions.repeat.count",
    "is.workflow.actions.delay",
    "is.workflow.actions.repeat.each",
    "is.workflow.actions.uuid",
    "is.workflow.actions.generateuuid",
    "is.workflow.actions.alert",
)
MARKERS = (
    "wfvpn", ".vpn.get", ".vpn.set", ".filter.vpns",
    "filter_vpns", "vpn_set_wfvpnoperation",
)
PROPERTY_LABELS = (
    "Is Connected", "Is On Demand Enabled", "Server Address",
)
MAX_MATCH_ROWS = 200
MAX_RELATION_ROWS = 1200
MAX_STATIC_FILES = 64
MAX_STATIC_PARSE_BYTES = 8 * 1024 * 1024
STATIC_RESOURCE_ROOTS = tuple(Path(path) for path in (
    "/System/Library/PrivateFrameworks/WorkflowKit.framework/Resources",
    "/System/Library/PrivateFrameworks/WorkflowKit.framework/Versions/A/Resources",
    "/System/Library/PrivateFrameworks/ActionKit.framework/Resources",
    "/System/Library/PrivateFrameworks/ActionKit.framework/Versions/A/Resources",
    "/System/Library/PrivateFrameworks/ShortcutsKit.framework/Versions/A/Resources",
    "/System/Applications/Shortcuts.app/Contents/Resources",
    "/System/Applications/Shortcuts.app/Contents/Metadata.appintents",
    "/System/Applications/Shortcuts.app/Contents/PlugIns/ShortcutsActions.appex/Contents/Resources",
    "/System/Library/PrivateFrameworks/WorkflowKit.framework/Versions/A/Resources/Metadata.appintents",
    "/System/Library/PrivateFrameworks/ActionKit.framework/Versions/A/Resources/Metadata.appintents",
))


def ident(value: str) -> str:
    return '"' + value.replace('"', '""') + '"'


def encode(value):
    if isinstance(value, bytes):
        try:
            return {"plist": encode(plistlib.loads(value))}
        except Exception:
            return {
                "length": len(value), "sha256": hashlib.sha256(value).hexdigest(),
                "base64": base64.b64encode(value).decode("ascii"),
            }
    if isinstance(value, dict):
        return {str(key): encode(item) for key, item in value.items()}
    if isinstance(value, (tuple, list)):
        return [encode(item) for item in value]
    if isinstance(value, datetime):
        return value.isoformat()
    return value


def file_sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def read_toolkit(path: Path) -> dict:
    result = {"path": str(path), "mode": "SQLite URI mode=ro; PRAGMA query_only=ON"}
    if path.name.lower() == "shortcuts.sqlite":
        return {**result, "status": "refused_shortcut_database"}
    try:
        resolved = path.resolve(strict=True)
        result["resolvedPath"] = str(resolved)
        result["sourceSha256Before"] = file_sha256(resolved)
        connection = sqlite3.connect(resolved.as_uri() + "?mode=ro", uri=True)
        connection.row_factory = sqlite3.Row
        connection.execute("PRAGMA query_only=ON")
        tables = connection.execute(
            "SELECT name, type, sql FROM sqlite_schema WHERE type IN ('table','view') AND name NOT LIKE 'sqlite_%'"
        ).fetchall()
        table_names = {row["name"] for row in tables}
        if "Tools" not in table_names or any(name.upper().startswith("ZSHORTCUT") for name in table_names):
            connection.close()
            return {**result, "status": "refused_non_toolkit_database"}

        result["schema"] = {row["name"]: row["sql"] for row in tables}
        result["objectKinds"] = {row["name"]: row["type"] for row in tables}
        columns = {}
        foreign_keys = {}
        primary_keys = {}
        for table in table_names:
            info = connection.execute(f"PRAGMA table_info({ident(table)})").fetchall()
            columns[table] = [dict(row) for row in info]
            primary_keys[table] = [row["name"] for row in info if row["pk"]]
            foreign_keys[table] = [dict(row) for row in connection.execute(
                f"PRAGMA foreign_key_list({ident(table)})"
            )]
        result["columns"] = columns
        result["foreignKeys"] = foreign_keys

        # Apple exposes useful ToolOutputTypes/ToolParameterTypes views as well
        # as tables. Export their exact rows for the selected action IDs.
        # Linking by toolId to Tools.rowId is explicit catalog structure, and
        # does not require these views to declare SQLite foreign keys.
        tools_columns = {item["name"] for item in columns["Tools"]}
        identifier_column = next((item for item in ("id", "identifier", "persistentIdentifier") if item in tools_columns), None)
        target_actions = {}
        linked = {}
        for action in ACTION_IDS:
            action_rows = [] if identifier_column is None else connection.execute(
                f"SELECT * FROM Tools WHERE {ident(identifier_column)} = ?", (action,)
            ).fetchall()
            target_actions[action] = [dict(row) for row in action_rows]
            linked[action] = {}
            for action_row in action_rows:
                if "rowId" not in action_row.keys():
                    continue
                for table in sorted(table_names):
                    if "toolId" in {item["name"] for item in columns[table]}:
                        rows = connection.execute(
                            f"SELECT * FROM {ident(table)} WHERE toolId = ? LIMIT ?",
                            (action_row["rowId"], MAX_MATCH_ROWS),
                        ).fetchall()
                        if rows:
                            linked[action].setdefault(table, []).extend(dict(row) for row in rows)
        result["targetActions"] = encode(target_actions)
        result["linkedActionMetadata"] = encode(linked)

        # Only match stable Apple catalog identifiers and property labels. We do
        # not enumerate any installed VPN configuration or dynamic picker values.
        selected = {}
        row_counts = {}
        for table in sorted(table_names):
            text_columns = [item["name"] for item in columns[table]
                            if any(kind in (item["type"] or "").upper() for kind in ("TEXT", "CHAR", "CLOB"))
                            or item["name"] in ("id", "identifier", "persistentIdentifier", "key", "name")]
            if not text_columns:
                continue
            conditions, values = [], []
            for column in text_columns:
                for marker in MARKERS:
                    conditions.append(f"instr(lower({ident(column)}), ?) > 0")
                    values.append(marker.lower())
                for label in PROPERTY_LABELS:
                    conditions.append(f"{ident(column)} = ?")
                    values.append(label)
            where = " OR ".join(conditions)
            count = connection.execute(f"SELECT count(*) FROM {ident(table)} WHERE {where}", values).fetchone()[0]
            if count:
                row_counts[table] = {"matching": count, "limit": MAX_MATCH_ROWS}
                selected[table] = [dict(row) for row in connection.execute(
                    f"SELECT * FROM {ident(table)} WHERE {where} LIMIT ?", [*values, MAX_MATCH_ROWS]
                )]

        # Traverse declared metadata foreign keys in both directions, so output
        # types, parameter types and localizations travel with the selected rows.
        # No inference from similarly named columns is used.
        relation_count = 0
        seen = set()

        def add_rows(table, query, args):
            nonlocal relation_count
            if relation_count >= MAX_RELATION_ROWS:
                return
            for row in connection.execute(query, args).fetchmany(MAX_MATCH_ROWS):
                item = dict(row)
                key = (table, json.dumps(encode(item), sort_keys=True))
                if key not in seen:
                    seen.add(key)
                    selected.setdefault(table, []).append(item)
                    relation_count += 1
                    if relation_count >= MAX_RELATION_ROWS:
                        break

        for table, rows in selected.items():
            for row in rows:
                seen.add((table, json.dumps(encode(row), sort_keys=True)))
        for _ in range(3):
            before = relation_count
            snapshot = {table: list(rows) for table, rows in selected.items()}
            for child, keys in foreign_keys.items():
                for key in keys:
                    parent, child_column = key["table"], key["from"]
                    if parent not in table_names:
                        continue
                    # Provider/container records fan out to all installed apps;
                    # they are not needed to describe these three actions.
                    if "container" in parent.lower() or "container" in child.lower():
                        continue
                    parent_column = key["to"]
                    if not parent_column:
                        if len(primary_keys[parent]) != 1:
                            continue
                        parent_column = primary_keys[parent][0]
                    for row in snapshot.get(child, []):
                        value = row.get(child_column)
                        if value is not None:
                            add_rows(parent, f"SELECT * FROM {ident(parent)} WHERE {ident(parent_column)} = ?", (value,))
                    for row in snapshot.get(parent, []):
                        value = row.get(parent_column)
                        if value is not None:
                            add_rows(child, f"SELECT * FROM {ident(child)} WHERE {ident(child_column)} = ?", (value,))
            if relation_count == before or relation_count >= MAX_RELATION_ROWS:
                break

        result["records"] = encode(selected)
        result["matchCounts"] = row_counts
        result["relatedRowsAdded"] = relation_count
        result["relationLimitReached"] = relation_count >= MAX_RELATION_ROWS
        result["targetActions"] = encode(target_actions)
        connection.close()
        result["sourceSha256After"] = file_sha256(resolved)
        result["status"] = "read"
    except Exception as error:
        result["status"] = "unavailable"
        result["error"] = f"{type(error).__name__}: {error}"
    return result


def discover_databases() -> list[Path]:
    # This directory stores Apple action catalogs, not the user's workflows.
    root = Path.home() / "Library/Shortcuts/ToolKit"
    return sorted(item for item in root.glob("Tools*")
                  if item.is_file() and not item.name.endswith(("-wal", "-shm")))


def initialize_catalog() -> dict:
    executable = shutil.which("shortcuts")
    if executable is None:
        return {"status": "cli_unavailable"}
    try:
        completed = subprocess.run([executable, "list"], capture_output=True, timeout=45)
        # Deliberately do not persist or print returned shortcut names.
        return {"status": "completed" if completed.returncode == 0 else "failed",
                "exitCode": completed.returncode, "stdoutBytes": len(completed.stdout),
                "stderrBytes": len(completed.stderr), "timeoutSeconds": 45}
    except subprocess.TimeoutExpired:
        return {"status": "timed_out", "timeoutSeconds": 45}
    except OSError as error:
        return {"status": "unavailable", "errorType": type(error).__name__}


def extract_static_vpn_entries(value) -> list[dict]:
    entries = []
    markers = (*MARKERS, "wfgetcurrentvpn", "wffindvpns", "wfsetvpn",
               "get current vpn", "find vpns", "set vpn")

    def matches(text):
        return isinstance(text, str) and any(marker in text.lower() for marker in markers)

    def add(path, item):
        if len(entries) >= 40:
            return
        encoded = encode(item)
        serialized = json.dumps(encoded, ensure_ascii=False)
        if len(serialized) > 128 * 1024:
            entries.append({"path": path, "entryOmitted": "over_128KiB",
                            "sha256": hashlib.sha256(serialized.encode()).hexdigest()})
        else:
            entries.append({"path": path, "value": encoded})

    def visit(item, path):
        if len(entries) >= 40:
            return
        if isinstance(item, dict):
            for key, child in item.items():
                if matches(str(key)):
                    add([*path, str(key)], child)
            if any(matches(child) for child in item.values() if isinstance(child, str)):
                add(path, item)
            for key, child in item.items():
                if isinstance(child, (dict, list)):
                    visit(child, [*path, str(key)])
        elif isinstance(item, list):
            for index, child in enumerate(item):
                visit(child, [*path, index])
    visit(value, [])
    return entries


def probe_static_resources() -> dict:
    # Fixed Apple bundle locations only. No recursive search, home-directory
    # traversal, user workflows, profiles, or executable/framework loading.
    directories, candidates, seen = [], [], set()
    for root in STATIC_RESOURCE_ROOTS:
        directories.append({"path": str(root), "exists": root.is_dir()})
        if not root.is_dir():
            continue
        try:
            children = sorted(root.iterdir())
        except OSError:
            continue
        for child in children:
            if len(candidates) >= MAX_STATIC_FILES:
                break
            if not child.is_file() or child.suffix.lower() not in (".plist", ".json", ".intentdefinition", ".actionsdata"):
                continue
            resolved = child.resolve()
            if str(resolved) in seen:
                continue
            seen.add(str(resolved))
            record = {"path": str(child), "resolvedPath": str(resolved)}
            try:
                record.update(bytes=child.stat().st_size, sha256=file_sha256(child))
                if record["bytes"] <= MAX_STATIC_PARSE_BYTES:
                    raw = child.read_bytes()
                    try:
                        data = plistlib.loads(raw)
                        record["parseFormat"] = "plist"
                    except Exception:
                        data = json.loads(raw)
                        record["parseFormat"] = "json"
                    record["vpnEntries"] = extract_static_vpn_entries(data)
                else:
                    record["parseStatus"] = "over_8MiB_parse_limit"
            except Exception as error:
                record["parseStatus"] = "unparsed_or_unavailable"
                record["errorType"] = type(error).__name__
            candidates.append(record)
    return {"status": "static_candidates_found" if candidates else "not_found",
            "directories": directories, "candidates": candidates,
            "candidateLimit": MAX_STATIC_FILES, "parseByteLimit": MAX_STATIC_PARSE_BYTES}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--database", action="append", default=[], type=Path,
                        help="Explicit Apple ToolKit catalog, including a simulator's Tools-active")
    parser.add_argument("--output-dir", required=True, type=Path)
    parser.add_argument("--initialize-catalog", action="store_true",
                        help="Optionally call only shortcuts list (45s timeout); never execute or import a shortcut")
    args = parser.parse_args()
    args.output_dir.mkdir(parents=True, exist_ok=True)
    bootstrap = initialize_catalog() if args.initialize_catalog else {"status": "not_requested"}
    databases = args.database or discover_databases()
    # Resolve aliases so the same catalog is not exported multiple times.
    unique = {}
    for database in databases:
        unique[str(database.resolve())] = database
    reports = [read_toolkit(item) for item in unique.values()]
    static_resources = probe_static_resources()
    required_action_rows = {action: any(report.get("targetActions", {}).get(action) for report in reports)
                            for action in ACTION_IDS[:3]}
    outcome = ("complete_required_catalog_rows" if all(required_action_rows.values()) else
               "partial_required_catalog_rows" if any(required_action_rows.values()) else
               "static_candidates_only" if static_resources["candidates"] else "not_found")
    summary = {
        "generatedAtUTC": datetime.now(timezone.utc).isoformat(),
        "platform": platform.platform(), "macOS": platform.mac_ver()[0],
        "scope": "Apple action catalog metadata only; no workflow execution, profile reads, or network control",
        "status": "catalog_read" if any(item.get("status") == "read" for item in reports) else "catalog_unavailable",
        "warning": "No catalog/action row is not proof of unavailability. Initialize a clean runner's action catalog separately if needed.",
        "databases": reports,
        "catalogBootstrap": bootstrap,
        "staticAppleResources": static_resources,
        "requiredVPNActionRowsFound": required_action_rows,
        "metadataOutcome": outcome,
        "runtimeValidation": "not_run; metadata collection is never a runtime pass",
    }
    output = args.output_dir / "apple-vpn-metadata.json"
    output.write_text(json.dumps(summary, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(json.dumps({"status": summary["status"], "metadataOutcome": outcome,
                      "runtimeValidation": "not_run", "output": str(output), "catalogs": len(reports)}))


if __name__ == "__main__":
    main()

import Foundation
import CoreFoundation
import RenewalCore

func debugLog(_ text: String) {}
enum IntegrationEnvironment {
    static var supportURL: URL? {
        URL(fileURLWithPath: ProcessInfo.processInfo.environment["RENEWAL_INTEGRATION_ROOT"]!)
            .appendingPathComponent(DriverFixture.shared.namespace, isDirectory: true)
    }
}
final class UIViewController {}
final class SharedPipelineContext {
    func addPendingProfileBatch(_ batch: PendingProfileBatch) {}
}
struct PendingProfileBatch {
    let bundleID: String
    let profiles: [Data]
    let app: InstalledApp?
    let certStatus: String?
}
enum OperationError: Error {
    case invalidParameters(String)
    case noConnection(reason: String)
}

final class NSManagedObjectContext: NSObject, @unchecked Sendable {
    var hasChanges: Bool { false }
    func perform<T>(_ body: @escaping () throws -> T) async rethrows -> T { try body() }
    func save() throws {}
    func object(with id: UUID) -> Any { DriverFixture.shared.apps.first { $0.objectID == id }! }
}
final class PersistentContainer { func newBackgroundContext() -> NSManagedObjectContext { NSManagedObjectContext() } }
final class DatabaseManager: @unchecked Sendable {
    static let shared = DatabaseManager()
    let isStarted = true
    let persistentContainer = PersistentContainer()
}
final class InstalledApp: @unchecked Sendable {
    let kind: RenewalApp
    let objectID = UUID()
    let bundleIdentifier: String
    let resignedBundleIdentifier: String
    let version = "1.0"
    let buildVersion = "1"
    let appBundleFingerprint: String? = "fixture-cache-structure"
    let appExtensions: [InstalledExtension] = []
    var managedObjectContext: NSManagedObjectContext? { nil }
    var certificateStatus: String?
    init(_ app: RenewalApp, original: String, installed: String) {
        kind = app; bundleIdentifier = original; resignedBundleIdentifier = installed
    }
    func update(provisioningProfile: ALTProvisioningProfile) {
        DriverFixture.shared.record("updateDB:" + kind.rawValue)
    }
}
final class InstalledExtension {
    let bundleIdentifier = "unused"
    func update(provisioningProfile: ALTProvisioningProfile) {}
}
final class ALTApplication { let name = "FixtureApp" }
final class ALTProvisioningProfile {
    let data: Data
    init(_ data: Data) { self.data = data }
}
extension Bundle {
    enum Info {
        static var activeBundleURL: URL {
            URL(fileURLWithPath: ProcessInfo.processInfo.environment["RENEWAL_INTEGRATION_ROOT"]!).appendingPathComponent("Fixture.app")
        }
    }
}
class BasePipelineOperation<C, R>: @unchecked Sendable {
    let context: C
    let progress = Progress(totalUnitCount: 100)
    init(context: C) { self.context = context }
    func execute(parentProgress: Progress?) async throws -> R { fatalError("override") }
    func executePreconditionCheck(parentProgress: Progress?) async throws { try Task.checkCancellation() }
    func setProgress(_ value: Int64) { progress.completedUnitCount = value }
}
final class InstallAppOperationContext: @unchecked Sendable {
    let bundleIdentifier: String
    let targetBundleIdentifier: String
    let provisioningProfiles: [String: ALTProvisioningProfile]?
    let targetAppBundle: ALTApplication? = ALTApplication()
    let isCellularRefreshGroup = false
    let preserveCurrentNetwork: Bool
    let sharedContext: SharedPipelineContext
    let installedApp: InstalledApp?
    let targetCertStatus: String? = nil
    let dbBackgroundContext: NSManagedObjectContext
    let beforeProfileInstallation: (@Sendable (String, [Data]) async throws -> Void)?
    init(app: InstalledApp, group: RefreshGroup) throws {
        bundleIdentifier = app.bundleIdentifier
        targetBundleIdentifier = app.bundleIdentifier
        provisioningProfiles = [app.bundleIdentifier: ALTProvisioningProfile(try DriverFixture.shared.preparedData(app.kind))]
        preserveCurrentNetwork = group.preserveCurrentNetwork
        sharedContext = group.sharedContext
        installedApp = app
        dbBackgroundContext = group.dbContext
        beforeProfileInstallation = group.beforeProfileInstallation
    }
}
final class CellularRefreshManager {
    static let shared = CellularRefreshManager()
    func turnOffDataIfNeeded() async { DriverFixture.shared.record("FORBIDDEN_CELLULAR_OFF") }
    func turnOnDataIfNeeded() async { DriverFixture.shared.record("FORBIDDEN_CELLULAR_ON") }
}

enum CompletionPolicy { case normal, missing, duplicate, wrongIdentifier }
actor DriverGate {
    private var entered = false
    private var released = false
    private var entryWaiters: [CheckedContinuation<Void, Never>] = []
    private var nativeWaiter: CheckedContinuation<Void, Never>?
    func waitUntilEntered() async {
        if entered { return }
        await withCheckedContinuation { entryWaiters.append($0) }
    }
    func enter() async {
        entered = true
        entryWaiters.forEach { $0.resume() }; entryWaiters.removeAll()
        if released { return }
        await withCheckedContinuation { nativeWaiter = $0 }
    }
    func release() { released = true; nativeWaiter?.resume(); nativeWaiter = nil }
}

final class DriverFixture: @unchecked Sendable {
    static let shared = DriverFixture()
    private let lock = NSLock()
    private var _apps: [InstalledApp] = []
    private var _prepared: [RenewalApp: Data] = [:]
    private var _installed: [RenewalApp: Data] = [:]
    private var _events: [String] = []
    private var _gate: DriverGate?
    private var _failInstall = false
    private var _wrongReadbackPath = false
    private var _completion = CompletionPolicy.normal
    private var _wifi = true
    private var _namespace = "not-configured"
    private var _failInstallApp: RenewalApp?
    var apps: [InstalledApp] { lock.withLock { _apps } }
    var events: [String] { lock.withLock { _events } }
    var gate: DriverGate? { lock.withLock { _gate } }
    var failInstall: Bool { lock.withLock { _failInstall } }
    var completion: CompletionPolicy { lock.withLock { _completion } }
    var wifi: Bool { lock.withLock { _wifi } }
    var wrongReadbackPath: Bool { lock.withLock { _wrongReadbackPath } }
    var namespace: String { lock.withLock { _namespace } }
    let certificate = Data("synthetic DER fixture certificate".utf8)
    func configure(gate: DriverGate? = nil, failInstall: Bool = false,
                   completion: CompletionPolicy = .normal, wrongReadbackPath: Bool = false, wifi: Bool = true,
                   failInstallApp: RenewalApp? = nil) throws {
        var profiles: [RenewalApp: Data] = [:]
        var apps: [InstalledApp] = []
        for kind in RenewalApp.executionOrder {
            let original = kind == .rustDesk ? "com.bearberni.rustdesk.v2" : "com.SideStore.SideStore"
            let installed = original + ".85TZVFJX88"
            apps.append(InstalledApp(kind, original: original, installed: installed))
            profiles[kind] = try PropertyListSerialization.data(fromPropertyList: [
                "UUID": UUID().uuidString, "TeamIdentifier": ["85TZVFJX88"],
                "ApplicationIdentifierPrefix": ["85TZVFJX88"],
                "Entitlements": ["application-identifier": "85TZVFJX88." + installed,
                    "com.apple.developer.team-identifier": "85TZVFJX88"],
                "DeveloperCertificates": [certificate],
                "CreationDate": Date().addingTimeInterval(-60),
                "ExpirationDate": Date().addingTimeInterval(604800)
            ], format: .xml, options: 0)
        }
        lock.withLock {
            _apps = apps; _prepared = profiles; _installed = [:]; _events = []
            _gate = gate; _failInstall = failInstall; _completion = completion
            _wrongReadbackPath = wrongReadbackPath; _wifi = wifi
            _namespace = UUID().uuidString; _failInstallApp = failInstallApp
        }
    }
    func app(_ kind: RenewalApp) -> InstalledApp { lock.withLock { _apps.first { $0.kind == kind }! } }
    func target(_ kind: RenewalApp) -> RenewalTarget {
        let record = app(kind)
        return RenewalTarget(app: kind, originalBundleIdentifier: record.bundleIdentifier,
            installedBundleIdentifier: record.resignedBundleIdentifier, teamIdentifier: "85TZVFJX88",
            signingCertificateSHA256: SHA256.hash(data: certificate).map { String(format: "%02x", $0) }.joined(),
            installationFingerprint: "fixture-version-1")
    }
    func preparedData(_ kind: RenewalApp) throws -> Data { lock.withLock { _prepared[kind]! } }
    func record(_ event: String) { lock.withLock { _events.append(event) } }
    func installShouldFail(_ bytes: Data) -> Bool {
        lock.withLock { _failInstall || _prepared.first { $0.value == bytes }?.key == _failInstallApp }
    }
    func install(_ bytes: Data) {
        lock.withLock {
            let kind = _prepared.first { $0.value == bytes }!.key
            _installed[kind] = bytes
            _events.append("installed:" + kind.rawValue)
        }
    }
    func installedProfiles() -> [Data] { lock.withLock { Array(_installed.values) } }
}

final class AppManager: @unchecked Sendable {
