/// Only replaces the unavailable CryptoKit implementation; production digest caller stays exact.
enum SHA256 {
    static func hash(data: Data) -> [UInt8] {
        let process = Process()
        if FileManager.default.isExecutableFile(atPath: "/usr/bin/sha256sum") {
            process.executableURL = URL(fileURLWithPath: "/usr/bin/sha256sum")
        } else {
            process.executableURL = URL(fileURLWithPath: "/usr/bin/shasum")
            process.arguments = ["-a", "256"]
        }
        let input = Pipe(), output = Pipe()
        process.standardInput = input; process.standardOutput = output
        try! process.run()
        input.fileHandleForWriting.write(data)
        try! input.fileHandleForWriting.close()
        let result = output.fileHandleForReading.readDataToEndOfFile()
        process.waitUntilExit()
        precondition(process.terminationStatus == 0)
        let text = String(data: result, encoding: .utf8)!
        return stride(from: 0, to: 64, by: 2).map { index in
            let start = text.index(text.startIndex, offsetBy: index)
            return UInt8(text[start..<text.index(start, offsetBy: 2)], radix: 16)!
        }
    }
}

