actor NativeGate {
    private var entered = false
    private var released = false
    private var entering: [CheckedContinuation<Void, Never>] = []
    private var waiting: CheckedContinuation<Void, Never>?
    func waitUntilEntered() async {
        if entered { return }
        await withCheckedContinuation { entering.append($0) }
    }
    func enterAndWait() async {
        entered = true
        entering.forEach { $0.resume() }; entering.removeAll()
        if released { return }
        await withCheckedContinuation { waiting = $0 }
    }
    func release() {
        released = true
        waiting?.resume(); waiting = nil
    }
}

final class FixtureWorld: @unchecked Sendable {
    static let shared = FixtureWorld()
