    var databaseStarted: Bool { lock.withLock { _databaseStarted } }
    var events: [String] { lock.withLock { _events } }
    var gate: NativeGate? { lock.withLock { _gate } }
    var cancelled: Bool { lock.withLock { _cancelled } }
    var omitPrepared: Bool { lock.withLock { _omitPrepared } }
    var readFailure: Bool { lock.withLock { _readFailure } }
    func configure(databaseStarted: Bool = true, failNative: Set<RenewalApp> = [],
                   wrongReadback: Set<RenewalApp> = [], omitPrepared: Bool = false,
                   gate: NativeGate? = nil) {
        lock.withLock {
            _namespace = UUID().uuidString
            _databaseStarted = databaseStarted; _events = []; _failNative = failNative
            _wrongReadback = wrongReadback; _omitPrepared = omitPrepared
            _installed = [:]; _gate = gate; _cancelled = false; _readFailure = false
        }
    }
    func record(_ event: String) { lock.withLock { _events.append(event) } }
    func fail(_ app: RenewalApp) -> Bool { lock.withLock { _failNative.contains(app) } }
    func setFailures(_ apps: Set<RenewalApp>) { lock.withLock { _failNative = apps } }
    func setDatabaseStarted(_ started: Bool) { lock.withLock { _databaseStarted = started } }
    func setReadFailure(_ failed: Bool) { lock.withLock { _readFailure = failed } }
    func rotateJournalNamespaceKeepingDevice() { lock.withLock { _namespace = UUID().uuidString } }
    func clearGateAndCancellation() { lock.withLock { _gate = nil; _cancelled = false } }
    func cancel() { lock.withLock { _cancelled = true; _events.append("nativeCancellationRequested") } }
    func install(_ profile: ProfileEvidence, app: RenewalApp) { lock.withLock { _installed[app] = profile } }
    func installed(_ app: RenewalApp) -> ProfileEvidence? { lock.withLock { _installed[app] } }
