/// This is the explicit on-device boundary. It does not emulate driver or native pipeline internals.
actor RenewalNativeDriver: RenewalDeviceDriver {
    init(progress: Progress? = nil) {}
    func resolveTargets() async throws -> [RenewalTarget] {
        FixtureWorld.shared.record("resolveTargets")
        return fixtureTargets
    }
    func readDeviceProfiles(target: RenewalTarget) async throws -> DeviceProfileObservation {
        let world = FixtureWorld.shared
        world.record("read:" + target.app.rawValue)
        if world.readFailure { throw NSError(domain: "FixtureDeviceReadUnavailable", code: 61) }
        let installed = world.installed(target.app)
        let profile = installed != nil && world.wrong(target.app)
            ? fixtureProfile(target, suffix: "-wrong")
            : installed ?? fixtureProfile(target, suffix: "-old")
        return DeviceProfileObservation(target: target, profiles: [profile],
            applicationPresenceConfirmed: true, observedAt: Date())
    }
    func refreshNative(target: RenewalTarget,
                       beforeInstall: @escaping @Sendable (PreparedProfileSet) async throws -> Void)
        async throws -> NativeRefreshCompletion {
        let world = FixtureWorld.shared
        world.record("begin:" + target.app.rawValue)
        let operationID = UUID().uuidString
        let profile = fixtureProfile(target, suffix: "-new")
        if !world.omitPrepared {
            try await beforeInstall(PreparedProfileSet(operationID: operationID, target: target,
                mainProfileUUID: profile.uuid, profiles: [profile]))
        }
        if let gate = world.gate { await gate.enterAndWait() }
        if world.cancelled {
            world.record("endCancelled:" + target.app.rawValue)
            throw CancellationError()
        }
        if world.fail(target.app) {
            world.record("endFailed:" + target.app.rawValue)
            throw NSError(domain: "FixtureNative", code: 44,
                userInfo: [NSLocalizedDescriptionKey: "PRIVATE_ACCOUNT_MATERIAL_MUST_NOT_ESCAPE"])
        }
        world.install(profile, app: target.app)
        world.record("end:" + target.app.rawValue)
        return NativeRefreshCompletion(operationID: operationID, target: target, completedAt: Date())
    }
    func requestNativeCancellation() async { FixtureWorld.shared.cancel() }
}

