final class NetworkContractTests: XCTestCase {
    override func setUpWithError() throws { try DriverFixture.shared.configure() }

    private func pending(target: NetworkRestoreTarget? = nil) async throws -> (RenewalEngine, String) {
        let engine = try RenewalEngine(storage: NetworkStorage())
        let targets = try await ActualDriver.RenewalNativeDriver().resolveTargets()
        guard case .ready(let plan) = try await engine.prepare(mode: .manual, targets: targets,
            networkRestoreTarget: target, workflowOwnerID: networkOwner) else { throw NSError(domain: "MissingPlan", code: 1) }
        let run = try await engine.beginNetworkChange(plan)
        try await engine.requestCancellation(runID: run.id, workflowOwnerID: networkOwner)
        return (engine, run.id)
    }

    func testOnDemandMismatchOrMissingObservationKeepsRealRecoveryObligationPending() async throws {
        let target = NetworkRestoreTarget(quantumultX: .connected, localDevVPN: .notConnected,
            quantumultXOnDemand: true, localDevVPNOnDemand: false)
        let (engine, id) = try await pending(target: target)
        try await engine.recordRestorationRequestAccepted(runID: id, workflowOwnerID: networkOwner)
        for onDemand in [Bool?.none, false] {
            do {
                try await engine.confirmNetworkRestored(runID: id,
                    observation: NetworkRestorationObservation(quantumultX: .connected, localDevVPN: .notConnected,
                        source: .systemShortcutVPNQuery, observedAt: Date(),
                        quantumultXOnDemand: onDemand, localDevVPNOnDemand: false), workflowOwnerID: networkOwner)
                XCTFail("missing/mismatched On Demand must not clear recovery")
            } catch { XCTAssertEqual(error as? RenewalCoreError, .networkRestorationUnverified) }
            let snapshot = await engine.snapshot()
            XCTAssertTrue(snapshot.current!.networkRecovery.isPending)
            XCTAssertEqual(snapshot.current?.phase, .awaitingNetworkRestoration)
        }
        try await engine.confirmNetworkRestored(runID: id,
            observation: NetworkRestorationObservation(quantumultX: .connected, localDevVPN: .notConnected,
                source: .systemShortcutVPNQuery, observedAt: Date(),
                quantumultXOnDemand: true, localDevVPNOnDemand: false), workflowOwnerID: networkOwner)
        let snapshot = await engine.snapshot()
        XCTAssertFalse(snapshot.current!.networkRecovery.isPending)
        XCTAssertEqual(snapshot.current?.networkRecovery.restoredObservation?.source.rawValue, "systemShortcutVPNQuery")
        XCTAssertEqual(snapshot.current?.networkRecovery.restoredObservation?.localDevVPN.rawValue, "notConnected")
        XCTAssertFalse(snapshot.current!.fullyCompleted)
    }

    func testFailedVPNActionDoesNotStartCooldownOrOverwritePendingTask() async throws {
        let (engine, id) = try await pending()
        // A failed Set VPN action has no accepted-request receipt to persist.
        let before = await engine.snapshot()
        XCTAssertNil(before.current?.networkRecovery.requestAcceptedAt)
        let targets = try await ActualDriver.RenewalNativeDriver().resolveTargets()
        for mode in [RenewalMode.manual, .automatic] {
            let preparation = try await engine.prepare(mode: mode, targets: targets, workflowOwnerID: networkOwner)
            XCTAssertEqual(preparation, .recoveryRequired(runID: id))
        }
        // Immediate same-entry recovery is allowed once the action can run again.
        try await engine.recordRestorationRequestAccepted(runID: id, workflowOwnerID: networkOwner)
        try await engine.confirmNetworkRestored(runID: id,
            observation: NetworkRestorationObservation(quantumultX: .connected, localDevVPN: .notConnected,
                source: .systemShortcutVPNQuery, observedAt: Date()), workflowOwnerID: networkOwner)
        guard case .ready = try await engine.prepare(mode: .manual, targets: targets, workflowOwnerID: networkOwner) else {
            return XCTFail("manual entry must be retryable immediately after recovery")
        }
    }

    func testActionReturnFixedDelayAndStaleQueryCannotBecomeNetworkProof() async throws {
        let (engine, id) = try await pending()
        try await engine.recordRestorationRequestAccepted(runID: id, workflowOwnerID: networkOwner)
        for (source, date) in [
            (NetworkObservationSource.actionReturned, Date()),
