private func workflowJSON(_ text: String) throws -> [String: Any] {
    try XCTUnwrap(JSONSerialization.jsonObject(with: Data(text.utf8)) as? [String: Any])
}
private func systemObservation(qx: Bool = true, ld: Bool = false, qxOnDemand: Bool = true,
                               ldOnDemand: Bool = false, source: String = "systemShortcutVPNQuery",
                               when: Date = Date(), extraCurrent: [String] = [],
                               qxName: String = "Quantumult X", ldName: String = "LocalDevVPN") throws -> String {
    let formatter = ISO8601DateFormatter()
    formatter.formatOptions = [.withInternetDateTime, .withFractionalSeconds]
    let packet: [String: Any] = [
        "schemaVersion": 1, "source": source, "observedAt": formatter.string(from: when),
        "quantumultX": ["name": qxName, "connected": qx, "onDemand": qxOnDemand],
        "localDevVPN": ["name": ldName, "connected": ld, "onDemand": ldOnDemand],
        "currentVPNNames": (qx ? [qxName] : []) + (ld ? [ldName] : []) + extraCurrent
    ]
    return String(data: try JSONSerialization.data(withJSONObject: packet), encoding: .utf8)!
}

