import Foundation
import XCTest
import RenewalCore
@testable import ActualStack

/// One module compiles the actual service + driver + refresh methods together.
/// Only platform/FFI/context boundaries are fixtures; no substitute coordinator is used.
final class WorkflowStackTests: XCTestCase {
    private var owner = UUID().uuidString
    override func setUpWithError() throws { owner = UUID().uuidString; try DriverFixture.shared.configure() }
    private func object(_ text: String) throws -> [String: Any] {
        try XCTUnwrap(JSONSerialization.jsonObject(with: Data(text.utf8)) as? [String: Any])
    }
    private func observation() throws -> String {
        let formatter = ISO8601DateFormatter()
        formatter.formatOptions = [.withInternetDateTime, .withFractionalSeconds]
        return String(data: try JSONSerialization.data(withJSONObject: [
            "schemaVersion": 1, "source": "systemShortcutVPNQuery", "observedAt": formatter.string(from: Date()),
            "quantumultX": ["name": "Quantumult X", "connected": true, "onDemand": true],
            "localDevVPN": ["name": "LocalDevVPN", "connected": false, "onDemand": false],
            "currentVPNNames": ["Quantumult X"]
        ]), encoding: .utf8)!
    }
    private func prepare(_ service: PersonalRenewalService) async throws -> String {
        let value = try object(await service.prepareWorkflowJSON(mode: .manual, observationJSON: observation(), workflowOwnerID: owner))
        XCTAssertEqual(value["status"] as? String, "workflowPrepared")
        return try XCTUnwrap(value["runID"] as? String)
    }
    private func finish(_ service: PersonalRenewalService, id: String) async throws -> [String: Any] {
        _ = await service.recordRestorationRequestJSON(runID: id, workflowOwnerID: owner)
        return try object(await service.confirmRestorationJSON(runID: id, observationJSON: observation(), workflowOwnerID: owner))
    }

    func testEntireActualServiceDriverCoreRefreshStackAndJSONProtocol() async throws {
        let service = PersonalRenewalService()
        let id = try await prepare(service)
        XCTAssertFalse(DriverFixture.shared.events.contains("minimuxerProbe"))
        let native = try object(await service.executeWorkflowJSON(runID: id, recovering: false,
            progress: Progress(totalUnitCount: 0), control: RenewalInvocationControl(), workflowOwnerID: owner))
        XCTAssertEqual(native["restoreAllowed"] as? Bool, true)
        XCTAssertEqual(native["workflowCompleted"] as? Bool, false)
        let apps = try XCTUnwrap(native["apps"] as? [[String: Any]])
        XCTAssertEqual(apps.map { $0["state"] as? String }, ["verified", "verified"])
        let events = DriverFixture.shared.events
        XCTAssertLessThan(try XCTUnwrap(events.firstIndex(of: "updateDB:rustDesk")),
                          try XCTUnwrap(events.firstIndex(of: "pipelineRefresh:sideStore")))
        XCTAssertTrue(events.contains("runningSelfSource"))
        XCTAssertFalse(events.contains { $0.hasPrefix("FORBIDDEN_CELLULAR") })
        let completed = try await finish(service, id: id)
        XCTAssertEqual(completed["workflowCompleted"] as? Bool, true)
        XCTAssertEqual(completed["status"] as? String, "workflowVerified")
    }

    func testEntireActualStackRetainsFirstAppSuccessWhenSecondNativeFFIFails() async throws {
        try DriverFixture.shared.configure(failInstallApp: .sideStore)
        let service = PersonalRenewalService()
        let id = try await prepare(service)
        let nativeText = await service.executeWorkflowJSON(runID: id, recovering: false,
            progress: Progress(totalUnitCount: 0), control: RenewalInvocationControl(), workflowOwnerID: owner)
        let native = try object(nativeText)
        let apps = try XCTUnwrap(native["apps"] as? [[String: Any]])
        XCTAssertEqual(apps.map { $0["state"] as? String }, ["verified", "failed"])
        XCTAssertTrue(nativeText.contains("FixtureInstallFFI"))
        XCTAssertEqual(native["restoreAllowed"] as? Bool, true)
        let restored = try await finish(service, id: id)
        XCTAssertEqual(restored["networkRecoveryPending"] as? Bool, false)
        XCTAssertEqual(restored["workflowCompleted"] as? Bool, false)
    }

    func testEntireActualStackCancellationDoesNotRestoreBeforeConcreteNativeFFIReturns() async throws {
        let gate = DriverGate()
        try DriverFixture.shared.configure(gate: gate)
        let service = PersonalRenewalService()
        let id = try await prepare(service)
        let task = Task {
            await service.executeWorkflowJSON(runID: id, recovering: false,
                progress: Progress(totalUnitCount: 0), control: RenewalInvocationControl(), workflowOwnerID: owner)
        }
        await gate.waitUntilEntered()
        let cancel = try object(await service.cancelJSON(workflowOwnerID: owner))
        XCTAssertEqual(cancel["nativeWorkerDrained"] as? Bool, false)
        XCTAssertEqual(cancel["restoreAllowed"] as? Bool, false)
        XCTAssertFalse(DriverFixture.shared.events.contains("installed:rustDesk"))
        await gate.release()
        let drained = try object(await task.value)
        XCTAssertEqual(drained["nativeWorkerDrained"] as? Bool, true)
        XCTAssertEqual(drained["restoreAllowed"] as? Bool, true)
        XCTAssertTrue(DriverFixture.shared.events.contains("installed:rustDesk"))
        XCTAssertFalse(DriverFixture.shared.events.contains("pipelineRefresh:sideStore"))
        let restored = try await finish(service, id: id)
        XCTAssertEqual(restored["workflowCompleted"] as? Bool, false)
    }
}

