private final class DriverMemoryStorage: RenewalJournalStorage, @unchecked Sendable {
    let ownershipKey = UUID().uuidString
    private let lock = NSLock()
    private var bytes: Data?
    func load() throws -> Data? { lock.withLock { bytes } }
    func save(_ data: Data) throws { lock.withLock { bytes = data } }
}

final class DriverTests: XCTestCase {
    override func setUpWithError() throws { try DriverFixture.shared.configure() }

    func testActualDriverRefreshOperationAndDeviceParserFeedRealCoreSerially() async throws {
        let driver = ActualDriver.RenewalNativeDriver()
        let targets = try await driver.resolveTargets()
        let engine = try RenewalEngine(storage: DriverMemoryStorage())
        guard case .ready(let plan) = try await engine.prepare(mode: .manual, targets: targets, networkPolicy: .keepCurrent) else {
            return XCTFail("missing native plan")
        }
        let run = try await engine.beginNativeOnly(plan)
        let result = try await engine.execute(runID: run.id, driver: driver)
        XCTAssertTrue(result.run.nativeValidationCompleted)
        XCTAssertFalse(result.run.fullyCompleted)
        XCTAssertEqual(result.run.attempts.map(\.state), [.verified, .verified])
        let events = DriverFixture.shared.events
        XCTAssertEqual(events.filter { $0.hasPrefix("pipelineRefresh:") }, ["pipelineRefresh:rustDesk", "pipelineRefresh:sideStore"])
        XCTAssertEqual(events.filter { $0 == "preserveNetwork" }.count, 2)
        XCTAssertTrue(events.contains("runningSelfSource"))
        XCTAssertFalse(events.contains { $0.hasPrefix("FORBIDDEN_CELLULAR") })
        XCTAssertLessThan(try XCTUnwrap(events.firstIndex(of: "updateDB:rustDesk")),
                          try XCTUnwrap(events.firstIndex(of: "pipelineRefresh:sideStore")))
