        } catch {
            XCTAssertEqual((error as NSError).domain, "FixtureDurableWriteFailure")
        }
        XCTAssertFalse(DriverFixture.shared.events.contains("installEntered"))
        XCTAssertFalse(DriverFixture.shared.events.contains("updateDB:rustDesk"))
    }

    func testActualNativeInstallFailurePreservesErrorAndNeverUpdatesDatabase() async throws {
        try DriverFixture.shared.configure(failInstall: true)
        let driver = ActualDriver.RenewalNativeDriver()
        do {
            _ = try await driver.refreshNative(target: DriverFixture.shared.target(.rustDesk)) { _ in }
            XCTFail("native FFI failure must propagate")
        } catch {
            XCTAssertEqual((error as NSError).domain, "FixtureInstallFFI")
            XCTAssertEqual((error as NSError).code, 91)
        }
        XCTAssertTrue(DriverFixture.shared.events.contains("installEntered"))
        XCTAssertFalse(DriverFixture.shared.events.contains("updateDB:rustDesk"))
    }

    func testActualNativeCompletionRejectsMissingDuplicateAndWrongIdentifierCallbacks() async throws {
        for policy in [CompletionPolicy.missing, .duplicate, .wrongIdentifier] {
            try DriverFixture.shared.configure(completion: policy)
            let driver = ActualDriver.RenewalNativeDriver()
            do {
                _ = try await driver.refreshNative(target: DriverFixture.shared.target(.rustDesk)) { _ in }
                XCTFail("invalid native callback must fail")
            } catch {
                XCTAssertTrue(error.localizedDescription.contains("invalidNativeCompletion"))
            }
        }
    }

    func testActualDeviceReadbackRejectsWrongDumpRoot() async throws {
        try DriverFixture.shared.configure(wrongReadbackPath: true)
        let driver = ActualDriver.RenewalNativeDriver()
        do {
            _ = try await driver.readDeviceProfiles(target: DriverFixture.shared.target(.rustDesk))
            XCTFail("wrong profile dump root must fail")
        } catch {
            XCTAssertTrue(error.localizedDescription.contains("profileReadbackIncomplete"))
        }
    }

    func testActualDriverCancellationStillJoinsNativeFFIBeforeReturnAndPreservesLateSuccess() async throws {
        let gate = DriverGate()
        try DriverFixture.shared.configure(gate: gate)
        let driver = ActualDriver.RenewalNativeDriver()
        let target = DriverFixture.shared.target(.rustDesk)
        let task = Task { try await driver.refreshNative(target: target) { _ in } }
        await gate.waitUntilEntered()
        await driver.requestNativeCancellation()
        XCTAssertFalse(DriverFixture.shared.events.contains("installed:rustDesk"))
        XCTAssertFalse(DriverFixture.shared.events.contains("updateDB:rustDesk"))
        await gate.release()
        let completion = try await task.value
        XCTAssertEqual(completion.target, target)
        XCTAssertTrue(DriverFixture.shared.events.contains("installed:rustDesk"))
        XCTAssertTrue(DriverFixture.shared.events.contains("updateDB:rustDesk"))
    }

    func testActualDriverRejectsConcurrentNativeCallUntilFirstJoins() async throws {
        let gate = DriverGate()
        try DriverFixture.shared.configure(gate: gate)
        let driver = ActualDriver.RenewalNativeDriver()
        let first = Task { try await driver.refreshNative(target: DriverFixture.shared.target(.rustDesk)) { _ in } }
        await gate.waitUntilEntered()
        do {
            _ = try await driver.refreshNative(target: DriverFixture.shared.target(.sideStore)) { _ in }
            XCTFail("overlap must fail")
        } catch {
            XCTAssertTrue(error.localizedDescription.contains("operationAlreadyActive"))
        }
        await gate.release()
        _ = try await first.value
    }

    func testActualDriverRefusesWiFiLossBeforeAnyInstall() async throws {
        try DriverFixture.shared.configure(wifi: false)
        let driver = ActualDriver.RenewalNativeDriver()
        do {
            _ = try await driver.refreshNative(target: DriverFixture.shared.target(.rustDesk)) { _ in }
            XCTFail("WiFi loss must fail")
        } catch {
            XCTAssertTrue(error.localizedDescription.contains("currentWiFiRequired"))
        }
        XCTAssertFalse(DriverFixture.shared.events.contains("installEntered"))
    }
}

