"""Shared extraction of production methods; no product/build-recipe implementation."""
def driver_sources(read):
    driver = read("SideStore/Core/RenewalNativeDriver.swift")
    driver = driver[driver.index("/// Personal renewal"):]
    begin = driver.index("    private static func resolve(app kind:")
    end = driver.index("    private static func confirmDeviceIdentity", begin)
    driver = driver[:begin] + '''    private static func resolve(app kind: RenewalApp, in context: NSManagedObjectContext) throws -> TargetRecord {
        let app = DriverFixture.shared.app(kind)
        let target = DriverFixture.shared.target(kind)
        return TargetRecord(app: app, target: target,
            allowedBundleIdentifiers: Set([target.installedBundleIdentifier]),
            requiredProfileBundleIdentifiers: Set([target.installedBundleIdentifier]))
    }

''' + driver[end:]
    result = {"ActualDriver.swift": "import Foundation\nimport RenewalCore\n\n" + driver}
    for name, path in {
        "ActualRefreshGroup.swift": "SideStore/Core/Operations/RefreshGroup.swift",
        "ActualRefreshAppOperation.swift": "SideStore/Core/Operations/PipelineOperations/RefreshAppOperation.swift",
    }.items():
        content = read(path)
        content = "\n".join(line for line in content.splitlines() if not line.startswith("import "))
        result[name] = "import Foundation\nimport CoreFoundation\nimport RenewalCore\n\n" + content + "\n"
    content = read("AltStore/Managing Apps/AppManager.swift")
    begin = content.index("    @discardableResult\n    func refresh(_ installedApps:")
    end = content.index("    func activate(", begin)
    result["ActualAppManagerRefresh.swift"] = "import Foundation\nextension AppManager {\n" + content[begin:end] + "}\n"
    return result

#!/usr/bin/env python3
"""Read a built IPA's own AppIntents JSON and check the new workflow contract.

This never installs/runs the IPA and does not assert the phone's resigned action ID.
"""
from __future__ import annotations

import argparse
import hashlib
import json
from pathlib import Path
import plistlib
import zipfile

WORKFLOW_CASES = {"newWorkflowOwner", "prepareWorkflow", "executeWorkflow", "recoverWorkflow",
                  "recordRestorationRequest", "confirmRestoration"}
TYPED = {"quantumultXName", "localDevVPNName", "quantumultXConnected", "localDevVPNConnected",
         "quantumultXOnDemand", "localDevVPNOnDemand", "currentVPNNames", "observationDate"}


def check(data):
    errors = []
    intent = data.get("actions", {}).get("PersonalRenewalIntent", {})
    if not intent:
        errors.append("PersonalRenewalIntent not in compiled metadata")
    names = {p.get("name") for p in intent.get("parameters", [])}
    if names != {"action", "runID", "mode", "networkObservation", "workflowOwnerID", "allowRecoveryTakeover"} | TYPED:
        errors.append("compiled parameter names differ from workflow contract")
    enums = {e.get("identifier"): e for e in data.get("enums", [])}
    action_cases = {c.get("identifier") for c in enums.get("PersonalRenewalAction", {}).get("cases", [])}
    if not WORKFLOW_CASES <= action_cases:
        errors.append("compiled PersonalRenewalAction lacks workflow cases")
    mode_cases = {c.get("identifier") for c in enums.get("PersonalRenewalMode", {}).get("cases", [])}
    if mode_cases != {"manual", "automatic"}:
        errors.append("compiled trigger-mode cases differ")
    protocols = intent.get("systemProtocols", [])
    for protocol in ("LongRunning", "Cancellable"):
        if "com.apple.link.systemProtocol." + protocol not in protocols:
            errors.append("compiled intent lacks " + protocol)
    return {"valid": not errors, "errors": errors, "parameters": sorted(names),
            "actionCases": sorted(action_cases), "modeCases": sorted(mode_cases),
            "allowedTargets": intent.get("allowedTargets"),
            "supportedModes": intent.get("supportedModes"),
            "boundary": "compiled metadata only; not installed/resigned identity or runtime binding"}


def check_ipa(path):
    with zipfile.ZipFile(path) as archive:
        infos = [n for n in archive.namelist() if n.startswith("Payload/") and n.count("/") == 2 and n.endswith(".app/Info.plist")]
        if len(infos) != 1:
            raise ValueError("expected exactly one main app Info.plist")
        root = infos[0].removesuffix("Info.plist")
        info = plistlib.loads(archive.read(infos[0]))
        result = check(json.loads(archive.read(root + "Metadata.appintents/extract.actionsdata")))
    result.update({"ipaSHA256": hashlib.sha256(path.read_bytes()).hexdigest(),
                   "compiledBundleIdentifier": info.get("CFBundleIdentifier"), "build": info.get("CFBundleVersion")})
    return result


def main():
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument("ipa", type=Path)
    p.add_argument("--output", type=Path)
    args = p.parse_args()
    result = check_ipa(args.ipa)
    text = json.dumps(result, ensure_ascii=False, indent=2) + "\n"
    if args.output:
        args.output.parent.mkdir(parents=True, exist_ok=True)
        args.output.write_text(text, encoding="utf-8")
    print(text)
    raise SystemExit(0 if result["valid"] else 1)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Check field evidence in the read-only Apple ToolKit probe's JSON, without actions.

An unavailable/empty catalog is UNVERIFIED, never a successful capability check.
This checks action/parameter/property identities and associations, not the whole
undocumented plist archive grammar or actual installed workflow execution.
"""
from __future__ import annotations

import argparse
import base64
import json
from pathlib import Path
import plistlib

EXPECTED = {
    "is.workflow.actions.vpn.get": set(),
    "is.workflow.actions.filter.vpns": {"WFContentItemInputParameter", "WFContentItemFilter"},
    "is.workflow.actions.vpn.set": {"WFVPN", "WFVPNOperation", "WFOnDemandValue"},
    "is.workflow.actions.count": {"WFCountType", "Input"},
    "is.workflow.actions.getitemfromlist": {"WFItemSpecifier", "WFInput"},
    "is.workflow.actions.output": {"WFOutput"},
}
PROPERTIES = {"Name", "Is Connected", "Is On Demand Enabled"}
VPN_TYPE_IDS = {"WFVPNContentItem", "com.apple.shortcuts.WFVPNContentItem"}
ENUMS = {
    "com.apple.shortcuts.is.workflow.actions.vpn.set.WFVPNOperation": {"Connect", "Disconnect", "Set On Demand"},
    "com.apple.shortcuts.is.workflow.actions.filter.vpns.WFContentItemInputParameter": {"Library"},
}


def strings(value):
    if isinstance(value, str):
        yield value
    elif isinstance(value, list):
        for item in value:
            yield from strings(item)
    elif isinstance(value, dict):
        # Probe encodes binary fields as base64. Decode only data formats, never code.
        encoded = value.get("base64")
        if isinstance(encoded, str):
            try:
                blob = base64.b64decode(encoded, validate=True)
                parsed = plistlib.loads(blob) if blob.startswith((b"bplist", b"<?xml")) else json.loads(blob)
                yield from strings(parsed)
            except (ValueError, TypeError, plistlib.InvalidFileException, UnicodeDecodeError):
                pass
        for key, item in value.items():
            yield key
            if key != "base64":
                yield from strings(item)


def property_is_vpn_owned(table, row, db, depth=0):
    if VPN_TYPE_IDS & set(strings(row)):
        return True
    if depth >= 3:
        return False
    records = db.get("records", {})
    for fk in db.get("foreignKeys", {}).get(table, []):
        parent = fk.get("table")
        value = row.get(fk.get("from"))
        parent_key = fk.get("to")
        if not parent_key:
            primary = [c["name"] for c in db.get("columns", {}).get(parent, []) if c.get("pk")]
            if len(primary) != 1:
                continue
            parent_key = primary[0]
        if value is not None:
            for candidate in records.get(parent, []):
                if candidate.get(parent_key) == value and property_is_vpn_owned(parent, candidate, db, depth+1):
                    return True
    return False


def check(report):
    action_found = {key: False for key in EXPECTED}
    parameters = {key: set() for key in EXPECTED}
    properties = set()
    enum_cases = {key: set() for key in ENUMS}
    sources = []
    for db in report.get("databases", []):
        if db.get("status") != "read":
            continue
        sources.append({key: db.get(key) for key in ("resolvedPath", "sourceSha256Before", "sourceSha256After")})
        for action, expected in EXPECTED.items():
            rows = db.get("targetActions", {}).get(action, [])
            if any(action in set(strings(row)) for row in rows):
                action_found[action] = True
                # Only metadata explicitly linked to this exact action is evidence.
                linked = set(strings(db.get("linkedActionMetadata", {}).get(action, {})))
                parameters[action] |= expected & linked
        for table, rows in db.get("records", {}).items():
            if "propert" not in table.lower():
                continue
            for row in rows:
                labels = PROPERTIES & set(strings(row))
                if labels and property_is_vpn_owned(table, row, db):
                    properties |= labels
        for row in db.get("records", {}).get("EnumerationCases", []):
            if row.get("typeId") in ENUMS and row.get("id") in ENUMS[row["typeId"]]:
                enum_cases[row["typeId"]].add(row["id"])
    missing = ["action:"+a for a, found in action_found.items() if not found]
    missing += ["parameter:"+a+":"+p for a in EXPECTED for p in sorted(EXPECTED[a] - parameters[a])]
    missing += ["vpnProperty:"+p for p in sorted(PROPERTIES - properties)]
    missing += ["enumCase:"+t+":"+c for t in ENUMS for c in sorted(ENUMS[t] - enum_cases[t])]
    fields_complete = not missing
    mac_source = bool(report.get("macOS")) and str(report.get("platform", "")).startswith(("Darwin", "macOS"))
    verified = fields_complete and mac_source and report.get("status") == "catalog_read"
    return {"status": "catalogFieldsVerified" if verified else "unverified", "verified": verified,
            "fieldsComplete": fields_complete, "macOSSource": mac_source, "missing": missing,
            "actionsFound": action_found, "linkedParametersFound": {a: sorted(p) for a, p in parameters.items()},
            "vpnOwnedPropertiesFound": sorted(properties), "sourceCatalogs": sources,
            "enumCasesFound": {t: sorted(cases) for t, cases in enum_cases.items()},
            "boundary": "catalog identities/field associations only; not archive grammar, signing, import or runtime"}


def main():
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument("probe_json", type=Path)
    p.add_argument("--output", type=Path)
    p.add_argument("--require-verified", action="store_true")
    args = p.parse_args()
    result = check(json.loads(args.probe_json.read_text(encoding="utf-8")))
    text = json.dumps(result, ensure_ascii=False, indent=2) + "\n"
    if args.output:
        args.output.parent.mkdir(parents=True, exist_ok=True)
        args.output.write_text(text, encoding="utf-8")
    print(text)
    raise SystemExit(2 if args.require_verified and not result["verified"] else 0)


if __name__ == "__main__":
    main()

