"""Execute the actual serialized action list with independent fake system boundaries.

This is not an iOS emulator: coercions, import, catalog IDs and UI binding still need
Apple validation. Throws/global stop terminate immediately and cannot run cleanup.
"""
from __future__ import annotations

import copy
from datetime import datetime, timedelta, timezone
import base64
import json
import plistlib
from pathlib import Path
import tempfile
import unittest
import uuid

from builder import Builder, Config, STD, TYPED_OBSERVATION, text_value, token, write_outputs
from validate import validate, walk
from check_appintents_metadata import check as check_metadata
from check_apple_catalog import check as check_catalog, EXPECTED as CATALOG_EXPECTED, PROPERTIES as CATALOG_PROPERTIES, ENUMS as CATALOG_ENUMS

CONFIG = Config("test.example.SideStore", "ABCDEFGHIJ", poll_count=3)


class HostStopped(Exception):
    pass


class Finished(Exception):
    def __init__(self, value):
        self.value = value


class System:
    def __init__(self, qx=True, local=False, qx_od=True, local_od=False):
        self.vpns = [{"Name": CONFIG.quantumult_name, "Is Connected": qx, "Is On Demand Enabled": qx_od},
                     {"Name": CONFIG.local_name, "Is Connected": local, "Is On Demand Enabled": local_od}]
        self.now = datetime(2026, 11, 19, 0, 0, 0, tzinfo=timezone.utc)
        self.events, self.set_count, self.fail_set = [], 0, None
        self.ignore_connect = False
        self.ignore_on_demand = False
        self.service = None
        self.cancel_alert = False
        self.on_alert = None

    def alert(self, params):
        self.events.append(("alert", params["WFAlertActionMessage"]))
        if self.on_alert:
            self.on_alert()
        if self.cancel_alert:
            raise HostStopped("user cancelled recovery confirmation; Shortcut stops")

    def current(self):
        return copy.deepcopy([v for v in self.vpns if v["Is Connected"]])

    def set(self, selected, op, on_demand):
        self.set_count += 1
        if self.fail_set == self.set_count:
            self.events.append(("systemThrow", self.set_count))
            raise HostStopped("Set VPN threw; no catch/finally exists")
        # Temporal monitor: independent from workflow branching logic.
        assert self.service.pending and self.service.durable_saved
        assert not self.service.worker_active
        if self.service.native_returned:
            assert self.service.restore_authorized
        matches = [v for v in self.vpns if v["Name"] == selected["Name"]]
        assert len(matches) == 1
        value = matches[0]
        if op == "Set On Demand":
            assert type(on_demand) is bool
            if not self.ignore_on_demand:
                value["Is On Demand Enabled"] = on_demand
        elif op == "Disconnect":
            value["Is Connected"] = False
        elif op == "Connect":
            if not self.ignore_connect:
                for other in self.vpns:
                    other["Is Connected"] = False
                value["Is Connected"] = True
        else:
            raise AssertionError(op)
        self.events.append(("set", value["Name"], op, on_demand))


class Service:
    def __init__(self, system):
        self.system = system
        system.service = self
        self.pending = self.durable_saved = self.restore_authorized = False
        self.worker_active = self.native_returned = self.request_recorded = False
        self.run_id, self.target = "run-001", None
        self.calls, self.observations = [], []
        self.parameter_calls, self.owner_calls = [], []
        self.owner_id = None
        self.skip = self.busy = self.partial = self.cancelled = False
        self.fail_prepare = self.drain_false = self.deny_restore = False
        self.wrong_run = self.wrong_schema = self.throw_native = self.fail_record = False
        self.complete = False

    def reply(self, next_step="restore", **changes):
        r = {"schemaVersion": 2, "status": "partial" if self.partial else "verified",
             "runID": self.run_id, "nextStep": next_step,
             "nativeWorkerDrained": not self.worker_active,
             "networkRecoveryPending": self.pending, "restoreAllowed": self.restore_authorized,
             "workflowCompleted": self.complete, "restoreTarget": self.target,
             "workflowOwnerID": self.owner_id,
             "apps": [{"app": "rustDesk", "state": "verified"},
                      {"app": "sideStore", "state": "failed" if self.partial else "verified"}],
             "summary": "部分续签已核验" if self.partial else "已处理本次任务"}
        r.update(changes)
        if next_step == "confirmRecovery":
            r["summary"] = "先停止上一条续签快捷指令，再手动继续恢复。"
        r["displaySummary"] = r["summary"] + "\nRustDesk V2：已核验\nSideStore：" + ("失败" if self.partial else "已核验")
        return json.dumps(r)

    def call(self, params):
        action = params["action"]
        self.parameter_calls.append(copy.deepcopy(params))
        if action == "newWorkflowOwner":
            assert "workflowOwnerID" not in params
            assert not (TYPED_OBSERVATION & params.keys())
            owner = str(uuid.uuid4())
            self.owner_calls.append(owner)
            return json.dumps({"schemaVersion": 2, "workflowOwnerID": owner})
        self.calls.append(action)
        caller_owner = params["workflowOwnerID"]
        uuid.UUID(caller_owner)
        if action != "prepareWorkflow" and caller_owner != self.owner_id:
            return self.reply("none", status="wrongOwner")
        if params["mode"] not in ("manual", "automatic"):
            return self.reply("none", status="invalidMode", runID=None)
        observation = None
        if action != "recordRestorationRequest":
            if any(type(params.get(p)) is not bool for p in ("quantumultXConnected", "localDevVPNConnected", "quantumultXOnDemand", "localDevVPNOnDemand")):
                return self.reply("none", status="invalidObservation", runID=None)
            if not isinstance(params.get("observationDate"), datetime):
                return self.reply("none", status="invalidObservation", runID=None)
            observation = {"quantumultX": {"name": params["quantumultXName"], "connected": params["quantumultXConnected"], "onDemand": params["quantumultXOnDemand"]},
                           "localDevVPN": {"name": params["localDevVPNName"], "connected": params["localDevVPNConnected"], "onDemand": params["localDevVPNOnDemand"]},
                           "currentVPNNames": params.get("currentVPNNames") or [], "observedAt": params["observationDate"]}
            expected = sorted(v["name"] for v in (observation["quantumultX"], observation["localDevVPN"]) if v["connected"])
            if sorted(observation["currentVPNNames"]) != expected:
                return self.reply("none", status="invalidObservation", runID=None if action == "prepareWorkflow" else self.run_id)
            self.observations.append(observation)
            assert abs((observation["observedAt"] - self.system.now).total_seconds()) <= 1
            for field, name in (("quantumultX", CONFIG.quantumult_name), ("localDevVPN", CONFIG.local_name)):
                actual = next(v for v in self.system.vpns if v["Name"] == name)
                assert observation[field]["connected"] == actual["Is Connected"]
                assert observation[field]["onDemand"] == actual["Is On Demand Enabled"]
            assert observation["currentVPNNames"] == [v["Name"] for v in self.system.current()]
        if action == "prepareWorkflow":
            assert params["runID"] == ""
            if self.fail_prepare:
                return self.reply("none", status="storageFailed", runID=None)
            if self.skip or self.busy:
                return self.reply("skip" if self.skip else "busy", status="skipped" if self.skip else "busy", runID=None)
            if self.pending:
                if any(self.target.get(k) is not None and self.target[k] != params[k] for k in ("quantumultXName", "localDevVPNName")):
                    return self.reply("none", status="savedRoleMismatch")
                if self.worker_active:
                    return self.reply("busy", status="busy")
                if caller_owner != self.owner_id:
                    if params["mode"] != "manual" or params.get("allowRecoveryTakeover") is not True:
                        return self.reply("confirmRecovery", status="confirmationRequired")
                    self.owner_id = caller_owner
                    self.system.events.append(("ownerTakenOver", caller_owner))
                self.native_returned = self.restore_authorized = False
                return self.reply("recover")
            self.target = {"quantumultX": "connected" if observation["quantumultX"]["connected"] else "notConnected",
                           "localDevVPN": "connected" if observation["localDevVPN"]["connected"] else "notConnected",
                           "quantumultXOnDemand": observation["quantumultX"]["onDemand"],
                           "localDevVPNOnDemand": observation["localDevVPN"]["onDemand"],
                           "quantumultXName": observation["quantumultX"]["name"],
                           "localDevVPNName": observation["localDevVPN"]["name"]}
            self.pending = self.durable_saved = True
            self.owner_id = caller_owner
            self.system.events.append(("durable", self.run_id))
            return self.reply("switchAndExecute")
        assert params["runID"] == self.run_id
        if action in ("executeWorkflow", "recoverWorkflow"):
            if action == "executeWorkflow":
                assert observation["quantumultX"]["connected"] is False
                assert observation["localDevVPN"]["connected"] is True
            self.system.events.append(("nativeStart", action))
            self.worker_active = True
            if self.throw_native:
                raise HostStopped("AppIntent host interruption; native result not received")
            self.worker_active = self.drain_false
            self.native_returned = True
            self.restore_authorized = not (self.drain_false or self.deny_restore)
            self.system.events.append(("nativeReturned", not self.worker_active))
            return self.reply(runID="other" if self.wrong_run else self.run_id,
                              schemaVersion=99 if self.wrong_schema else 2)
        if action == "recordRestorationRequest":
            assert self.restore_authorized and not self.worker_active
            if self.fail_record:
                return self.reply(status="infrastructureFailure")
            self.request_recorded = True
            self.system.events.append(("requestAccepted", self.system.set_count))
            return self.reply(status="restorationRequestRecorded")
        if action == "confirmRestoration":
            assert self.request_recorded and self.restore_authorized and not self.worker_active
            matches = True
            for field, od in (("quantumultX", "quantumultXOnDemand"), ("localDevVPN", "localDevVPNOnDemand")):
                matches &= observation[field]["connected"] == (self.target[field] == "connected")
                matches &= self.target[od] is None or observation[field]["onDemand"] == self.target[od]
            if matches:
                self.pending = False
                self.complete = not self.partial and not self.cancelled
                self.system.events.append(("cleared", self.run_id))
            return self.reply("none", workflowCompleted=self.complete)
        raise AssertionError(action)


class Interpreter:
    def __init__(self, workflow, system, service, shortcut_input=None, after_action=None):
        # Read a binary plist round trip, not a builder AST or stage sidecar.
        self.actions = plistlib.loads(plistlib.dumps(workflow))["WFWorkflowActions"]
        self.system, self.service, self.input = system, service, shortcut_input
        self.variables, self.outputs, self.ends = {}, {}, {}
        self.after_action = after_action
        stack = []
        for i, a in enumerate(self.actions):
            p = a["WFWorkflowActionParameters"]
            if "WFControlFlowMode" in p:
                if p["WFControlFlowMode"] == 0:
                    stack.append(i)
                elif p["WFControlFlowMode"] == 2:
                    start = stack.pop()
                    self.ends[start] = i

    def value(self, value):
        if not isinstance(value, dict):
            return value
        kind = value.get("WFSerializationType")
        if kind == "WFTextTokenAttachment":
            raw = value["Value"]
            if raw["Type"] == "Variable":
                v = self.variables.get(raw["VariableName"])
            elif raw["Type"] == "ExtensionInput":
                v = self.input
            else:
                v = self.outputs.get(raw["OutputUUID"])
            for property_ in raw.get("Aggrandizements", []):
                v = ([item.get(property_["PropertyName"]) for item in v] if isinstance(v, list)
                     else v.get(property_["PropertyName"]))
            return v
        if kind == "WFTextTokenString":
            raw = value["Value"]
            # Replace using UTF-16, as the actual file format does.
            data = raw["string"].encode("utf-16-le")
            for span, attachment in sorted(raw.get("attachmentsByRange", {}).items(), reverse=True,
                                           key=lambda kv: int(kv[0].split(",")[0][1:])):
                start, length = [int(x) for x in span.strip("{}").split(",")]
                resolved = self.value({"WFSerializationType": "WFTextTokenAttachment", "Value": attachment})
                replacement = "" if resolved is None else str(resolved)
                data = data[:start*2] + replacement.encode("utf-16-le") + data[(start+length)*2:]
            return data.decode("utf-16-le")
        return value

    def run_range(self, start, end):
        i = start
        while i < end:
            a = self.actions[i]
            aid, p = a["WFWorkflowActionIdentifier"], a["WFWorkflowActionParameters"]
            short = aid.removeprefix(STD)
            result = None
            if short == "conditional":
                v = self.value(p["WFInput"]["Variable"])
                condition = p["WFCondition"]
                target = self.value(p.get("WFNumberValue", p.get("WFConditionalActionString")))
                matches = {4: lambda: v == target, 5: lambda: v != target,
                           100: lambda: v is not None and v != "" and v != [],
                           101: lambda: v is None or v == "" or v == []}[condition]()
                if matches:
                    self.run_range(i + 1, self.ends[i])
                i = self.ends[i] + 1
                continue
            if short.startswith("repeat."):
                values = range(p["WFRepeatCount"]) if short == "repeat.count" else self.value(p["WFInput"])
                for item in values or []:
                    self.outputs[p["UUID"]] = item
                    self.run_range(i + 1, self.ends[i])
                i = self.ends[i] + 1
                continue
            if short == "gettext":
                result = self.value(p["WFTextActionText"])
            elif short == "setvariable":
                self.variables[p["WFVariableName"]] = self.value(p["WFInput"])
            elif short == "filter.vpns":
                name = p["WFContentItemFilter"]["Value"]["WFActionParameterFilterTemplates"][0]["String"]
                result = copy.deepcopy([v for v in self.system.vpns if v["Name"] == name])
            elif short == "count":
                result = len(self.value(p["Input"]))
            elif short == "getitemfromlist":
                result = self.value(p["WFInput"])[0]
            elif short == "vpn.get":
                result = self.system.current()
            elif short == "vpn.set":
                self.system.set(self.value(p["WFVPN"]), p["WFVPNOperation"], p.get("WFOnDemandValue"))
            elif short == "date":
                result = self.system.now
            elif short == "format.date":
                result = self.value(p["WFDate"]).isoformat(timespec="milliseconds")
            elif short == "delay":
                self.system.now += timedelta(seconds=p["WFDelayTime"])
            elif short == "detect.dictionary":
                result = json.loads(self.value(p["WFInput"]))
            elif short == "getvalueforkey":
                result = self.value(p["WFInput"]).get(p["WFDictionaryKey"])
            elif short == "output":
                raise Finished(self.value(p["WFOutput"]))
            elif short == "showresult":
                self.system.events.append(("showResult", self.value(p["Text"])))
            elif short == "alert":
                self.system.alert(p)
            elif short == "comment":
                pass
            elif aid.endswith(".PersonalRenewalIntent"):
                result = self.service.call({k: self.value(v) for k, v in p.items()})
            else:
                raise AssertionError(aid)
            self.outputs[p["UUID"]] = result
            if self.after_action:
                self.after_action(self, i, aid, p)
            i += 1

    def run(self):
        try:
            self.run_range(0, len(self.actions))
        except Finished as finished:
            return finished.value


class BuilderTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.workflow = Builder(CONFIG).build()

    def run_workflow(self, system=None, service=None, input_value=None):
        system = system or System()
        service = service or Service(system)
        output = Interpreter(self.workflow, system, service, input_value).run()
        return system, service, output

    def test_structural_validation_and_deterministic_binary(self):
        result = validate(self.workflow)
        self.assertEqual(result["errors"], [])
        with tempfile.TemporaryDirectory() as tmp:
            first = write_outputs(CONFIG, Path(tmp))
            second = write_outputs(CONFIG, Path(tmp))
            self.assertEqual(first, second)
            self.assertEqual(plistlib.loads((Path(tmp)/"SideStore-Renewal-unsigned.shortcut").read_bytes()), self.workflow)

    def test_manual_success_preserves_original_network_and_on_demand(self):
        system, service, _ = self.run_workflow()
        self.assertEqual(service.calls, ["prepareWorkflow", "executeWorkflow", "recordRestorationRequest", "confirmRestoration"])
        self.assertTrue(service.complete)
        self.assertFalse(service.pending)
        self.assertEqual([(v["Is Connected"], v["Is On Demand Enabled"]) for v in system.vpns], [(True, True), (False, False)])
        self.assertLess(system.events.index(("nativeReturned", True)), system.events.index(("requestAccepted", system.set_count)))
        shown = [e[1] for e in system.events if e[0] == "showResult"]
        self.assertEqual(len(shown), 1)
        self.assertIn("RustDesk V2：已核验", shown[0])
        self.assertIn("SideStore：已核验", shown[0])

    def test_restore_both_disconnected_and_nondefault_on_demand(self):
        system, service, _ = self.run_workflow(System(qx=False, local=False, qx_od=False, local_od=True))
        self.assertTrue(service.complete)
        self.assertEqual([(v["Is Connected"], v["Is On Demand Enabled"]) for v in system.vpns], [(False, False), (False, True)])

    def test_restore_original_local_vpn_instead_of_assuming_quantumult(self):
        system, service, _ = self.run_workflow(System(qx=False, local=True, qx_od=False, local_od=True))
        self.assertTrue(service.complete)
        self.assertFalse(system.vpns[0]["Is Connected"])
        self.assertTrue(system.vpns[1]["Is Connected"])
        self.assertTrue(system.vpns[1]["Is On Demand Enabled"])

    def test_automatic_skip_and_busy_never_change_network(self):
        for field in ("skip", "busy"):
            with self.subTest(field=field):
                system = System()
                service = Service(system)
                setattr(service, field, True)
                self.run_workflow(system, service, "automatic")
                self.assertEqual(system.set_count, 0)
                self.assertEqual(service.calls, ["prepareWorkflow"])
                self.assertFalse(any(e[0] == "showResult" for e in system.events))

    def test_unknown_input_stops_before_service_or_mutation(self):
        system, service, _ = self.run_workflow(input_value="unexpected")
        self.assertEqual(system.set_count, 0)
        self.assertEqual(service.calls, ["prepareWorkflow"])

    def test_prepare_storage_failure_prevents_all_network_changes(self):
        system = System()
        service = Service(system)
        service.fail_prepare = True
        self.run_workflow(system, service)
        self.assertEqual(system.set_count, 0)
        self.assertFalse(service.pending)

    def test_missing_and_duplicate_names_refuse_without_first_item_fallback(self):
        for mode in ("missing", "duplicate"):
            with self.subTest(mode=mode):
                system = System()
                if mode == "missing":
                    system.vpns.pop()
                else:
                    system.vpns.append(copy.deepcopy(system.vpns[0]))
                _, service, _ = self.run_workflow(system)
                self.assertEqual(service.calls, [])
                self.assertEqual(system.set_count, 0)

    def test_foreign_active_vpn_refuses_without_changing_it(self):
        system = System(qx=False)
        system.vpns.append({"Name": "Other VPN", "Is Connected": True, "Is On Demand Enabled": True})
        _, service, _ = self.run_workflow(system)
        self.assertEqual(service.calls, ["prepareWorkflow"])
        self.assertEqual(system.set_count, 0)
        self.assertTrue(system.vpns[-1]["Is Connected"])

    def test_foreign_vpn_selected_during_long_native_is_not_overwritten(self):
        system = System()
        service = Service(system)
        original = service.call
        def call(params):
            result = original(params)
            if params["action"] == "executeWorkflow":
                for vpn in system.vpns:
                    vpn["Is Connected"] = False
                system.vpns.append({"Name": "Other VPN", "Is Connected": True, "Is On Demand Enabled": True})
            return result
        service.call = call
        self.run_workflow(system, service)
        self.assertTrue(service.pending)
        self.assertEqual(system.set_count, 4)
        self.assertNotIn("recordRestorationRequest", service.calls)
        self.assertTrue(system.vpns[-1]["Is Connected"])

    def test_missing_or_unknown_system_boolean_never_becomes_false(self):
        for value in (None, "Unknown", "No"):
            with self.subTest(value=value):
                system = System()
                system.vpns[0]["Is Connected"] = value
                _, service, _ = self.run_workflow(system)
                self.assertEqual(service.calls, ["prepareWorkflow"])
                self.assertEqual(system.set_count, 0)

    def test_partial_native_result_still_restores_but_does_not_claim_workflow_success(self):
        system = System()
        service = Service(system)
        service.partial = True
        _, _, output = self.run_workflow(system, service)
        self.assertFalse(service.pending)
        self.assertFalse(service.complete)
        self.assertIn("部分", output)

    def test_controlled_native_cancel_still_restores_after_drain(self):
        system = System()
        service = Service(system)
        service.cancelled = True
        self.run_workflow(system, service)
        self.assertFalse(service.pending)
        self.assertFalse(service.complete)
        self.assertTrue(system.vpns[0]["Is Connected"])

    def test_native_not_drained_or_not_authorized_never_restores(self):
        for field in ("drain_false", "deny_restore", "wrong_run", "wrong_schema"):
            with self.subTest(field=field):
                system = System()
                service = Service(system)
                setattr(service, field, True)
                self.run_workflow(system, service)
                self.assertTrue(service.pending)
                self.assertEqual(system.set_count, 4)
                self.assertNotIn("recordRestorationRequest", service.calls)
                self.assertNotIn("confirmRestoration", service.calls)

    def test_each_set_vpn_throw_keeps_obligation_and_runs_no_finally(self):
        successful, _, _ = self.run_workflow()
        for fail_at in range(1, successful.set_count + 1):
            with self.subTest(fail_at=fail_at):
                system = System()
                service = Service(system)
                system.fail_set = fail_at
                with self.assertRaises(HostStopped):
                    self.run_workflow(system, service)
                self.assertTrue(service.pending)
                self.assertFalse(service.complete)
                self.assertEqual(system.set_count, fail_at)
                self.assertNotIn("confirmRestoration", service.calls)

    def test_next_same_entry_recovers_after_interruption_without_native_retry(self):
        system = System()
        service = Service(system)
        system.fail_set = 6
        with self.assertRaises(HostStopped):
            self.run_workflow(system, service)
        self.assertTrue(service.pending)
        system.fail_set = None
        self.run_workflow(system, service)
        self.assertEqual(service.calls.count("executeWorkflow"), 1)
        self.assertEqual(service.calls.count("recoverWorkflow"), 1)
        self.assertFalse(service.pending)
        self.assertTrue(system.vpns[0]["Is Connected"])

    def test_host_interrupted_native_has_no_cleanup_or_fake_completion(self):
        system = System()
        service = Service(system)
        service.throw_native = True
        with self.assertRaises(HostStopped):
            self.run_workflow(system, service)
        self.assertTrue(service.pending)
        self.assertEqual(system.set_count, 4)
        self.assertFalse(service.request_recorded)
        self.assertFalse(service.complete)

    def test_local_connection_timeout_calls_read_only_recovery_not_execute(self):
        system = System()
        system.ignore_connect = True
        _, service, _ = self.run_workflow(system)
        self.assertNotIn("executeWorkflow", service.calls)
        self.assertIn("recoverWorkflow", service.calls)
        # Ignored final Connect is not converted into a successful restoration.
        self.assertTrue(service.pending)
        self.assertFalse(service.complete)

    def test_unchanged_disconnected_readback_does_not_clear_restore_obligation(self):
        system = System()
