class WorkflowOwnerInterleavingTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.workflow = Builder(CONFIG).build()

    def test_normal_invocations_use_distinct_app_generated_owners_without_alert(self):
        system = System()
        service = Service(system)
        Interpreter(self.workflow, system, service).run()
        Interpreter(self.workflow, system, service).run()
        self.assertEqual(len(service.owner_calls), 2)
        self.assertNotEqual(*service.owner_calls)
        for owner in service.owner_calls:
            uuid.UUID(owner)
            calls = [p for p in service.parameter_calls if p.get("workflowOwnerID") == owner]
            self.assertEqual([p["action"] for p in calls], ["prepareWorkflow", "executeWorkflow", "recordRestorationRequest", "confirmRestoration"])
            self.assertTrue(all(p["allowRecoveryTakeover"] is False for p in calls))
        self.assertFalse(any(e[0] == "alert" for e in system.events))
        ids = [a["WFWorkflowActionIdentifier"] for a in self.workflow["WFWorkflowActions"]]
        self.assertFalse(any("uuid" in aid.lower() for aid in ids))

    def test_bootstrap_has_no_database_observation_or_vpn_side_effect(self):
        system = System()
        service = Service(system)
        seen = []
        def stop_after_bootstrap(interpreter, index, aid, params):
            seen.append(aid)
            if aid.endswith(".PersonalRenewalIntent") and interpreter.value(params["action"]) == "newWorkflowOwner":
                raise HostStopped("stop before any network observation")
        with self.assertRaises(HostStopped):
            Interpreter(self.workflow, system, service, after_action=stop_after_bootstrap).run()
        self.assertFalse(service.pending)
        self.assertIsNone(service.owner_id)
        self.assertEqual(service.calls, [])
        self.assertEqual(system.set_count, 0)
        self.assertNotIn(STD+"filter.vpns", seen)

    def test_missing_bootstrap_owner_stops_before_find_or_prepare(self):
        system = System()
        service = Service(system)
        def call(params):
            self.assertEqual(params["action"], "newWorkflowOwner")
            return '{"schemaVersion":2}'
        service.call = call
        interpreter = Interpreter(self.workflow, system, service)
        interpreter.run()
        self.assertNotIn("QXVPN", interpreter.variables)
        self.assertEqual(system.set_count, 0)

    def test_second_automatic_cannot_mutate_between_first_prepare_or_native_and_cleanup(self):
        for boundary in ("prepareWorkflow", "executeWorkflow"):
            with self.subTest(boundary=boundary):
                system = System()
                service = Service(system)
                inserted = False
                def interleave(interpreter, index, aid, params):
                    nonlocal inserted
                    if inserted or not aid.endswith(".PersonalRenewalIntent") or interpreter.value(params["action"]) != boundary:
                        return
                    inserted = True
                    owner, mutations = service.owner_id, system.set_count
                    second = Interpreter(self.workflow, system, service, "automatic")
                    output = second.run()
                    self.assertEqual(system.set_count, mutations)
                    self.assertEqual(service.owner_id, owner)
                    self.assertNotEqual(second.variables["WorkflowOwnerID"], owner)
                    self.assertIn("先停止上一条", output)
                    self.assertFalse(any(e[0] == "alert" for e in system.events))
                first = Interpreter(self.workflow, system, service, after_action=interleave)
                first.run()
                self.assertTrue(inserted)
                self.assertTrue(service.complete)
                self.assertFalse(service.pending)
                self.assertEqual(service.calls.count("executeWorkflow"), 1)
                self.assertEqual(service.calls.count("recoverWorkflow"), 0)
                self.assertEqual(service.calls.count("confirmRestoration"), 1)

    def test_second_manual_cancel_keeps_first_owner_and_first_can_finish(self):
        system = System()
        service = Service(system)
        inserted = False
        def interleave(interpreter, index, aid, params):
            nonlocal inserted
            if inserted or not aid.endswith(".PersonalRenewalIntent") or interpreter.value(params["action"]) != "prepareWorkflow":
                return
            inserted = True
            owner, mutations = service.owner_id, system.set_count
            system.cancel_alert = True
            with self.assertRaises(HostStopped):
                Interpreter(self.workflow, system, service).run()
            system.cancel_alert = False
            self.assertEqual(service.owner_id, owner)
            self.assertEqual(system.set_count, mutations)
            self.assertFalse(any(p.get("allowRecoveryTakeover") is True for p in service.parameter_calls))
        Interpreter(self.workflow, system, service, after_action=interleave).run()
        self.assertTrue(service.complete)
        self.assertEqual(len([e for e in system.events if e[0] == "alert"]), 1)

    def stop_first_after_prepare(self, system, service):
        def stop(interpreter, index, aid, params):
            if aid.endswith(".PersonalRenewalIntent") and interpreter.value(params["action"]) == "prepareWorkflow":
                raise HostStopped("user stopped the previous Shortcut host")
        with self.assertRaises(HostStopped):
            Interpreter(self.workflow, system, service, after_action=stop).run()
        return service.owner_id

    def test_manual_confirm_after_stopping_first_takes_over_and_rejects_late_old_callbacks(self):
        system = System()
        service = Service(system)
        old_owner = self.stop_first_after_prepare(system, service)
        self.assertEqual(system.set_count, 0)
        system.on_alert = lambda: setattr(system, "now", system.now + timedelta(minutes=2))
        second = Interpreter(self.workflow, system, service)
        second.run()
        new_owner = second.variables["WorkflowOwnerID"]
        self.assertNotEqual(new_owner, old_owner)
        self.assertEqual(service.owner_id, new_owner)
        prepares = [p for p in service.parameter_calls if p["action"] == "prepareWorkflow" and p.get("workflowOwnerID") == new_owner]
        self.assertEqual([p["allowRecoveryTakeover"] for p in prepares], [False, True])
        self.assertEqual(service.calls.count("executeWorkflow"), 0)
        self.assertEqual(service.calls.count("recoverWorkflow"), 1)
        self.assertFalse(service.pending)
        self.assertTrue(system.vpns[0]["Is Connected"])
        before = (system.set_count, len(system.events), service.owner_id, service.pending, service.request_recorded)
        stale = next(p for p in service.parameter_calls if p["action"] == "prepareWorkflow" and p.get("workflowOwnerID") == old_owner)
        for action in ("executeWorkflow", "recoverWorkflow", "recordRestorationRequest", "confirmRestoration"):
            request = {**stale, "action": action, "runID": service.run_id}
            response = json.loads(service.call(request))
            self.assertEqual(response["status"], "wrongOwner")
            self.assertEqual(response["workflowOwnerID"], new_owner)
        self.assertEqual(before, (system.set_count, len(system.events), service.owner_id, service.pending, service.request_recorded))

    def test_worker_start_between_confirmation_and_takeover_prevents_owner_change(self):
        system = System()
        service = Service(system)
        old_owner = self.stop_first_after_prepare(system, service)
        system.on_alert = lambda: setattr(service, "worker_active", True)
        Interpreter(self.workflow, system, service).run()
        self.assertEqual(service.owner_id, old_owner)
        self.assertTrue(service.pending)
        self.assertEqual(system.set_count, 0)
        self.assertNotIn("recoverWorkflow", service.calls)

    def test_missing_or_different_reply_owner_cannot_start_switch_or_restore(self):
        for boundary, expected_sets in (("prepareWorkflow", 0), ("executeWorkflow", 4)):
            for bad_owner in (None, str(uuid.uuid4())):
                with self.subTest(boundary=boundary, bad_owner=bad_owner):
                    system = System()
                    service = Service(system)
                    original = service.call
                    def call(params):
                        result = json.loads(original(params))
                        if params["action"] == boundary:
                            if bad_owner is None:
                                result.pop("workflowOwnerID", None)
                            else:
                                result["workflowOwnerID"] = bad_owner
                        return json.dumps(result)
                    service.call = call
                    Interpreter(self.workflow, system, service).run()
                    self.assertEqual(system.set_count, expected_sets)
                    self.assertTrue(service.pending)
                    self.assertNotIn("recordRestorationRequest", service.calls)

    def test_validator_rejects_owner_mismatch_and_nonprepare_takeover(self):
        for mutation in ("owner", "missing", "takeover", "initialTakeover", "cancel"):
            workflow = copy.deepcopy(self.workflow)
            app = next(a for a in workflow["WFWorkflowActions"] if a["WFWorkflowActionIdentifier"].endswith(".PersonalRenewalIntent") and isinstance(a["WFWorkflowActionParameters"].get("action"), dict))
            p = app["WFWorkflowActionParameters"]
            if mutation == "owner":
                p["workflowOwnerID"] = "hard-coded-other-owner"
            elif mutation == "missing":
                del p["workflowOwnerID"]
            elif mutation == "takeover":
                p["allowRecoveryTakeover"] = True
            elif mutation == "initialTakeover":
                prepare = next(a for a in workflow["WFWorkflowActions"] if a["WFWorkflowActionParameters"].get("action") == "prepareWorkflow")
                prepare["WFWorkflowActionParameters"]["allowRecoveryTakeover"] = True
            else:
                alert = next(a for a in workflow["WFWorkflowActions"] if a["WFWorkflowActionIdentifier"] == STD+"alert")
                alert["WFWorkflowActionParameters"]["WFAlertActionCancelButtonShown"] = False
            self.assertFalse(validate(workflow)["valid"])


