#!/usr/bin/env python3
"""Read-only structural validation of the generated, unsigned plist.

This deliberately does not claim Apple import/runtime validation. The interpreter
tests exercise the serialized actions separately, with temporal safety assertions.
"""
from __future__ import annotations

import argparse
import json
from pathlib import Path
import plistlib

STD = "is.workflow.actions."
KNOWN = {"comment", "gettext", "setvariable", "conditional", "repeat.count", "repeat.each",
         "getvalueforkey", "detect.dictionary", "filter.vpns", "count", "getitemfromlist",
         "vpn.get", "vpn.set", "date", "format.date", "delay", "output", "showresult", "alert"}
WORKFLOW_ACTIONS = {"newWorkflowOwner", "prepareWorkflow", "executeWorkflow", "recoverWorkflow",
                    "recordRestorationRequest", "confirmRestoration"}
TYPED = {"quantumultXName", "localDevVPNName", "quantumultXConnected", "localDevVPNConnected",
         "quantumultXOnDemand", "localDevVPNOnDemand", "currentVPNNames", "observationDate"}


def walk(value):
    yield value
    if isinstance(value, dict):
        for child in value.values():
            yield from walk(child)
    elif isinstance(value, list):
        for child in value:
            yield from walk(child)


def validate(workflow):
    errors, seen, stack, intent_actions, mutations, filters = [], set(), [], set(), 0, 0
    bundle = None
    bootstrap_indices, prepares, alert_indices = [], [], []
    actions = workflow.get("WFWorkflowActions", [])
    if not actions:
        errors.append("empty workflow")
    for index, action in enumerate(actions):
        aid = action.get("WFWorkflowActionIdentifier", "")
        p = action.get("WFWorkflowActionParameters", {})
        label = f"action {index} {aid}"
        uid = p.get("UUID")
        if not uid or uid in seen:
            errors.append(f"{label}: missing/duplicate UUID")
        for value in walk(p):
            if isinstance(value, dict) and value.get("Type") == "ActionOutput":
                if value.get("OutputUUID") not in seen:
                    errors.append(f"{label}: forward/missing output reference")
        if uid:
            seen.add(uid)
        if aid.startswith(STD):
            short = aid[len(STD):]
            if short not in KNOWN:
                errors.append(f"{label}: unapproved action")
        else:
            descriptor = p.get("AppIntentDescriptor", {})
            this_bundle = descriptor.get("BundleIdentifier")
            bundle = bundle or this_bundle
            if not this_bundle or this_bundle != bundle or aid != this_bundle + ".PersonalRenewalIntent":
                errors.append(f"{label}: app action/descriptor mismatch")
            if descriptor.get("AppIntentIdentifier") != "PersonalRenewalIntent":
                errors.append(f"{label}: wrong intent")
            required = {"UUID", "AppIntentDescriptor", "action", "runID", "mode", "OpenWhenRun"}
            raw_action = p.get("action")
            if raw_action == "newWorkflowOwner":
                bootstrap_indices.append(index)
            elif raw_action == "prepareWorkflow":
                prepares.append((index, p.get("allowRecoveryTakeover")))
            if raw_action != "newWorkflowOwner":
                required |= {"workflowOwnerID", "allowRecoveryTakeover"}
                if p.get("workflowOwnerID") != {"WFSerializationType": "WFTextTokenAttachment", "Value": {"Type": "Variable", "VariableName": "WorkflowOwnerID"}}:
                    errors.append(f"{label}: action must use this invocation's owner")
                if type(p.get("allowRecoveryTakeover")) is not bool or (p.get("allowRecoveryTakeover") is True and raw_action != "prepareWorkflow"):
                    errors.append(f"{label}: invalid takeover authorization parameter")
            if raw_action not in ("recordRestorationRequest", "newWorkflowOwner"):
                required |= TYPED
            if set(p) != required:
                errors.append(f"{label}: incorrect AppIntent parameter set")
            if isinstance(raw_action, dict):
                if raw_action != {"WFSerializationType": "WFTextTokenAttachment", "Value": {"Type": "Variable", "VariableName": "NativeAction"}}:
                    errors.append(f"{label}: unknown dynamic action source")
                intent_actions |= {"executeWorkflow", "recoverWorkflow"}
            else:
                if raw_action not in WORKFLOW_ACTIONS:
                    errors.append(f"{label}: unknown protocol action")
                intent_actions.add(raw_action)
        if aid in (STD + "conditional", STD + "repeat.count", STD + "repeat.each"):
            mode, group = p.get("WFControlFlowMode"), p.get("GroupingIdentifier")
            if mode == 0:
                stack.append((aid, group))
            elif mode == 2:
                if not stack or stack.pop() != (aid, group):
                    errors.append(f"{label}: incorrectly nested block")
            else:
                errors.append(f"{label}: unsupported control-flow mode")
        if aid == STD + "vpn.set":
            mutations += 1
            operation = p.get("WFVPNOperation")
            if operation not in {"Connect", "Disconnect", "Set On Demand"}:
                errors.append(f"{label}: toggle/unknown operation")
            if operation == "Set On Demand" and type(p.get("WFOnDemandValue")) is not bool:
                errors.append(f"{label}: On Demand is not a plist boolean")
            if p.get("WFVPN", {}).get("WFSerializationType") != "WFTextTokenAttachment":
                errors.append(f"{label}: VPN picker must be a dynamic Find result")
        if aid == STD + "count":
            if "Input" not in p or "WFInput" in p or p.get("WFCountType") != "Items":
                errors.append(f"{label}: Count uses the Apple catalog parameter Input, not WFInput")
        if aid == STD + "alert":
            alert_indices.append(index)
            if p.get("WFAlertActionCancelButtonShown") is not True:
                errors.append(f"{label}: recovery confirmation must have a cancel button")
        if aid == STD + "filter.vpns":
            filters += 1
            if p.get("WFContentItemInputParameter") != "Library" or p.get("WFContentItemLimitEnabled") is not False:
                errors.append(f"{label}: incorrect library input or concealed duplicates")
            predicates = p.get("WFContentItemFilter", {}).get("Value", {}).get("WFActionParameterFilterTemplates", [])
            if len(predicates) != 1 or predicates[0].get("Property") != "Name" or predicates[0].get("Operator") != 4:
                errors.append(f"{label}: require exact Name equality")
            # Count the full result before a First Item is allowed to consume it.
            following = actions[index + 1:index + 10]
            ids = [a["WFWorkflowActionIdentifier"] for a in following]
            if not ids or ids[0] != STD + "count" or STD + "output" not in ids or STD + "getitemfromlist" not in ids:
                errors.append(f"{label}: missing duplicate/empty-result guard")
        if aid == STD + "repeat.count" and p.get("WFControlFlowMode") == 0:
            if not isinstance(p.get("WFRepeatCount"), int) or not 1 <= p["WFRepeatCount"] <= 30:
                errors.append(f"{label}: unbounded poll")
    if stack:
        errors.append("unclosed control-flow block")
    if intent_actions != WORKFLOW_ACTIONS:
        errors.append("missing workflow protocol action")
    if len(bootstrap_indices) != 1 or not prepares or bootstrap_indices[0] >= prepares[0][0]:
        errors.append("one owner bootstrap must precede preparation")
    if [flag for _, flag in prepares] != [False, True] or len(alert_indices) != 1 or not prepares[0][0] < alert_indices[0] < prepares[-1][0]:
        errors.append("initial preparation cannot authorize takeover; explicit second prepare follows recovery alert")
    return {"valid": not errors, "errors": errors, "actionCount": len(actions),
            "vpnMutations": mutations, "uniqueNameQueries": filters,
            "appIntentActions": sorted(intent_actions), "validationBoundary": "offline structure only"}


def main():
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument("shortcut", type=Path)
    args = p.parse_args()
    result = validate(plistlib.loads(args.shortcut.read_bytes()))
    print(json.dumps(result, ensure_ascii=False, indent=2))
    raise SystemExit(0 if result["valid"] else 1)


if __name__ == "__main__":
    main()

"""Rebuild the personal source snapshot; never consumes phone data or signing keys."""
from __future__ import annotations

import argparse
import hashlib
import json
import os
from pathlib import Path
import plistlib
import shutil
import subprocess
import zipfile

ROOT = Path(__file__).resolve().parent


def sha(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def run(*args: str, cwd: Path | None = None) -> None:
    subprocess.run(args, cwd=cwd, check=True)


def manifest() -> dict:
    return json.loads((ROOT / "manifest.json").read_text(encoding="utf-8"))


def checked_payload(entry: dict) -> bytes:
    path = ROOT / "payload" / entry["path"]
    if not path.resolve().is_relative_to((ROOT / "payload").resolve()):
        raise ValueError("Payload path escaped its root")
    data = path.read_bytes()
    if sha(data) != entry["sha256"]:
        raise ValueError(f"Payload changed: {entry['path']}")
    return data


def assemble(destination: Path) -> None:
    if destination.exists():
        raise ValueError("Assembly destination must be new")
    spec = manifest()
    run("git", "clone", "--filter=blob:none", "--no-checkout", spec["upstream"], str(destination))
    run("git", "checkout", "--detach", spec["commit"], cwd=destination)
    run("git", "submodule", "update", "--init", "--recursive", cwd=destination)
    for submodule, expected in spec["submodules"].items():
        actual = subprocess.check_output(["git", "rev-parse", "HEAD"], cwd=destination / submodule, text=True).strip()
        if actual != expected:
            raise ValueError(f"Unexpected submodule revision: {submodule}")
    for entry in spec["files"]:
        data = checked_payload(entry)
        path = destination / entry["path"]
        if not path.resolve().is_relative_to(destination.resolve()):
            raise ValueError("Assembly path escaped its root")
        previous = entry["originalSha256"]
        if previous is None:
            if path.exists():
                raise ValueError(f"New source already exists: {entry['path']}")
        elif not path.is_file() or sha(path.read_bytes()) != previous:
            raise ValueError(f"Official source did not match: {entry['path']}")
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(data)
    (destination / "personal-source-manifest.json").write_text(json.dumps(spec, indent=2) + "\n", encoding="utf-8")
    for entry in spec["unmodifiedUpstreamPaths"]:
        if sha((destination / entry["path"]).read_bytes()) != entry["sha256"]:
            raise ValueError("Upstream startup or database source changed")
    if (destination / "SideStore/PersonalUpgradePreservation.swift").exists():
        raise ValueError("Removed custom startup helper is still present")


def verify_payload() -> None:
    spec = manifest()
    if {entry["path"] for entry in spec["files"]} & {entry["path"] for entry in spec["unmodifiedUpstreamPaths"]}:
        raise ValueError("Startup or database files must remain exactly upstream")
    if any(entry["path"] == "SideStore/PersonalUpgradePreservation.swift" for entry in spec["files"]):
        raise ValueError("Removed custom startup helper cannot be packaged")
    for entry in spec["files"]:
        checked_payload(entry)
    for entry in spec.get("ciTools", []):
        path = ROOT / entry["path"]
        if not path.resolve().is_relative_to((ROOT / "ci-tools").resolve()):
            raise ValueError("CI tool path escaped its root")
        if sha(path.read_bytes()) != entry["sha256"]:
            raise ValueError("CI tool changed")
    for entry in spec["preservationHarness"]:
        data = (ROOT / "preservation-check" / entry["path"]).read_bytes()
        if sha(data) != entry["sha256"]:
            raise ValueError("Preservation harness changed")
    print(f"Verified {len(spec['files'])} source files; no device material is included.")


def build(source: Path, artifacts: Path) -> None:
    artifacts.mkdir(parents=True, exist_ok=True)
    run("make", "build", f"MARKETING_VERSION={manifest()['version']}", cwd=source)
    run("make", "fakesign", "ipa", cwd=source)
    ipa = source / "SideStore.ipa"
    with zipfile.ZipFile(ipa) as archive:
        if archive.testzip() is not None:
            raise ValueError("IPA zip integrity failure")
        info = plistlib.loads(archive.read("Payload/SideStore.app/Info.plist"))
        if info.get("CFBundleIdentifier") != "com.SideStore.SideStore":
            raise ValueError("Main application identity changed")
        if info.get("CFBundleShortVersionString") != manifest()["version"]:
            raise ValueError("Build version mismatch")
        if info.get("CFBundleVersion") != "0707":
            raise ValueError("Build number mismatch")
        if not str(info.get("DTSDKName", "")).startswith("iphoneos27.2"):
            raise ValueError("Expected the verified iOS 27.2 SDK")
        if any(name.lower().endswith((".mobileprovision", ".p12", ".pfx")) for name in archive.namelist()):
            raise ValueError("Unexpected signing material in unsigned package")
        metadata = json.loads(archive.read("Payload/SideStore.app/Metadata.appintents/extract.actionsdata"))
        if "PersonalRenewalIntent" not in metadata.get("actions", {}):
            raise ValueError("Renewal intent was not extracted for Shortcuts")
        actions = next((entry for entry in metadata.get("enums", []) if entry.get("identifier") == "PersonalRenewalAction"), None)
        expected_actions = {"checkReadiness", "nativeValidation", "status", "cancel", "newWorkflowOwner", "prepareWorkflow",
                            "executeWorkflow", "recoverWorkflow", "recordRestorationRequest", "confirmRestoration"}
        if actions is None or {entry["identifier"] for entry in actions["cases"]} != expected_actions:
            raise ValueError("Renewal actions were not extracted completely")
    output = artifacts / "SideStore-OneClick-Renewal-0707-unsigned.ipa"
    shutil.copyfile(ipa, output)
    provenance = {
        "version": manifest()["version"],
        "sha256": sha(output.read_bytes()),
        "sourceManifestSHA256": sha((ROOT / "manifest.json").read_bytes()),
        "gitHubRecipeCommit": os.environ.get("GITHUB_SHA"),
        "acceptance": "not-phone-tested",
        "scope": "Full workflow source and Shortcut wiring; real device acceptance remains separate",
    }
    (artifacts / "build-provenance.json").write_text(json.dumps(provenance, indent=2) + "\n", encoding="utf-8")
    print(json.dumps(provenance))


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("command", choices=["verify", "assemble", "build"])
    parser.add_argument("--source", type=Path, default=Path("native-source"))
    parser.add_argument("--artifacts", type=Path, default=Path("artifacts"))
    options = parser.parse_args()
    if options.command == "verify":
        verify_payload()
    elif options.command == "assemble":
        assemble(options.source)
    else:
        build(options.source, options.artifacts)


if __name__ == "__main__":
    main()

