/// Created before entering a long-running intent so even cancellation before a
/// durable run exists is remembered. The synchronous signal cannot arrive late
/// and accidentally cancel another invocation.
public final class RenewalInvocationControl: @unchecked Sendable {
    public let id = UUID().uuidString
    private let lock = NSLock()
    private var cancellationRequested = false

    public init() {}

    public func requestCancellation() {
        lock.lock()
        cancellationRequested = true
        lock.unlock()
    }

    public var isCancellationRequested: Bool {
        lock.lock()
        defer { lock.unlock() }
        return cancellationRequested
    }

    public func checkCancellation() throws {
        try Task.checkCancellation()
        if isCancellationRequested { throw CancellationError() }
    }
}

