/// One live engine owns a storage key. The app integration must also use a single process/target.
public protocol RenewalJournalStorage: Sendable {
    var ownershipKey: String { get }
    func load() throws -> Data?
    func save(_ data: Data) throws
}

public final class FileRenewalJournalStorage: RenewalJournalStorage, @unchecked Sendable {
    public let url: URL
    public var ownershipKey: String { url.standardizedFileURL.resolvingSymlinksInPath().path }

    public init(url: URL) { self.url = url }

    public func load() throws -> Data? {
        guard FileManager.default.fileExists(atPath: url.path) else { return nil }
        return try Data(contentsOf: url)
    }

    public func save(_ data: Data) throws {
        try FileManager.default.createDirectory(at: url.deletingLastPathComponent(),
                                                withIntermediateDirectories: true)
        try data.write(to: url, options: .atomic)
        let file = try FileHandle(forWritingTo: url)
        defer { try? file.close() }
        try file.synchronize()
        guard try Data(contentsOf: url) == data else { throw RenewalCoreError.journalWriteUnverified }
    }
}

struct RenewalLedger: Codable, Sendable {
    var schemaVersion = 1
    var revision: UInt64 = 0
    var current: RenewalRun?
    var history: [RenewalRun] = []
    var latestVerified: [String: VerifiedRenewal] = [:]
}

struct RenewalJournalIOFailure: Error, Sendable {
    let domain: String
    let code: Int
}

/// This is an in-process guard, deliberately not advertised as a cross-process file lock.
final class RenewalStorageOwners: @unchecked Sendable {
    static let shared = RenewalStorageOwners()
    private let lock = NSLock()
    private var keys = Set<String>()

    func acquire(_ key: String) throws {
        lock.lock()
        defer { lock.unlock() }
        guard keys.insert(key).inserted else { throw RenewalCoreError.journalAlreadyOwned }
    }

    func release(_ key: String) {
        lock.lock()
        defer { lock.unlock() }
        keys.remove(key)
    }
}

