public enum RenewalOutcome: String, Codable, Sendable {
    case succeeded
    case recoveredAndVerified
    case partiallySucceeded
    case failed
    case cancelled
}

public struct RenewalRun: Codable, Equatable, Sendable {
    public let id: String
    public let mode: RenewalMode
    public let createdAt: Date
    public let networkPolicy: RenewalNetworkPolicy
    /// Per Shortcut invocation, separate from the durable renewal task ID.
    /// Nil is a legacy record that must be explicitly taken over before workflow work.
    public internal(set) var workflowOwnerID: String?
    /// Only incomplete prior tasks are retry sources. An ordinary manual refresh does not reuse successful runs.
    public let retryOfRunID: String?
    public internal(set) var phase: RenewalPhase
    public internal(set) var attempts: [RenewalAttempt]
    public internal(set) var cancellationRequested: Bool
    public internal(set) var networkRecovery: NetworkRecoveryState
    public internal(set) var finishedAt: Date?
    public internal(set) var failures: [RenewalFailure]

    public var outcome: RenewalOutcome {
        let verified = attempts.filter { attempt in
            guard !attempt.requiresReverification, let proof = attempt.verification,
                  proof.target == attempt.target else { return false }
            if attempt.state == .reconciledInstalled { return !proof.nativeCompletionConfirmed }
            return attempt.state == .verified && proof.nativeCompletionConfirmed &&
                attempt.preparedProfiles?.target == attempt.target &&
                attempt.nativeCompletion?.target == attempt.target &&
                attempt.nativeCompletion?.operationID == attempt.preparedProfiles?.operationID
        }
        if verified.count == RenewalApp.executionOrder.count {
            return verified.allSatisfy { $0.state == .verified } ? .succeeded : .recoveredAndVerified
        }
        if !verified.isEmpty { return .partiallySucceeded }
        return cancellationRequested ? .cancelled : .failed
    }

    /// A successful profile outcome alone is not successful completion of the entire workflow.
    public var fullyCompleted: Bool {
        failures.isEmpty && networkPolicy == .switchAndRestore && phase == .finished && !networkRecovery.isPending &&
            attempts.allSatisfy({ !$0.requiresReverification }) &&
            (outcome == .succeeded || outcome == .recoveredAndVerified)
    }

    public var nativeValidationCompleted: Bool {
        failures.isEmpty && networkPolicy == .keepCurrent && phase == .finished &&
            attempts.allSatisfy({ !$0.requiresReverification && $0.state == .verified &&
                $0.verification?.nativeCompletionConfirmed == true }) && outcome == .succeeded
    }

    public init(id: String, mode: RenewalMode, createdAt: Date, targets: [RenewalTarget],
                networkPolicy: RenewalNetworkPolicy = .switchAndRestore, retryOfRunID: String? = nil,
                networkRestoreTarget: NetworkRestoreTarget? = nil, workflowOwnerID: String? = nil) {
        self.id = id
        self.mode = mode
        self.createdAt = createdAt
        self.networkPolicy = networkPolicy
        self.workflowOwnerID = workflowOwnerID
        self.retryOfRunID = retryOfRunID
        phase = .networkChangePending
        attempts = targets.map(RenewalAttempt.init)
        cancellationRequested = false
        networkRecovery = NetworkRecoveryState(requiredSince: createdAt, required: networkPolicy == .switchAndRestore,
                                               restoreTarget: networkRestoreTarget)
        finishedAt = nil
        failures = []
    }
}

