import Foundation

/// The integration must place this engine in the main app process only. An actor and atomic writes
/// are not a cross-process lock. A second live engine for the same storage key is rejected here.
public actor RenewalEngine {
    private let storage: any RenewalJournalStorage
    private let ownershipKey: String
    private let clock: @Sendable () -> Date
    private let automaticThreshold: TimeInterval
    private let planLifetime: TimeInterval
    private var ledger: RenewalLedger
    private var worker: Task<RenewalExecutionResult, Error>?
    private var activeDriver: (any RenewalDeviceDriver)?
    private var cancellationRequestedInProcess = false
    private var lastPersistenceFailure: RenewalFailure?

    public init(storage: any RenewalJournalStorage,
                automaticThreshold: TimeInterval = 48 * 60 * 60,
                planLifetime: TimeInterval = 10 * 60,
                clock: @escaping @Sendable () -> Date = { Date() }) throws {
        let key = storage.ownershipKey
        try RenewalStorageOwners.shared.acquire(key)
        do {
            if let bytes = try storage.load() {
                let decoded: RenewalLedger
                do { decoded = try JSONDecoder().decode(RenewalLedger.self, from: bytes) }
                catch { throw RenewalCoreError.corruptJournal }
                guard decoded.schemaVersion == 1 else { throw RenewalCoreError.unsupportedJournalVersion }
                if let current = decoded.current {
                    try RenewalVerification.validateTargets(current.attempts.map(\.target))
                    if let owner = current.workflowOwnerID, UUID(uuidString: owner) == nil {
                        throw RenewalCoreError.corruptJournal
                    }
                    guard (current.networkPolicy == .switchAndRestore) == current.networkRecovery.required,
                          current.phase != .finished || !current.networkRecovery.isPending,
                          current.networkPolicy != .switchAndRestore || current.phase == .finished || current.networkRecovery.isPending else {
                        throw RenewalCoreError.corruptJournal
                    }
                }
                ledger = decoded
            } else {
                ledger = RenewalLedger()
            }
        } catch {
            RenewalStorageOwners.shared.release(key)
            throw error
        }
        self.storage = storage
        ownershipKey = key
        self.clock = clock
        self.automaticThreshold = max(0, automaticThreshold)
        self.planLifetime = max(1, planLifetime)
    }

    deinit { RenewalStorageOwners.shared.release(ownershipKey) }

    public func snapshot() -> RenewalSnapshot {
        RenewalSnapshot(current: ledger.current, nativeWorkerActive: worker != nil,
                        journalRevision: ledger.revision)
    }

    public func completedRuns() -> [RenewalRun] {
        ledger.history + (ledger.current?.phase == .finished ? [ledger.current!] : [])
    }

    /// A plan is deliberately not persisted and acquires no busy lease. Abandoning it cannot block entry.
    public func prepare(mode: RenewalMode, targets: [RenewalTarget],
                        networkPolicy: RenewalNetworkPolicy = .switchAndRestore,
                        networkRestoreTarget: NetworkRestoreTarget? = nil,
                        workflowOwnerID: String? = nil) throws -> RenewalPreparation {
        try RenewalVerification.validateTargets(targets)
        let owner = networkPolicy == .switchAndRestore ? try validWorkflowOwner(workflowOwnerID) : nil
        if let networkRestoreTarget, !networkRestoreTarget.isValidRestoreTarget {
            throw RenewalCoreError.invalidNetworkRestoreTarget
        }
        if worker != nil, let current = ledger.current { return .busy(runID: current.id) }
        if let current = ledger.current, current.phase != .finished {
            return .recoveryRequired(runID: current.id)
        }
        let now = clock()
        if mode == .automatic {
            let verified = targets.compactMap { target -> VerifiedRenewal? in
                guard !target.installationFingerprint.isEmpty,
                      let evidence = ledger.latestVerified[target.app.rawValue],
                      RenewalVerification.usableForPolicy(evidence, target: target, now: now) else { return nil }
                return evidence
            }
            if verified.count == targets.count, let earliest = verified.map(\.earliestExpiration).min(),
               earliest.timeIntervalSince(now) > automaticThreshold {
                return .notDue(earliestExpiration: earliest,
                               nextEligibleAt: earliest.addingTimeInterval(-automaticThreshold))
            }
        }
        return .ready(RenewalPlan(id: UUID().uuidString, mode: mode, targets: targets, createdAt: now,
                                  expiresAt: now.addingTimeInterval(planLifetime),
                                  journalRevision: ledger.revision, networkPolicy: networkPolicy,
                                  networkRestoreTarget: networkRestoreTarget, workflowOwnerID: owner))
    }

    /// This durable write must complete before Shortcuts changes either VPN.
    @discardableResult
    public func beginNetworkChange(_ plan: RenewalPlan) throws -> RenewalRun {
        guard plan.networkPolicy == .switchAndRestore else { throw RenewalCoreError.invalidPhase }
        return try begin(plan)
    }

    /// Fixed-network native validation: no VPN change or restoration obligation is implied.
    @discardableResult
    public func beginNativeOnly(_ plan: RenewalPlan) throws -> RenewalRun {
        guard plan.networkPolicy == .keepCurrent else { throw RenewalCoreError.invalidPhase }
        return try begin(plan)
    }

    private func begin(_ plan: RenewalPlan) throws -> RenewalRun {
        try RenewalVerification.validateTargets(plan.targets)
        let owner = plan.networkPolicy == .switchAndRestore ? try validWorkflowOwner(plan.workflowOwnerID) : nil
        if let target = plan.networkRestoreTarget, !target.isValidRestoreTarget {
            throw RenewalCoreError.invalidNetworkRestoreTarget
        }
        guard worker == nil else { throw RenewalCoreError.nativeWorkerStillActive }
        guard ledger.current == nil || ledger.current?.phase == .finished else {
            throw RenewalCoreError.recoveryRequired
        }
        guard plan.journalRevision == ledger.revision else { throw RenewalCoreError.stalePlan }
        let now = clock()
        guard now <= plan.expiresAt, plan.createdAt <= now else { throw RenewalCoreError.expiredPlan }
        let previous = ledger.current
        let hasIncompleteResults = previous?.attempts.contains { attempt in
            attempt.requiresReverification || attempt.state != .verified ||
                attempt.verification?.nativeCompletionConfirmed != true ||
                attempt.nativeCompletion == nil || attempt.preparedProfiles == nil
        } ?? false
        let retrySource = previous.flatMap {
            hasIncompleteResults || !$0.failures.isEmpty || $0.cancellationRequested ? $0.id : nil
        }
        let run = RenewalRun(id: plan.id, mode: plan.mode, createdAt: now, targets: plan.targets,
                             networkPolicy: plan.networkPolicy, retryOfRunID: retrySource,
                             networkRestoreTarget: plan.networkRestoreTarget, workflowOwnerID: owner)
        try commit { draft in
            if let old = draft.current { draft.history.append(old) }
            draft.current = run
        }
        cancellationRequestedInProcess = false
        return run
    }

    /// Business failures return per-app values. Thrown errors are caller/protocol errors before work.
    public func execute(runID: String, driver: any RenewalDeviceDriver,
                        workflowOwnerID: String? = nil) async throws -> RenewalExecutionResult {
        guard let current = ledger.current, current.id == runID else { throw RenewalCoreError.wrongRun }
        try requireWorkflowOwner(current, workflowOwnerID)
        if let worker { return try await worker.value }
        guard current.phase == .networkChangePending else { throw RenewalCoreError.invalidPhase }
        activeDriver = driver
        let task = Task { try await self.performNativeRun(runID: runID, driver: driver) }
        worker = task
        defer { worker = nil; activeDriver = nil }
        return try await task.value
    }

    /// A cold journal is not busy. Reconciliation reads only; it never retries a native installation.
    public func reconcileInterruptedRun(runID: String,
                                        driver: any RenewalDeviceDriver,
                                        workflowOwnerID: String? = nil) async throws -> RenewalExecutionResult {
        guard let current = ledger.current, current.id == runID else { throw RenewalCoreError.wrongRun }
        try requireWorkflowOwner(current, workflowOwnerID)
        if let worker { return try await worker.value }
        guard current.phase != .finished else { throw RenewalCoreError.invalidPhase }
        activeDriver = driver
        let task = Task { try await self.performReconciliation(runID: runID, driver: driver) }
        worker = task
        defer { worker = nil; activeDriver = nil }
        return try await task.value
    }

    /// Controlled in-app cancellation. A Shortcut global Stop/process kill cannot promise this method runs.
    public func requestCancellation(runID: String, workflowOwnerID: String? = nil) async throws {
        guard let current = ledger.current, current.id == runID, current.phase != .finished else {
            throw RenewalCoreError.wrongRun
        }
        try requireWorkflowOwner(current, workflowOwnerID)
        cancellationRequestedInProcess = true
        do {
            try changeRun(runID) { run in run.cancellationRequested = true }
        } catch {
            await activeDriver?.requestNativeCancellation()
            throw error
        }
        await activeDriver?.requestNativeCancellation()
        if worker == nil {
            let now = clock()
            try changeRun(runID) { run in
                // The awaited cancellation request above may permit an explicit
                // takeover. An old caller cannot write the new owner's phase.
                try requireWorkflowOwner(run, workflowOwnerID)
                for index in run.attempts.indices where run.attempts[index].state == .notStarted {
                    run.attempts[index].state = .cancelled
                }
                run.phase = run.networkPolicy == .keepCurrent ? .finished : .awaitingNetworkRestoration
                if run.phase == .finished { run.finishedAt = now }
            }
        }
    }

    /// An accepted Set VPN action is recorded as a request, never as proof of a connection.
    public func recordRestorationRequestAccepted(runID: String, workflowOwnerID: String? = nil) throws {
        guard worker == nil else { throw RenewalCoreError.nativeWorkerStillActive }
        guard let current = ledger.current, current.id == runID else { throw RenewalCoreError.wrongRun }
        try requireWorkflowOwner(current, workflowOwnerID)
        let now = clock()
        try changeRun(runID) { run in
            guard run.networkPolicy == .switchAndRestore, run.phase == .awaitingNetworkRestoration else {
                throw RenewalCoreError.invalidPhase
            }
            run.networkRecovery.requestAcceptedAt = now
        }
    }

    /// Only an explicit, recent state observation can discharge the pending restoration obligation.
    public func confirmNetworkRestored(runID: String, observation: NetworkRestorationObservation,
                                      workflowOwnerID: String? = nil) throws {
        guard worker == nil else { throw RenewalCoreError.nativeWorkerStillActive }
        guard let current = ledger.current, current.id == runID else { throw RenewalCoreError.wrongRun }
        try requireWorkflowOwner(current, workflowOwnerID)
        let now = clock()
        try changeRun(runID) { run in
            let target = run.networkRecovery.restoreTarget ??
                NetworkRestoreTarget(quantumultX: .connected, localDevVPN: .disconnected)
            func matches(_ observed: VPNConnectionState, _ expected: VPNConnectionState) -> Bool {
                observed == expected ||
                    ([.notConnected, .disconnected].contains(observed) &&
                     [.notConnected, .disconnected].contains(expected))
            }
            guard run.networkPolicy == .switchAndRestore, run.phase == .awaitingNetworkRestoration,
                  let requestedAt = run.networkRecovery.requestAcceptedAt,
                  target.isValidRestoreTarget, observation.source.provesState,
                  matches(observation.quantumultX, target.quantumultX),
                  matches(observation.localDevVPN, target.localDevVPN),
                  target.quantumultXOnDemand == nil || observation.quantumultXOnDemand == target.quantumultXOnDemand,
                  target.localDevVPNOnDemand == nil || observation.localDevVPNOnDemand == target.localDevVPNOnDemand,
                  target.quantumultXName == nil || observation.quantumultXName == target.quantumultXName,
                  target.localDevVPNName == nil || observation.localDevVPNName == target.localDevVPNName,
                  observation.observedAt >= requestedAt.addingTimeInterval(
                    observation.source == .systemShortcutVPNQuery ? -0.001 : 0),
                  requestedAt <= now, observation.observedAt >= now.addingTimeInterval(-60),
                  observation.observedAt <= now.addingTimeInterval(60) else {
                throw RenewalCoreError.networkRestorationUnverified
            }
            run.networkRecovery.restoredObservation = observation
            run.phase = .finished
            run.finishedAt = now
        }
    }

    /// Only an explicitly confirmed manual caller can replace another invocation.
    /// A persisted running phase with no in-process worker is cold interruption;
    /// it may be taken over, but execute still rejects it until read-only recovery.
    @discardableResult
    public func takeWorkflowOwnership(runID: String, workflowOwnerID: String,
                                      mode: RenewalMode, allowRecoveryTakeover: Bool) throws -> RenewalRun {
        let owner = try validWorkflowOwner(workflowOwnerID)
        guard worker == nil else { throw RenewalCoreError.nativeWorkerStillActive }
        guard let current = ledger.current, current.id == runID,
              current.networkPolicy == .switchAndRestore, current.phase != .finished else {
            throw RenewalCoreError.wrongRun
        }
        if current.workflowOwnerID.flatMap({ UUID(uuidString: $0)?.uuidString }) == owner { return current }
        guard mode == .manual, allowRecoveryTakeover else { throw RenewalCoreError.recoveryTakeoverNotAllowed }
        try changeRun(runID) { $0.workflowOwnerID = owner }
        return ledger.current!
    }

    private func validWorkflowOwner(_ value: String?) throws -> String {
        guard let value, let owner = UUID(uuidString: value) else { throw RenewalCoreError.invalidWorkflowOwner }
        return owner.uuidString
    }

    private func requireWorkflowOwner(_ run: RenewalRun, _ value: String?) throws {
        guard run.networkPolicy == .switchAndRestore else { return }
        let owner = try validWorkflowOwner(value)
        guard let stored = run.workflowOwnerID, UUID(uuidString: stored)?.uuidString == owner else {
            throw RenewalCoreError.workflowOwnerMismatch
        }
    }

    private var isCancelled: Bool {
        cancellationRequestedInProcess || ledger.current?.cancellationRequested == true
    }

    private func recordPrepared(_ prepared: PreparedProfileSet, runID: String,
                                target: RenewalTarget) throws {
        guard !isCancelled else { throw CancellationError() }
        try RenewalVerification.validatePrepared(prepared, target: target, now: clock())
        try changeAttempt(runID, app: target.app) { attempt in
            guard attempt.state == .nativeRunning, attempt.preparedProfiles == nil else {
                throw RenewalCoreError.nativeProtocolViolation("beforeInstallCalledMoreThanOnce")
            }
            attempt.preparedProfiles = prepared
            attempt.state = .profilesPrepared
        }
        // Actor re-entry/cancellation can happen around the asynchronous callback in the integration.
        guard !isCancelled else { throw CancellationError() }
    }

    private func performNativeRun(runID: String,
                                  driver: any RenewalDeviceDriver) async throws -> RenewalExecutionResult {
        var infrastructureFailure: RenewalFailure?
        do {
            guard let run = ledger.current, run.id == runID else { throw RenewalCoreError.wrongRun }
            // Prove native communication and both app identities before the first installation.
            for attempt in run.attempts {
                if isCancelled { break }
                do {
                    let started = clock()
                    let observation = try await driver.readDeviceProfiles(target: attempt.target)
                    guard observation.target == attempt.target, observation.applicationPresenceConfirmed,
                          observation.observedAt >= started.addingTimeInterval(-0.001),
                          observation.observedAt <= clock().addingTimeInterval(60) else {
                        throw RenewalCoreError.verificationFailed("preflightDeviceIdentityUnavailable")
                    }
                } catch {
                    let failure = makeFailure(error, now: clock())
                    try changeAttempt(runID, app: attempt.target.app) { current in
                        current.state = .failed
                        current.failures.append(failure)
                    }
                    throw error
                }
            }
            for target in run.attempts.map(\.target) {
                if isCancelled { break }
                if try await reuseConfirmedResult(runID: runID, target: target, driver: driver) { continue }
                if isCancelled { break }
                let started = clock()
                let previous = ledger.latestVerified[target.app.rawValue]
                try commit { draft in
                    guard var run = draft.current, run.id == runID else { throw RenewalCoreError.wrongRun }
                    run.phase = .running
                    let index = run.attempts.firstIndex(where: { $0.target.app == target.app })!
                    run.attempts[index].nativeStartedAt = started
                    run.attempts[index].state = .nativeRunning
                    draft.current = run
                    draft.latestVerified.removeValue(forKey: target.app.rawValue)
                }
                do {
                    let completion = try await driver.refreshNative(target: target) { prepared in
                        try await self.recordPrepared(prepared, runID: runID, target: target)
                    }
                    guard let prepared = ledger.current?.attempts.first(where: { $0.target.app == target.app })?.preparedProfiles,
                          completion.operationID == prepared.operationID, completion.target == target,
                          completion.completedAt >= started.addingTimeInterval(-0.001),
                          completion.completedAt <= clock().addingTimeInterval(60) else {
                        throw RenewalCoreError.nativeProtocolViolation("missingPreparedProfilesOrWrongCompletion")
                    }
                    try changeAttempt(runID, app: target.app) { attempt in
                        attempt.nativeCompletion = completion
                        attempt.state = .nativeCompleted
                    }
                    // Stop new operations after a controlled cancellation; the completed receipt remains recoverable.
                    if isCancelled { break }
                    let observation = try await driver.readDeviceProfiles(target: target)
                    let verified = try RenewalVerification.verify(prepared: prepared, completion: completion,
                        observation: observation, notBefore: completion.completedAt,
                        previous: previous, now: clock())
                    try storeVerification(verified, runID: runID, app: target.app, recovered: false)
                } catch {
                    if let persistenceFailure = lastPersistenceFailure {
                        infrastructureFailure = persistenceFailure
                        break
                    }
                    let failure = makeFailure(error, now: clock())
                    if failure.kind == .storage { throw error }
                    try changeAttempt(runID, app: target.app) { attempt in
                        attempt.failures.append(failure)
                        attempt.state = failure.kind == .cancellation ? .cancelled : .failed
                    }
                    if failure.kind == .storage || failure.kind == .protocolViolation { throw error }
                }
            }
        } catch {
            infrastructureFailure = makeFailure(error, now: clock())
        }
        return completeNativePhase(runID: runID, infrastructureFailure: infrastructureFailure)
    }

    private func performReconciliation(runID: String,
                                        driver: any RenewalDeviceDriver) async throws -> RenewalExecutionResult {
        var infrastructureFailure: RenewalFailure?
        guard let saved = ledger.current, saved.id == runID else { throw RenewalCoreError.wrongRun }
        for attempt in saved.attempts {
            do {
                guard let prepared = attempt.preparedProfiles else {
                    if attempt.state == .nativeRunning || attempt.state == .profilesPrepared {
                        let failure = RenewalFailure(kind: .interrupted, machineCode: "noExpectedProfileEvidence",
                                                     recordedAt: clock())
                        try changeAttempt(runID, app: attempt.target.app) { current in
                            current.state = .interruptedUnknown
                            current.failures.append(failure)
                        }
                    }
                    continue
                }
                let requestedAt = clock()
                let observation = try await driver.readDeviceProfiles(target: attempt.target)
                let verified = try RenewalVerification.verify(prepared: prepared, completion: attempt.nativeCompletion,
                    observation: observation, notBefore: requestedAt,
                    previous: ledger.latestVerified[attempt.target.app.rawValue], now: clock())
                try storeVerification(verified, runID: runID, app: attempt.target.app,
                                      recovered: attempt.nativeCompletion == nil)
            } catch {
                let failure = makeFailure(error, now: clock())
                do {
                    try commit { draft in
                        guard var run = draft.current, run.id == runID,
                              let index = run.attempts.firstIndex(where: { $0.target.app == attempt.target.app }) else {
                            throw RenewalCoreError.wrongRun
                        }
                        var current = run.attempts[index]
                        if current.verification == nil { current.state = .interruptedUnknown }
                        current.requiresReverification = true
                        current.failures.append(failure)
                        run.attempts[index] = current
                        draft.current = run
                        draft.latestVerified.removeValue(forKey: attempt.target.app.rawValue)
                    }
                } catch {
                    infrastructureFailure = makeFailure(error, now: clock())
                    break
                }
            }
        }
        return completeNativePhase(runID: runID, infrastructureFailure: infrastructureFailure)
    }

    private func completeNativePhase(runID: String,
                                      infrastructureFailure: RenewalFailure?) -> RenewalExecutionResult {
        var fault = infrastructureFailure
        do {
            let cancelled = isCancelled
            let now = clock()
            try changeRun(runID) { run in
                if cancelled {
                    run.cancellationRequested = true
                    for index in run.attempts.indices where run.attempts[index].state == .notStarted {
                        run.attempts[index].state = .cancelled
                    }
                }
                run.phase = run.networkPolicy == .keepCurrent ? .finished : .awaitingNetworkRestoration
                if run.phase == .finished { run.finishedAt = now }
                if let fault { run.failures.append(fault) }
            }
        } catch {
            fault = makeFailure(error, now: clock())
        }
        // The method is reached only after each concrete driver call has returned. It never races a timeout.
        return RenewalExecutionResult(run: ledger.current!, infrastructureFailure: fault,
                                      nativeWorkerDrained: true)
    }

    private func storeVerification(_ verified: VerifiedRenewal, runID: String,
                                    app: RenewalApp, recovered: Bool) throws {
        try commit { draft in
            guard var run = draft.current, run.id == runID,
                  let index = run.attempts.firstIndex(where: { $0.target.app == app }) else {
                throw RenewalCoreError.wrongRun
            }
            run.attempts[index].verification = verified
            run.attempts[index].requiresReverification = false
            run.attempts[index].state = recovered ? .reconciledInstalled : .verified
            draft.current = run
            draft.latestVerified[app.rawValue] = verified
        }
    }

    /// Reuse is limited to the immediately retried task, with its actual native callback and exact
    /// prepared profiles. A fresh device query is mandatory; a historical outcome is never enough.
    private func reuseConfirmedResult(runID: String, target: RenewalTarget,
                                      driver: any RenewalDeviceDriver) async throws -> Bool {
        guard let source = confirmedRetryEvidence(runID: runID, target: target) else { return false }
        let (sourceID, prepared, completion, oldProof) = source

        let verified: VerifiedRenewal
        do {
            let requestedAt = clock()
            let observation = try await driver.readDeviceProfiles(target: target)
            verified = try RenewalVerification.verify(prepared: prepared, completion: completion,
                observation: observation, notBefore: requestedAt, previous: oldProof, now: clock())
        } catch {
            // A failed recheck does not justify a skip. Keep its diagnostic, then perform a new native refresh.
            let failure = makeFailure(error, now: clock())
            try changeAttempt(runID, app: target.app) { attempt in attempt.failures.append(failure) }
            return false
        }
        guard !isCancelled else { return false }
        try commit { draft in
            guard var current = draft.current, current.id == runID,
                  let index = current.attempts.firstIndex(where: { $0.target == target }),
                  current.attempts[index].state == .notStarted else { throw RenewalCoreError.wrongRun }
            current.phase = .running
            current.attempts[index].preparedProfiles = prepared
            current.attempts[index].nativeCompletion = completion
            current.attempts[index].verification = verified
            current.attempts[index].reusedFromRunID = sourceID
            current.attempts[index].requiresReverification = false
            current.attempts[index].state = .verified
            draft.current = current
            draft.latestVerified[target.app.rawValue] = verified
        }
        return true
    }

    private func confirmedRetryEvidence(runID: String, target: RenewalTarget)
        -> (String, PreparedProfileSet, NativeRefreshCompletion, VerifiedRenewal)? {
        guard let run = ledger.current, run.id == runID, !target.installationFingerprint.isEmpty else { return nil }
        var sourceID = run.retryOfRunID
        var visited = Set<String>()
        while let candidateID = sourceID {
            guard visited.insert(candidateID).inserted,
                  let sourceRun = ledger.history.last(where: { $0.id == candidateID }) else { return nil }
            // Follow only this retry's ancestry, never an unrelated historical successful task.
            sourceID = sourceRun.retryOfRunID
            guard let source = sourceRun.attempts.first(where: { $0.target.app == target.app }),
                  source.target == target, source.state == .verified,
                  let prepared = source.preparedProfiles, prepared.target == target,
                  let completion = source.nativeCompletion, completion.target == target,
                  completion.operationID == prepared.operationID,
                  let proof = source.verification, proof.target == target, proof.nativeCompletionConfirmed,
                  proof.mainProfileUUID == prepared.mainProfileUUID, proof.profiles == prepared.profiles,
                  proof.verifiedAt >= completion.completedAt.addingTimeInterval(-0.001),
                  RenewalVerification.usableForPolicy(proof, target: target, now: clock()) else { continue }
            return (candidateID, prepared, completion, proof)
        }
        return nil
    }

    private func changeAttempt(_ runID: String, app: RenewalApp,
                                _ body: (inout RenewalAttempt) throws -> Void) throws {
        try changeRun(runID) { run in
            guard let index = run.attempts.firstIndex(where: { $0.target.app == app }) else {
                throw RenewalCoreError.invalidTargets
            }
            try body(&run.attempts[index])
        }
    }

    private func changeRun(_ runID: String, _ body: (inout RenewalRun) throws -> Void) throws {
        try commit { draft in
            guard var run = draft.current, run.id == runID else { throw RenewalCoreError.wrongRun }
            try body(&run)
            draft.current = run
        }
    }

    private func commit(_ body: (inout RenewalLedger) throws -> Void) throws {
        var draft = ledger
        try body(&draft)
        draft.revision += 1
        let encoder = JSONEncoder()
        encoder.outputFormatting = [.sortedKeys]
        do {
            let bytes = try encoder.encode(draft)
            try storage.save(bytes)
            guard try storage.load() == bytes else { throw RenewalCoreError.journalWriteUnverified }
        } catch {
            let underlying = error as NSError
            lastPersistenceFailure = RenewalFailure(kind: .storage, machineCode: "journalPersistenceFailed",
                domain: underlying.domain, code: underlying.code, recordedAt: clock())
            throw RenewalJournalIOFailure(domain: underlying.domain, code: underlying.code)
        }
        lastPersistenceFailure = nil
        ledger = draft
    }

    private func makeFailure(_ error: Error, now: Date) -> RenewalFailure {
        if let journal = error as? RenewalJournalIOFailure {
            return RenewalFailure(kind: .storage, machineCode: "journalPersistenceFailed",
                                  domain: journal.domain, code: journal.code, recordedAt: now)
        }
        if error is CancellationError || (error as? RenewalCoreError) == .cancelled {
            return RenewalFailure(kind: .cancellation, machineCode: "controlledCancellation", recordedAt: now)
        }
        if let backend = error as? RenewalBackendFailure {
            return RenewalFailure(kind: .nativeOperation, machineCode: "nativeOperationFailed",
                                  domain: backend.domain, code: backend.code,
                                  safeMessage: backend.safeMessage, recordedAt: now)
        }
        if let core = error as? RenewalCoreError {
            switch core {
            case .verificationFailed(let code):
                return RenewalFailure(kind: .verification, machineCode: code, recordedAt: now)
            case .invalidPreparedProfiles(let code), .nativeProtocolViolation(let code):
                return RenewalFailure(kind: .protocolViolation, machineCode: code, recordedAt: now)
            default:
                return RenewalFailure(kind: .storage, machineCode: String(describing: core), recordedAt: now)
            }
        }
        let native = error as NSError
        // Raw localized descriptions can contain pairing contents or account data. Preserve exact domain/code.
        return RenewalFailure(kind: .nativeOperation, machineCode: "nativeOperationFailed",
                              domain: native.domain, code: native.code, recordedAt: now)
    }
}

import Foundation

enum RenewalVerification {
    static func usableForPolicy(_ evidence: VerifiedRenewal, target: RenewalTarget, now: Date) -> Bool {
        guard evidence.target == target, evidence.verifiedAt <= now,
              evidence.earliestExpiration > now,
              let earliest = evidence.profiles.map(\.expiresAt).min(),
              abs(earliest.timeIntervalSince(evidence.earliestExpiration)) < 0.001 else { return false }
        let expected = PreparedProfileSet(operationID: "policy-validation", target: target,
            mainProfileUUID: evidence.mainProfileUUID, profiles: evidence.profiles)
        do {
            try validatePrepared(expected, target: target, now: now)
            return true
        } catch { return false }
    }

    static func validateTargets(_ targets: [RenewalTarget]) throws {
        guard targets.map(\.app) == RenewalApp.executionOrder,
              Set(targets.map(\.installedBundleIdentifier)).count == targets.count,
              targets.allSatisfy({ !$0.originalBundleIdentifier.isEmpty &&
                  !$0.installedBundleIdentifier.isEmpty && !$0.teamIdentifier.isEmpty &&
                  isSHA256($0.signingCertificateSHA256) }) else {
            throw RenewalCoreError.invalidTargets
        }
    }

    static func validatePrepared(_ prepared: PreparedProfileSet, target: RenewalTarget, now: Date) throws {
        guard prepared.target == target, !prepared.operationID.isEmpty, !prepared.profiles.isEmpty,
              Set(prepared.profiles.map(\.uuid)).count == prepared.profiles.count else {
            throw RenewalCoreError.invalidPreparedProfiles("identityOrProfileSet")
        }
        guard let main = prepared.profiles.first(where: { $0.uuid == prepared.mainProfileUUID }),
              main.bundleIdentifier == target.installedBundleIdentifier else {
            // Wildcard profiles are intentionally unsupported until their entitlement matching is implemented.
            throw RenewalCoreError.invalidPreparedProfiles("mainProfileIdentity")
        }
        for profile in prepared.profiles {
            guard !profile.uuid.isEmpty, !profile.bundleIdentifier.isEmpty,
                  !profile.bundleIdentifier.contains("*"), profile.teamIdentifier == target.teamIdentifier,
                  profile.certificateSHA256.contains(target.signingCertificateSHA256),
                  profile.certificateSHA256.allSatisfy(isSHA256), isSHA256(profile.sha256),
                  profile.createdAt < profile.expiresAt, profile.createdAt <= now.addingTimeInterval(60),
                  profile.expiresAt > now else {
                throw RenewalCoreError.invalidPreparedProfiles("invalidProfileEvidence")
            }
        }
    }

    static func verify(prepared: PreparedProfileSet, completion: NativeRefreshCompletion?,
                       observation: DeviceProfileObservation, notBefore: Date,
                       previous: VerifiedRenewal?, now: Date) throws -> VerifiedRenewal {
        try validatePrepared(prepared, target: prepared.target, now: now)
        guard observation.target == prepared.target, observation.applicationPresenceConfirmed,
              observation.observedAt >= notBefore.addingTimeInterval(-0.001),
              observation.observedAt <= now.addingTimeInterval(60) else {
            throw RenewalCoreError.verificationFailed("missingCurrentDeviceIdentity")
        }
        if let completion {
            guard completion.target == prepared.target, completion.operationID == prepared.operationID,
                  completion.completedAt <= observation.observedAt.addingTimeInterval(0.001) else {
                throw RenewalCoreError.nativeProtocolViolation("completionDoesNotMatchPreparedProfiles")
            }
        }
        for expected in prepared.profiles {
            let matches = observation.profiles.filter { $0.uuid == expected.uuid }
            guard matches.count == 1, let actual = matches.first,
                  actual.bundleIdentifier == expected.bundleIdentifier,
                  actual.teamIdentifier == expected.teamIdentifier,
                  actual.sha256 == expected.sha256,
                  actual.certificateSHA256 == expected.certificateSHA256,
                  abs(actual.createdAt.timeIntervalSince(expected.createdAt)) < 0.001,
                  abs(actual.expiresAt.timeIntervalSince(expected.expiresAt)) < 0.001 else {
                throw RenewalCoreError.verificationFailed("deviceProfileDoesNotMatchExpected")
            }
        }
        let expiration = prepared.profiles.map(\.expiresAt).min()!
        let expirationChange: ExpirationChange
        if let previous, previous.target == prepared.target {
            expirationChange = expiration > previous.earliestExpiration ? .extended : .unchangedOrEarlier
        } else {
            expirationChange = .noPreviousEvidence
        }
        return VerifiedRenewal(target: prepared.target, mainProfileUUID: prepared.mainProfileUUID,
                               profiles: prepared.profiles, earliestExpiration: expiration,
                               verifiedAt: observation.observedAt,
                               nativeCompletionConfirmed: completion != nil,
                               expirationChange: expirationChange)
    }

    static func isSHA256(_ value: String) -> Bool {
        value.utf8.count == 64 && value.utf8.allSatisfy {
            (48...57).contains($0) || (97...102).contains($0)
        }
    }
}

import Foundation
import XCTest
@testable import RenewalCore

private actor StartupProbe {
    private var calls = 0
    private var entered: CheckedContinuation<Void, Never>?
    private var release: CheckedContinuation<Void, Never>?
    private var started = false
    private var opened = false

    func start() async {
        calls += 1
        started = true
        entered?.resume()
        entered = nil
        if !opened { await withCheckedContinuation { release = $0 } }
    }

    func waitUntilStarted() async {
        if !started { await withCheckedContinuation { entered = $0 } }
    }

    func finish() {
        opened = true
        release?.resume()
        release = nil
    }

    func count() -> Int { calls }
}

