            XCTFail("A cancelled preparation must not start native renewal")
        }
        await probe.waitUntilStarted()
        control.requestCancellation()
        await probe.finish()
        do {
            try await request.value
            XCTFail("Expected cancellation")
        } catch is CancellationError {}
    }

}

