private func target(_ app: RenewalApp, certificate: String = String(repeating: "a", count: 64)) -> RenewalTarget {
    let original = app == .rustDesk ? "com.bearberni.rustdesk.v2" : "com.SideStore.SideStore"
    return RenewalTarget(app: app, originalBundleIdentifier: original,
                         installedBundleIdentifier: original + ".85TZVFJX88", teamIdentifier: "85TZVFJX88",
                         signingCertificateSHA256: certificate, installationFingerprint: "installed-version-" + app.rawValue)
}

