private func profile(_ target: RenewalTarget, expiresIn: TimeInterval = 7 * 24 * 60 * 60,
                     suffix: String = "") -> ProfileEvidence {
    ProfileEvidence(uuid: target.app.rawValue + suffix,
                    bundleIdentifier: target.installedBundleIdentifier + suffix,
                    teamIdentifier: target.teamIdentifier, certificateSHA256: [target.signingCertificateSHA256],
                    createdAt: testNow.addingTimeInterval(-60), expiresAt: testNow.addingTimeInterval(expiresIn),
                    sha256: String(repeating: target.app == .rustDesk ? "1" : "2", count: 64))
}

private func confirmedAttempt(_ target: RenewalTarget, at date: Date = testNow,
                              profiles: [ProfileEvidence]? = nil) -> RenewalAttempt {
    let values = profiles ?? [profile(target)]
    let prepared = PreparedProfileSet(operationID: "confirmed-" + target.app.rawValue, target: target,
                                     mainProfileUUID: values[0].uuid, profiles: values)
    var attempt = RenewalAttempt(target: target)
    attempt.state = .verified
    attempt.nativeStartedAt = date
    attempt.preparedProfiles = prepared
    attempt.nativeCompletion = NativeRefreshCompletion(operationID: prepared.operationID, target: target, completedAt: date)
    attempt.verification = VerifiedRenewal(target: target, mainProfileUUID: prepared.mainProfileUUID, profiles: values,
        earliestExpiration: values.map(\.expiresAt).min()!, verifiedAt: date,
        nativeCompletionConfirmed: true, expirationChange: .noPreviousEvidence)
    return attempt
}

private final class MemoryStorage: RenewalJournalStorage, @unchecked Sendable {
    let ownershipKey = UUID().uuidString
    private let lock = NSLock()
    private var bytes: Data?
    private var saves = 0
    private var failureSaves = Set<Int>()
    var failAtSave: Int?

    func load() throws -> Data? {
        lock.lock()
        defer { lock.unlock() }
        return bytes
    }

    func save(_ data: Data) throws {
        lock.lock()
        defer { lock.unlock() }
        saves += 1
        if saves == failAtSave || failureSaves.contains(saves) { throw NSError(domain: "TestStorage", code: 28) }
        bytes = data
    }

    func failNextSave() {
        failNextSaves(1)
    }

    func failNextSaves(_ count: Int) {
        lock.lock()
        defer { lock.unlock() }
        if count > 0 { failureSaves.formUnion((saves + 1)...(saves + count)) }
    }
}

private actor NativeGate {
    private var entered = false
    private var open = false
    private var enteredWaiters: [CheckedContinuation<Void, Never>] = []
    private var nativeWaiter: CheckedContinuation<Void, Never>?

    func waitUntilEntered() async {
        if entered { return }
        await withCheckedContinuation { enteredWaiters.append($0) }
    }

    func enterAndWait() async {
        entered = true
        for waiter in enteredWaiters { waiter.resume() }
        enteredWaiters.removeAll()
        if open { return }
        await withCheckedContinuation { nativeWaiter = $0 }
    }

    func release() {
        open = true
        nativeWaiter?.resume()
        nativeWaiter = nil
    }
}

private actor Driver: RenewalDeviceDriver {
    private var events: [String] = []
    private var installed = Set<RenewalApp>()
    private var nativeCalls: [RenewalApp] = []
    private var cancellationRequested = false
    private var readCounts: [RenewalApp: Int] = [:]
    let failNative: Set<RenewalApp>
    let wrongReadback: Set<RenewalApp>
    let failRead: Set<RenewalApp>
    let includeExpiringExtension: Bool
    let gate: NativeGate?
    let initialProfiles: [RenewalApp: [ProfileEvidence]]
    let failReadAt: [RenewalApp: Set<Int>]

    init(failNative: Set<RenewalApp> = [], wrongReadback: Set<RenewalApp> = [], failRead: Set<RenewalApp> = [],
         includeExpiringExtension: Bool = false, gate: NativeGate? = nil,
         initialProfiles: [RenewalApp: [ProfileEvidence]] = [:], failReadAt: [RenewalApp: Set<Int>] = [:]) {
        self.failNative = failNative
        self.wrongReadback = wrongReadback
        self.failRead = failRead
        self.includeExpiringExtension = includeExpiringExtension
        self.gate = gate
        self.initialProfiles = initialProfiles
        self.failReadAt = failReadAt
    }

    func profileSet(for target: RenewalTarget) -> [ProfileEvidence] {
        var values = [profile(target)]
        if includeExpiringExtension && target.app == .rustDesk {
            values.append(profile(target, expiresIn: 24 * 60 * 60, suffix: ".extension"))
        }
        return values
    }

    func refreshNative(target: RenewalTarget,
                       beforeInstall: @escaping @Sendable (PreparedProfileSet) async throws -> Void)
        async throws -> NativeRefreshCompletion {
        let set = PreparedProfileSet(operationID: "operation-" + target.app.rawValue, target: target,
                                     mainProfileUUID: target.app.rawValue, profiles: profileSet(for: target))
        try await beforeInstall(set)
        events.append("native-start-" + target.app.rawValue)
        nativeCalls.append(target.app)
        if target.app == .rustDesk, let gate { await gate.enterAndWait() }
        if cancellationRequested { throw CancellationError() }
        if failNative.contains(target.app) {
            throw RenewalBackendFailure(domain: "NativeTest", code: 1016, safeMessage: "requiresUnlock")
        }
        installed.insert(target.app)
        events.append("native-end-" + target.app.rawValue)
        return NativeRefreshCompletion(operationID: set.operationID, target: target, completedAt: testNow)
    }

    func readDeviceProfiles(target: RenewalTarget) async throws -> DeviceProfileObservation {
        events.append("read-" + target.app.rawValue)
        readCounts[target.app, default: 0] += 1
        if failRead.contains(target.app) || failReadAt[target.app]?.contains(readCounts[target.app]!) == true {
            throw RenewalBackendFailure(domain: "DeviceRead", code: 9, safeMessage: "notReady")
        }
        var values = !installed.contains(target.app) ? initialProfiles[target.app] ?? profileSet(for: target) : profileSet(for: target)
        if installed.contains(target.app), wrongReadback.contains(target.app), let first = values.first {
            values[0] = ProfileEvidence(uuid: first.uuid, bundleIdentifier: first.bundleIdentifier,
                teamIdentifier: first.teamIdentifier, certificateSHA256: first.certificateSHA256,
                createdAt: first.createdAt, expiresAt: first.expiresAt, sha256: String(repeating: "f", count: 64))
        }
        return DeviceProfileObservation(target: target, profiles: values,
                                        applicationPresenceConfirmed: true, observedAt: testNow)
    }

    func requestNativeCancellation() async { cancellationRequested = true }
    func calls() -> [RenewalApp] { nativeCalls }
    func trace() -> [String] { events }
    func reads(for app: RenewalApp) -> Int { readCounts[app, default: 0] }
}

