    func testRecoveryInfrastructureFaultCannotBecomePersistedCompletionStatus() async throws {
        for policy in [RenewalNetworkPolicy.keepCurrent, .switchAndRestore] {
            let storage = MemoryStorage()
            var interrupted = RenewalRun(id: "saved-both-verified-" + policy.rawValue, mode: .manual,
                createdAt: testNow, targets: testTargets, networkPolicy: policy, workflowOwnerID: testWorkflowOwner)
            interrupted.phase = .running
            interrupted.attempts = testTargets.map { confirmedAttempt($0) }
            var ledger = RenewalLedger()
            ledger.current = interrupted
            try storage.save(JSONEncoder().encode(ledger))
            let engine = try makeEngine(storage)
            // Lose both the new verification write and the write recording that failure. The final
            // phase/fault write then succeeds, retaining the original per-app verified results.
            storage.failNextSaves(2)
            let result = try await engine.reconcileInterruptedRun(runID: interrupted.id, driver: Driver(), workflowOwnerID: testWorkflowOwner)
            XCTAssertEqual(result.infrastructureFailure?.kind, .storage)
            XCTAssertEqual(result.run.attempts.map(\.state), [.verified, .verified])
            XCTAssertEqual(result.run.outcome, .succeeded) // Profile history is not whole-task completion.
            if policy == .switchAndRestore { try await restore(engine, runID: interrupted.id) }
            let snapshot = await engine.snapshot()
            XCTAssertEqual(snapshot.current?.failures.last?.kind, .storage)
            XCTAssertFalse(snapshot.current?.nativeValidationCompleted ?? true)
            XCTAssertFalse(snapshot.current?.fullyCompleted ?? true)
            let persisted = try JSONDecoder().decode(RenewalLedger.self, from: XCTUnwrap(storage.load()))
            XCTAssertFalse(persisted.current?.nativeValidationCompleted ?? true)
            XCTAssertFalse(persisted.current?.fullyCompleted ?? true)

            // The fault is not a permanent lock. A new run independently verifies both saved real
            // completions, reuses them without native calls, and reports its own fault-free status.
            let nextPlan = try await newPlan(engine, policy: .keepCurrent)
            _ = try await engine.beginNativeOnly(nextPlan)
            let nextDriver = Driver()
            let next = try await engine.execute(runID: nextPlan.id, driver: nextDriver, workflowOwnerID: testWorkflowOwner)
            let calls = await nextDriver.calls()
            XCTAssertTrue(calls.isEmpty)
            XCTAssertTrue(next.run.nativeValidationCompleted)
            XCTAssertTrue(next.run.attempts.allSatisfy { $0.reusedFromRunID == interrupted.id })
            let history = await engine.completedRuns()
            XCTAssertEqual(history[0].failures.last?.kind, .storage)
        }
    }
}

