@available(iOS 27.0, tvOS 27.0, *)
enum PersonalRenewalAction: String, AppEnum {
    case newWorkflowOwner
    case checkReadiness
    case nativeValidation
    case status
    case cancel
    case prepareWorkflow
    case executeWorkflow
    case recoverWorkflow
    case recordRestorationRequest
    case confirmRestoration

    static var typeDisplayRepresentation: TypeDisplayRepresentation = "续签操作"
    static var caseDisplayRepresentations: [Self: DisplayRepresentation] = [
        .newWorkflowOwner: "创建本次入口编号",
        .checkReadiness: "检查续签准备",
        .nativeValidation: "验证原生续签",
        .status: "读取本次状态",
        .cancel: "请求取消",
        .prepareWorkflow: "准备完整续签",
        .executeWorkflow: "执行完整续签",
        .recoverWorkflow: "恢复中断任务",
        .recordRestorationRequest: "记录网络恢复请求",
        .confirmRestoration: "核对网络恢复结果"
    ]
}

@available(iOS 27.0, tvOS 27.0, *)
enum PersonalRenewalMode: String, AppEnum {
    case manual, automatic
    static var typeDisplayRepresentation: TypeDisplayRepresentation = "触发方式"
    static var caseDisplayRepresentations: [Self: DisplayRepresentation] = [
        .manual: "手动", .automatic: "自动"
    ]
}

/// Shortcuts owns system VPN actions; this entry owns native work and its durable result.
@available(iOS 27.0, tvOS 27.0, *)
struct PersonalRenewalIntent: LongRunningIntent, CancellableIntent {
    static var title: LocalizedStringResource = "续签 RustDesk V2 与 SideStore"
    static var description = IntentDescription("检查准备或执行并核验两项原生续签。")
    static var allowedExecutionTargets: IntentExecutionTargets { [.main] }
    static var supportedModes: IntentModes { [.foreground(.immediate)] }

    @Parameter(title: "操作", default: .nativeValidation)
    var action: PersonalRenewalAction

    @Parameter(title: "运行编号", default: "")
    var runID: String

    @Parameter(title: "触发方式", default: .manual)
    var mode: PersonalRenewalMode

    @Parameter(title: "系统 VPN 查询结果", default: "")
    var networkObservation: String

    @Parameter(title: "本次入口编号", default: "")
    var workflowOwnerID: String
    @Parameter(title: "已确认旧快捷指令停止", default: false)
    var allowRecoveryTakeover: Bool

    @Parameter(title: "Quantumult X 配置名", default: "Quantumult X")
    var quantumultXName: String
    @Parameter(title: "LocalDevVPN 配置名", default: "LocalDevVPN")
    var localDevVPNName: String
    @Parameter(title: "Quantumult X 已连接")
    var quantumultXConnected: Bool?
    @Parameter(title: "LocalDevVPN 已连接")
    var localDevVPNConnected: Bool?
    @Parameter(title: "Quantumult X 按需连接")
    var quantumultXOnDemand: Bool?
    @Parameter(title: "LocalDevVPN 按需连接")
    var localDevVPNOnDemand: Bool?
    @Parameter(title: "系统当前 VPN 名称")
    var currentVPNNames: [String]?
    @Parameter(title: "系统查询时间")
    var observationDate: Date?

    static var parameterSummary: some ParameterSummary {
        Summary("\(\.$action)")
    }

    func perform() async throws -> some IntentResult & ReturnsValue<String> {
        let value: String
        switch action {
        case .newWorkflowOwner:
            value = await PersonalRenewalService.shared.newWorkflowOwnerJSON()
        case .status:
            value = await PersonalRenewalService.shared.statusJSON()
        case .cancel:
            value = await PersonalRenewalService.shared.cancelJSON(workflowOwnerID: workflowOwnerID)
        case .recordRestorationRequest:
            value = await PersonalRenewalService.shared.recordRestorationRequestJSON(runID: runID, workflowOwnerID: workflowOwnerID)
        case .confirmRestoration:
            value = await PersonalRenewalService.shared.confirmRestorationJSON(
                runID: runID, observationJSON: observationPayload, workflowOwnerID: workflowOwnerID)
        case .checkReadiness, .nativeValidation, .prepareWorkflow, .executeWorkflow, .recoverWorkflow:
            let control = RenewalInvocationControl()
            do {
                value = try await performBackgroundTask {
                    switch self.action {
                    case .prepareWorkflow:
                        self.progress.totalUnitCount = 1
                        let result = await PersonalRenewalService.shared.prepareWorkflowJSON(
                            mode: self.mode == .automatic ? .automatic : .manual,
                            observationJSON: self.observationPayload, control: control,
                            workflowOwnerID: self.workflowOwnerID, allowRecoveryTakeover: self.allowRecoveryTakeover)
                        self.progress.completedUnitCount = 1
                        return result
                    case .checkReadiness:
                        return await PersonalRenewalService.shared.readinessJSON(progress: self.progress, control: control)
                    case .executeWorkflow, .recoverWorkflow:
                        return await PersonalRenewalService.shared.executeWorkflowJSON(
                            runID: self.runID, recovering: self.action == .recoverWorkflow,
                            progress: self.progress, control: control, workflowOwnerID: self.workflowOwnerID)
                    default:
                        return await PersonalRenewalService.shared.validateNativeJSON(progress: self.progress, control: control)
                    }
                } onCancel: { _ in
                    control.requestCancellation()
                    Task { await PersonalRenewalService.shared.requestCancellation(invocationID: control.id,
                        workflowOwnerID: self.workflowOwnerID) }
                }
            } catch {
                value = await PersonalRenewalService.shared.boundaryFailureJSON(error,
                    expectedRunID: (action == .executeWorkflow || action == .recoverWorkflow) ? runID : nil,
                    workflowOwnerID: workflowOwnerID)
            }
        }
        return .result(value: value)
    }

    private var observationPayload: String {
        if !networkObservation.isEmpty { return networkObservation }
        guard let observationDate, let quantumultXConnected, let localDevVPNConnected,
              let quantumultXOnDemand, let localDevVPNOnDemand else { return "" }
        let dateFormatter = ISO8601DateFormatter()
        dateFormatter.formatOptions = [.withInternetDateTime, .withFractionalSeconds]
        let object: [String: Any] = [
            "schemaVersion": 1, "source": "systemShortcutVPNQuery",
            "observedAt": dateFormatter.string(from: observationDate),
            "quantumultX": ["name": quantumultXName, "connected": quantumultXConnected,
                            "onDemand": quantumultXOnDemand],
            "localDevVPN": ["name": localDevVPNName, "connected": localDevVPNConnected,
                            "onDemand": localDevVPNOnDemand],
            "currentVPNNames": currentVPNNames ?? []
        ]
        guard let bytes = try? JSONSerialization.data(withJSONObject: object),
              let text = String(data: bytes, encoding: .utf8) else { return "" }
        return text
    }
}

private struct PersonalRenewalReadiness: Encodable {
    let app: RenewalApp
    let deviceIdentityConfirmed: Bool
    let matchingMainProfilePresent: Bool
    let earliestMatchingExpiration: Date?
    let observedAt: Date

    var ready: Bool { deviceIdentityConfirmed && matchingMainProfilePresent }
}

private enum PersonalRenewalReadinessError: Error {
    case minimuxerReadinessTimedOut
    case databaseNotStarted
    case invalidNetworkObservation
    case staleNetworkObservation
}

/// Actual values returned by Find VPNs/Get Current VPN, not private NEVPNStatus values.
private struct ShortcutNetworkObservation: Decodable {
    struct VPN: Decodable {
        let name: String
        let connected: Bool
        let onDemand: Bool
    }
    let schemaVersion: Int
    let source: String
    let observedAt: Date
    let quantumultX: VPN
    let localDevVPN: VPN
    let currentVPNNames: [String]

    static func decode(_ json: String, now: Date = Date()) throws -> Self {
        let decoder = JSONDecoder()
        decoder.dateDecodingStrategy = .custom { decoder in
            let text = try decoder.singleValueContainer().decode(String.self)
            let formatter = ISO8601DateFormatter()
            formatter.formatOptions = [.withInternetDateTime, .withFractionalSeconds]
            if let date = formatter.date(from: text) { return date }
            formatter.formatOptions = [.withInternetDateTime]
            guard let date = formatter.date(from: text) else {
                throw PersonalRenewalReadinessError.invalidNetworkObservation
            }
            return date
        }
        let value = try decoder.decode(Self.self, from: Data(json.utf8))
        guard value.schemaVersion == 1, value.source == "systemShortcutVPNQuery",
              !value.quantumultX.name.isEmpty, !value.localDevVPN.name.isEmpty,
              value.quantumultX.name != value.localDevVPN.name,
              Set(value.currentVPNNames).count == value.currentVPNNames.count else {
            throw PersonalRenewalReadinessError.invalidNetworkObservation
        }
        let expected = Set([value.quantumultX, value.localDevVPN].filter(\.connected).map(\.name))
        guard Set(value.currentVPNNames) == expected else {
            throw PersonalRenewalReadinessError.invalidNetworkObservation
        }
        guard abs(value.observedAt.timeIntervalSince(now)) <= 60 else {
            throw PersonalRenewalReadinessError.staleNetworkObservation
        }
        return value
    }

    var restoreTarget: NetworkRestoreTarget {
        NetworkRestoreTarget(quantumultX: quantumultX.connected ? .connected : .notConnected,
                             localDevVPN: localDevVPN.connected ? .connected : .notConnected,
                             quantumultXOnDemand: quantumultX.onDemand, localDevVPNOnDemand: localDevVPN.onDemand,
                             quantumultXName: quantumultX.name, localDevVPNName: localDevVPN.name)
    }

    var restorationObservation: NetworkRestorationObservation {
        NetworkRestorationObservation(quantumultX: restoreTarget.quantumultX,
                                      localDevVPN: restoreTarget.localDevVPN,
                                      source: .systemShortcutVPNQuery, observedAt: observedAt,
                                      quantumultXOnDemand: quantumultX.onDemand,
                                      localDevVPNOnDemand: localDevVPN.onDemand,
                                      quantumultXName: quantumultX.name, localDevVPNName: localDevVPN.name)
    }
}

private struct PersonalRenewalAppSummary: Encodable {
    let app: RenewalApp
    let state: RenewalAppState
    let requiresReverification: Bool
    let earliestExpiration: Date?
    let verifiedAt: Date?
    let expirationChange: ExpirationChange?
    let reusedFromRunID: String?
    let failureCodes: [String]

    init(_ attempt: RenewalAttempt) {
        app = attempt.target.app
        state = attempt.state
        requiresReverification = attempt.requiresReverification
        earliestExpiration = attempt.verification?.earliestExpiration
        verifiedAt = attempt.verification?.verifiedAt
        expirationChange = attempt.verification?.expirationChange
        reusedFromRunID = attempt.reusedFromRunID
        failureCodes = attempt.failures.map(\.machineCode)
    }
}

private struct PersonalRenewalReply: Encodable {
    let schemaVersion = 2
    var status: String
    var run: RenewalRun?
    var nativeWorkerDrained: Bool
    var nativeValidationCompleted: Bool
    var workflowCompleted = false
    var nextStep = "none"
    var restoreAllowed = false
    var earliestExpiration: Date?
    var nextEligibleAt: Date?
    var readiness: [PersonalRenewalReadiness]?
    var errorDomain: String?
    var errorCode: Int?
    var infrastructureFailure: RenewalFailure?
    var generatedWorkflowOwnerID: String?

    var apps: [PersonalRenewalAppSummary] { run?.attempts.map(PersonalRenewalAppSummary.init) ?? [] }
    var runID: String? { run?.id }
    var workflowOwnerID: String? { run?.workflowOwnerID ?? generatedWorkflowOwnerID }
    var networkRecoveryPending: Bool { run?.networkRecovery.isPending ?? false }
    var restoreTarget: NetworkRestoreTarget? {
        guard let run, run.networkPolicy == .switchAndRestore else { return nil }
        return run.networkRecovery.restoreTarget ??
            NetworkRestoreTarget(quantumultX: .connected, localDevVPN: .notConnected)
    }

    var displaySummary: String {
        let formatter = DateFormatter()
        formatter.dateStyle = .short
        formatter.timeStyle = .short
        let rows = apps.map { item in
            let name = item.app == .rustDesk ? "RustDesk V2" : "SideStore"
            let state: String
            switch item.state {
            case .verified: state = "已核验"
            case .reconciledInstalled: state = "中断后已读回（未补造原生回调）"
            case .failed: state = "失败"
            case .cancelled: state = "已取消"
            case .notStarted: state = "尚未执行"
            default: state = "待核验"
            }
            var text = name + "：" + state
            if item.requiresReverification { text += "，需要重新核验" }
            if let expiration = item.earliestExpiration { text += "；到期 " + formatter.string(from: expiration) }
            if item.reusedFromRunID != nil { text += "（本次读回后沿用已完成项）" }
            return text
        }
        return ([summary] + rows).joined(separator: "\n")
    }

    var summary: String {
        switch status {
        case "workflowOwnerCreated": return "已创建本次快捷指令入口编号。"
        case "recoveryConfirmationRequired": return "已有其他入口留下的任务。自动运行不会接管；手动恢复前请确认旧快捷指令已停止。"
        case "workflowPrepared": return "已保存原网络设置，正在切换续签网络。"
        case "workflowRecoveryRequired": return "发现中断任务，先核对结果并恢复原网络。"
        case "workflowAwaitingRestoration": return "原生操作已结束，正在恢复原网络设置。"
        case "workflowVerified": return "两项续签及系统 VPN 设置恢复均已核验。"
        case "workflowFinishedWithFailures": return "网络设置已恢复，续签结果见各 App；未确认双项成功。"
        case "restorationRequestRecorded": return "网络恢复请求已返回，等待系统查询结果。"
        case "notDue": return "两项 App 仍在有效期内，本次自动任务无需续签。"
        case "readyForNativeValidation": return "两项 App 身份与当前主描述文件已读取，可开始原生续签验证。"
        case "readinessIncomplete": return "续签准备未通过，请先查看各 App 的检查结果。"
        case "nativeVerified": return "RustDesk V2 与 SideStore 原生续签均已完成并核验。"
        case "nativeReconciled": return "中断后已核对设备上的描述文件；没有补造丢失的原生完成回调。"
        case "partiallyVerified": return "部分 App 已核验成功。再次执行时会先复核成功项，只重试必要项。"
        case "cancelled", "cancelledBeforeStart": return "续签请求已取消。"
        case "cancelling": return "已请求取消，正在等待原生操作结束。"
        case "preparing": return "正在准备续签。"
        case "busy": return "已有准备或续签任务在运行。"
        case "verificationRequired": return "需要重新读取设备结果，当前不能确认双项成功。"
        case "infrastructureFailure": return "结果记录失败，当前不能确认本次完成。"
        case "networkRecoveryRequired": return "仍有网络恢复义务，请先完成恢复。"
        case "recoveryRequired": return "有中断任务，需要先重新读取设备状态。"
        case "status":
            if nativeValidationCompleted { return "最近一次原生续签已完成并核验；结果时间见各 App。" }
            return "已读取当前状态。"
        default: return "本次未确认原生续签完成，请查看结果代码。"
        }
    }

    private enum CodingKeys: String, CodingKey {
        case schemaVersion, status, summary, displaySummary, apps, run, nativeWorkerDrained
        case nativeValidationCompleted, workflowCompleted, readiness
        case errorDomain, errorCode, infrastructureFailure
        case runID, nextStep, restoreAllowed, networkRecoveryPending, restoreTarget
        case earliestExpiration, nextEligibleAt
        case workflowOwnerID
    }

    func encode(to encoder: Encoder) throws {
        var values = encoder.container(keyedBy: CodingKeys.self)
        try values.encode(schemaVersion, forKey: .schemaVersion)
        try values.encode(status, forKey: .status)
        try values.encode(summary, forKey: .summary)
        try values.encode(displaySummary, forKey: .displaySummary)
        try values.encode(apps, forKey: .apps)
        try values.encodeIfPresent(run, forKey: .run)
        try values.encode(nativeWorkerDrained, forKey: .nativeWorkerDrained)
        try values.encode(nativeValidationCompleted, forKey: .nativeValidationCompleted)
        try values.encode(workflowCompleted, forKey: .workflowCompleted)
        try values.encodeIfPresent(runID, forKey: .runID)
        try values.encodeIfPresent(workflowOwnerID, forKey: .workflowOwnerID)
        try values.encode(nextStep, forKey: .nextStep)
        try values.encode(restoreAllowed, forKey: .restoreAllowed)
        try values.encode(networkRecoveryPending, forKey: .networkRecoveryPending)
        try values.encodeIfPresent(restoreTarget, forKey: .restoreTarget)
        try values.encodeIfPresent(earliestExpiration, forKey: .earliestExpiration)
        try values.encodeIfPresent(nextEligibleAt, forKey: .nextEligibleAt)
        try values.encodeIfPresent(readiness, forKey: .readiness)
        try values.encodeIfPresent(errorDomain, forKey: .errorDomain)
        try values.encodeIfPresent(errorCode, forKey: .errorCode)
        try values.encodeIfPresent(infrastructureFailure, forKey: .infrastructureFailure)
    }

    var json: String {
        let encoder = JSONEncoder()
        encoder.outputFormatting = [.sortedKeys]
        encoder.dateEncodingStrategy = .iso8601
        guard let data = try? encoder.encode(self), let string = String(data: data, encoding: .utf8) else {
            return "{\"schemaVersion\":2,\"status\":\"responseEncodingFailed\",\"workflowCompleted\":false,\"nativeValidationCompleted\":false,\"restoreAllowed\":false,\"nextStep\":\"none\"}"
        }
        return string
    }
}

actor PersonalRenewalService {
    static let shared = PersonalRenewalService()
    private var engine: RenewalEngine?
    private var activeInvocation: RenewalInvocationControl?
    private var activeRunID: String?
    private var activeWorkflowOwnerID: String?

    /// No database, device or VPN work is needed to identify one Shortcut invocation.
    func newWorkflowOwnerJSON() -> String {
        var reply = PersonalRenewalReply(status: "workflowOwnerCreated", nativeWorkerDrained: true,
                                         nativeValidationCompleted: false)
        reply.generatedWorkflowOwnerID = UUID().uuidString
        return reply.json
    }

    private func validatedWorkflowOwner(_ value: String?) throws -> String {
        guard let value, let owner = UUID(uuidString: value) else { throw RenewalCoreError.invalidWorkflowOwner }
        return owner.uuidString
    }

    private func requireWorkflowOwner(_ run: RenewalRun, _ value: String?) throws -> String {
        let owner = try validatedWorkflowOwner(value)
        guard let saved = run.workflowOwnerID, UUID(uuidString: saved)?.uuidString == owner else {
            throw RenewalCoreError.workflowOwnerMismatch
        }
        return owner
    }

    private func runtime() throws -> RenewalEngine {
        if let engine { return engine }
        guard let support = FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask).first else {
            throw RenewalCoreError.journalWriteUnverified
        }
        // Fresh namespace: no legacy automation journal is opened or imported.
        let journal = support.appendingPathComponent("PersonalRenewal", isDirectory: true)
            .appendingPathComponent("v1", isDirectory: true).appendingPathComponent("ledger.json")
        let created = try RenewalEngine(storage: FileRenewalJournalStorage(url: journal))
        engine = created
        return created
    }

    func prepareWorkflowJSON(mode: RenewalMode, observationJSON: String,
                             control: RenewalInvocationControl = RenewalInvocationControl(),
                             workflowOwnerID: String = "", allowRecoveryTakeover: Bool = false) async -> String {
        guard activeInvocation == nil else { return await busyJSON() }
        activeInvocation = control
        defer { activeInvocation = nil; activeRunID = nil; activeWorkflowOwnerID = nil }
        do {
            let owner = try validatedWorkflowOwner(workflowOwnerID)
            activeWorkflowOwnerID = owner
            try await waitForDatabaseReadiness(control: control)
            let observed = try ShortcutNetworkObservation.decode(observationJSON)
            let runtime = try self.runtime()
            var snapshot = await runtime.snapshot()
            guard !snapshot.nativeWorkerActive else { return await busyJSON() }
            // A native-only diagnostic can leave an unfinished record too. Reconcile it
            // read-only on this same entry before preparing a network-changing task.
            if let current = snapshot.current, current.phase != .finished,
               current.networkPolicy == .keepCurrent {
                activeRunID = current.id
                let recovered = try await runtime.reconcileInterruptedRun(
                    runID: current.id, driver: RenewalNativeDriver())
                try control.checkCancellation()
                guard recovered.nativeWorkerDrained, recovered.infrastructureFailure == nil,
                      recovered.run.phase == .finished else {
                    return reply(status: "infrastructureFailure", result: recovered).json
                }
                activeRunID = nil
                snapshot = await runtime.snapshot()
            }
            if let current = snapshot.current, current.phase != .finished {
                if let target = current.networkRecovery.restoreTarget {
                    guard (target.quantumultXName == nil || target.quantumultXName == observed.quantumultX.name),
                          (target.localDevVPNName == nil || target.localDevVPNName == observed.localDevVPN.name) else {
                        throw PersonalRenewalReadinessError.invalidNetworkObservation
                    }
                }
                let savedOwner = current.workflowOwnerID.flatMap { UUID(uuidString: $0)?.uuidString }
                guard savedOwner == owner || (mode == .manual && allowRecoveryTakeover) else {
                    return workflowReply(status: "recoveryConfirmationRequired", run: current,
                                         drained: true, nextStep: "confirmRecovery").json
                }
                let owned = try await runtime.takeWorkflowOwnership(runID: current.id, workflowOwnerID: owner,
                    mode: mode, allowRecoveryTakeover: allowRecoveryTakeover)
                activeRunID = owned.id
                try control.checkCancellation()
                return workflowReply(status: "workflowRecoveryRequired", run: owned,
                                     drained: true, nextStep: "recover").json
            }
            let targets = try await RenewalNativeDriver().resolveTargets()
            try control.checkCancellation()
            switch try await runtime.prepare(mode: mode, targets: targets, networkPolicy: .switchAndRestore,
                                             networkRestoreTarget: observed.restoreTarget, workflowOwnerID: owner) {
            case .ready(let plan):
                try control.checkCancellation()
                let run = try await runtime.beginNetworkChange(plan)
                activeRunID = run.id
                try control.checkCancellation()
                return workflowReply(status: "workflowPrepared", run: run, drained: true,
                                     nextStep: "switchAndExecute").json
            case .notDue(let expiration, let nextEligibleAt):
                var reply = PersonalRenewalReply(status: "notDue", nativeWorkerDrained: true,
                                                 nativeValidationCompleted: false)
                reply.nextStep = "skip"
                reply.earliestExpiration = expiration
                reply.nextEligibleAt = nextEligibleAt
                return reply.json
            case .recoveryRequired:
                let latest = await runtime.snapshot()
                if latest.current?.workflowOwnerID.flatMap({ UUID(uuidString: $0)?.uuidString }) != owner {
                    return workflowReply(status: "recoveryConfirmationRequired", run: latest.current,
                                         drained: !latest.nativeWorkerActive, nextStep: "confirmRecovery").json
                }
                return workflowReply(status: "workflowRecoveryRequired", run: latest.current,
                                     drained: !latest.nativeWorkerActive, nextStep: "recover").json
            case .busy:
                return await busyJSON()
            }
        } catch {
            if let activeRunID, control.isCancellationRequested || Task.isCancelled {
                try? await engine?.requestCancellation(runID: activeRunID, workflowOwnerID: activeWorkflowOwnerID)
            }
            return await failedReply(error).json
        }
    }

    func executeWorkflowJSON(runID: String, recovering: Bool, progress: Progress,
                             control: RenewalInvocationControl, workflowOwnerID: String = "") async -> String {
        guard activeInvocation == nil else { return await busyJSON() }
        activeInvocation = control
        activeRunID = runID
        defer { activeInvocation = nil; activeRunID = nil; activeWorkflowOwnerID = nil }
        progress.totalUnitCount = 3
        progress.completedUnitCount = 0
        do {
            let runtime = try self.runtime()
            let snapshot = await runtime.snapshot()
            guard let run = snapshot.current, run.id == runID,
                  run.networkPolicy == .switchAndRestore else { throw RenewalCoreError.wrongRun }
            activeWorkflowOwnerID = try requireWorkflowOwner(run, workflowOwnerID)
            guard !snapshot.nativeWorkerActive else { return await busyJSON() }
            guard run.phase != .finished else { throw RenewalCoreError.invalidPhase }
            if !recovering, run.phase != .networkChangePending {
                return workflowReply(status: "workflowRecoveryRequired", run: run,
                                     drained: true, nextStep: "recover").json
            }
            try await waitForDatabaseReadiness(control: control)
            // Reconciliation never installs profiles. A failed device read remains unverified,
            // but must not strand the user with the temporary network indefinitely.
            if !recovering { try await waitForMinimuxerReadiness(control: control) }
            try control.checkCancellation()
            progress.completedUnitCount = 1
            let driver = RenewalNativeDriver(progress: progress)
            let result: RenewalExecutionResult
            if recovering {
                result = try await runtime.reconcileInterruptedRun(runID: runID, driver: driver,
                    workflowOwnerID: activeWorkflowOwnerID)
            } else {
                result = try await runtime.execute(runID: runID, driver: driver, workflowOwnerID: activeWorkflowOwnerID)
            }
            if result.nativeWorkerDrained { progress.completedUnitCount = progress.totalUnitCount }
            return workflowReply(status: "workflowAwaitingRestoration", run: result.run,
                                 drained: result.nativeWorkerDrained, nextStep: "restore",
                                 infrastructureFailure: result.infrastructureFailure).json
        } catch {
            return await workflowFailureJSON(error, runID: runID, workflowOwnerID: workflowOwnerID)
        }
    }

    func recordRestorationRequestJSON(runID: String, workflowOwnerID: String = "") async -> String {
        guard activeInvocation == nil else { return await busyJSON() }
        do {
            let runtime = try self.runtime()
            try await runtime.recordRestorationRequestAccepted(runID: runID, workflowOwnerID: workflowOwnerID)
            let snapshot = await runtime.snapshot()
            return workflowReply(status: "restorationRequestRecorded", run: snapshot.current,
                                 drained: !snapshot.nativeWorkerActive).json
        } catch { return await failedReply(error).json }
    }

    func confirmRestorationJSON(runID: String, observationJSON: String, workflowOwnerID: String = "") async -> String {
        guard activeInvocation == nil else { return await busyJSON() }
        do {
            let runtime = try self.runtime()
            let observed = try ShortcutNetworkObservation.decode(observationJSON)
            try await runtime.confirmNetworkRestored(runID: runID, observation: observed.restorationObservation,
                workflowOwnerID: workflowOwnerID)
            let snapshot = await runtime.snapshot()
            let completed = snapshot.current?.fullyCompleted == true
            return workflowReply(status: completed ? "workflowVerified" : "workflowFinishedWithFailures",
                                 run: snapshot.current, drained: !snapshot.nativeWorkerActive).json
        } catch { return await failedReply(error).json }
    }

    /// Platform errors may prevent Shortcuts from continuing. Return a truthful receipt if the
    /// system still grants execution time; never turn an active worker into a restoration grant.
    func boundaryFailureJSON(_ error: Error, expectedRunID: String? = nil,
                             workflowOwnerID: String? = nil) async -> String {
        if let expectedRunID, !expectedRunID.isEmpty,
           activeInvocation != nil, activeRunID == expectedRunID,
           let owner = try? validatedWorkflowOwner(workflowOwnerID), owner == activeWorkflowOwnerID {
            return await workflowFailureJSON(error, runID: expectedRunID, workflowOwnerID: owner)
        }
        var reply = await failedReply(error)
        if let expectedRunID, reply.runID == expectedRunID, reply.networkRecoveryPending,
           let owner = try? validatedWorkflowOwner(workflowOwnerID), owner == reply.workflowOwnerID {
            reply.nextStep = "recover"
        }
        return reply.json
    }

    private func workflowFailureJSON(_ error: Error, runID: String, workflowOwnerID: String) async -> String {
        guard let runtime = engine else { return await failedReply(error).json }
        var snapshot = await runtime.snapshot()
        guard let current = snapshot.current, current.id == runID,
              (try? requireWorkflowOwner(current, workflowOwnerID)) != nil else {
            return await failedReply(error).json
        }
        // Before native entry, cancellation moves this exact run into the restore phase.
        // A cold running record must instead pass through explicit reconciliation.
        if snapshot.current?.id == runID, snapshot.current?.phase == .networkChangePending,
           !snapshot.nativeWorkerActive {
            try? await runtime.requestCancellation(runID: runID, workflowOwnerID: workflowOwnerID)
            snapshot = await runtime.snapshot()
        }
        guard snapshot.current?.id == runID else { return await failedReply(error).json }
        let native = error as NSError
        var reply = workflowReply(status: error is CancellationError ? "cancelledBeforeStart" : "failed",
                                  run: snapshot.current, drained: !snapshot.nativeWorkerActive,
                                  nextStep: "restore")
        reply.errorDomain = native.domain
        reply.errorCode = native.code
        return reply.json
    }

    private func workflowReply(status: String, run: RenewalRun?, drained: Bool,
                               nextStep: String = "none",
                               infrastructureFailure: RenewalFailure? = nil) -> PersonalRenewalReply {
        var reply = PersonalRenewalReply(status: status, run: run, nativeWorkerDrained: drained,
                                         nativeValidationCompleted: false,
                                         infrastructureFailure: infrastructureFailure)
        let mayRestore = drained && run?.networkPolicy == .switchAndRestore &&
            run?.phase == .awaitingNetworkRestoration && run?.networkRecovery.isPending == true
        reply.restoreAllowed = nextStep == "restore" && mayRestore
        reply.nextStep = nextStep == "restore" && !mayRestore ? "none" : nextStep
        reply.workflowCompleted = status == "workflowVerified" && infrastructureFailure == nil &&
            drained && run?.fullyCompleted == true
        return reply
    }

    private func waitForDatabaseReadiness(control: RenewalInvocationControl) async throws {
        let deadline = ProcessInfo.processInfo.systemUptime + 15
        while !DatabaseManager.shared.isStarted {
            try control.checkCancellation()
            guard ProcessInfo.processInfo.systemUptime < deadline else {
                throw PersonalRenewalReadinessError.databaseNotStarted
            }
            try await Task.sleep(nanoseconds: 250_000_000)
        }
        try control.checkCancellation()
    }

    func readinessJSON(progress: Progress, control: RenewalInvocationControl) async -> String {
        guard activeInvocation == nil else { return await busyJSON() }
        activeInvocation = control
        defer { activeInvocation = nil; activeRunID = nil }
        progress.totalUnitCount = 4
        progress.completedUnitCount = 0
        do {
            try control.checkCancellation()
            try await waitForMinimuxerReadiness(control: control)
            try control.checkCancellation()
            progress.completedUnitCount = 1
            let runtime = try self.runtime()
            let snapshot = await runtime.snapshot()
            guard !snapshot.nativeWorkerActive else { return await busyJSON() }
            let driver = RenewalNativeDriver()
            let targets = try await driver.resolveTargets()
            try control.checkCancellation()
            progress.completedUnitCount = 2
            var readiness: [PersonalRenewalReadiness] = []
            for target in targets {
                try control.checkCancellation()
                let observation = try await driver.readDeviceProfiles(target: target)
                try control.checkCancellation()
                let main = observation.profiles.filter {
                    $0.bundleIdentifier == target.installedBundleIdentifier &&
                    $0.teamIdentifier == target.teamIdentifier &&
                    $0.certificateSHA256.contains(target.signingCertificateSHA256) &&
                    $0.expiresAt > observation.observedAt
                }
                readiness.append(PersonalRenewalReadiness(
                    app: target.app, deviceIdentityConfirmed: observation.applicationPresenceConfirmed,
                    matchingMainProfilePresent: main.count == 1,
                    earliestMatchingExpiration: main.map(\.expiresAt).min(), observedAt: observation.observedAt))
                progress.completedUnitCount += 1
            }
            return PersonalRenewalReply(status: readiness.allSatisfy(\.ready) ? "readyForNativeValidation" : "readinessIncomplete",
                                        nativeWorkerDrained: true, nativeValidationCompleted: false,
                                        readiness: readiness).json
        } catch { return await failedReply(error).json }
    }

    func validateNativeJSON(progress: Progress, control: RenewalInvocationControl) async -> String {
        guard activeInvocation == nil else { return await busyJSON() }
        activeInvocation = control
        defer { activeInvocation = nil; activeRunID = nil }
        progress.totalUnitCount = 3
        progress.completedUnitCount = 0
        do {
            try control.checkCancellation()
            try await waitForMinimuxerReadiness(control: control)
            try control.checkCancellation()
            let runtime = try self.runtime()
            let driver = RenewalNativeDriver(progress: progress)
            let targets = try await driver.resolveTargets()
            try control.checkCancellation()
            progress.completedUnitCount = 1
            var preparation = try await runtime.prepare(mode: .manual, targets: targets, networkPolicy: .keepCurrent)
            try control.checkCancellation()
            if case .recoveryRequired(let runID) = preparation {
                activeRunID = runID
                let recovered = try await runtime.reconcileInterruptedRun(runID: runID, driver: driver)
                if recovered.infrastructureFailure != nil {
                    return reply(status: "infrastructureFailure", result: recovered).json
                }
                try control.checkCancellation()
                guard recovered.run.networkPolicy == .keepCurrent else {
                    return reply(status: "networkRecoveryRequired", result: recovered).json
                }
                let allInstalled = recovered.run.attempts.allSatisfy {
                    !$0.requiresReverification && $0.verification != nil &&
                        ($0.state == .verified || $0.state == .reconciledInstalled)
                }
                if allInstalled {
                    return reply(status: "nativeReconciled", result: recovered).json
                }
                preparation = try await runtime.prepare(mode: .manual, targets: targets, networkPolicy: .keepCurrent)
                try control.checkCancellation()
            }
            switch preparation {
            case .ready(let plan):
                try control.checkCancellation()
                let run = try await runtime.beginNativeOnly(plan)
                activeRunID = run.id
                // An onCancel signal may arrive during the begin journal write.
                // Stop this particular run before starting its native worker.
                if control.isCancellationRequested || Task.isCancelled {
                    try await runtime.requestCancellation(runID: run.id)
                    let snapshot = await runtime.snapshot()
                    return PersonalRenewalReply(status: "cancelledBeforeStart", run: snapshot.current,
                                                nativeWorkerDrained: !snapshot.nativeWorkerActive,
                                                nativeValidationCompleted: false).json
                }
                let result = try await runtime.execute(runID: run.id, driver: driver)
                if result.nativeWorkerDrained { progress.completedUnitCount = progress.totalUnitCount }
                let status: String
                if result.infrastructureFailure != nil {
                    status = "infrastructureFailure"
                } else if result.nativeWorkerDrained && result.run.nativeValidationCompleted {
                    status = "nativeVerified"
                } else if result.run.attempts.contains(where: { $0.requiresReverification }) {
                    status = "verificationRequired"
                } else {
                    switch result.run.outcome {
                    case .succeeded, .recoveredAndVerified: status = "unverified"
                    case .partiallySucceeded: status = "partiallyVerified"
                    case .failed: status = "failed"
                    case .cancelled: status = "cancelled"
                    }
                }
                return reply(status: status, result: result).json
            case .busy:
                return await busyJSON()
            case .recoveryRequired:
                let snapshot = await runtime.snapshot()
                return PersonalRenewalReply(status: "recoveryRequired", run: snapshot.current,
                                            nativeWorkerDrained: !snapshot.nativeWorkerActive,
                                            nativeValidationCompleted: false).json
            case .notDue:
                throw RenewalCoreError.nativeProtocolViolation("manualRequestWasThrottled")
            }
        } catch { return await failedReply(error).json }
    }

    private func waitForMinimuxerReadiness(control: RenewalInvocationControl) async throws {
        let deadline = ProcessInfo.processInfo.systemUptime + 15
        var readiness: Result<Bool, MinimuxerError> = .success(false)
        repeat {
            try control.checkCancellation()
            // Observe normal upstream boot; do not start or reconfigure it here.
            if DatabaseManager.shared.isStarted {
                // Join each probe before checking the deadline to avoid leaving device work behind.
                readiness = await minimuxer.core.isReady(withNetworkCheck: true, withDDIMountCheck: false)
                try control.checkCancellation()
                if case .success(true) = readiness { return }
            }
            guard ProcessInfo.processInfo.systemUptime < deadline else { break }
            try await Task.sleep(nanoseconds: 250_000_000)
        } while ProcessInfo.processInfo.systemUptime < deadline

        try control.checkCancellation()
        guard DatabaseManager.shared.isStarted else { throw PersonalRenewalReadinessError.databaseNotStarted }
        if case .failure(let error) = readiness { throw error }
        throw PersonalRenewalReadinessError.minimuxerReadinessTimedOut
    }

    func statusJSON() async -> String {
        do {
            let snapshot = await (try runtime()).snapshot()
            let preparing = activeInvocation != nil && activeRunID == nil
            return PersonalRenewalReply(status: preparing ? "preparing" : "status", run: snapshot.current,
                                        nativeWorkerDrained: !snapshot.nativeWorkerActive,
                                        nativeValidationCompleted: !preparing && !snapshot.nativeWorkerActive &&
                                            (snapshot.current?.nativeValidationCompleted ?? false)).json
        } catch { return await failedReply(error).json }
    }

    func requestCancellation(invocationID: String, workflowOwnerID: String? = nil) async {
        // A delayed cleanup request can only affect its originating invocation.
        guard activeInvocation?.id == invocationID else { return }
        if let activeWorkflowOwnerID {
            guard (try? validatedWorkflowOwner(workflowOwnerID)) == activeWorkflowOwnerID else { return }
        }
        await requestCurrentCancellation(expectedInvocationID: invocationID,
                                         expectedWorkflowOwnerID: activeWorkflowOwnerID)
    }

    private func requestCurrentCancellation(expectedInvocationID: String?, expectedWorkflowOwnerID: String?) async {
        guard activeInvocation?.id == expectedInvocationID,
              activeWorkflowOwnerID == expectedWorkflowOwnerID else { return }
        activeInvocation?.requestCancellation()
        guard let runtime = engine, let runID = activeRunID else { return }
        let snapshot = await runtime.snapshot()
        guard activeInvocation?.id == expectedInvocationID, activeRunID == runID,
              activeWorkflowOwnerID == expectedWorkflowOwnerID,
              snapshot.current?.id == runID, snapshot.current?.phase != .finished else { return }
        try? await runtime.requestCancellation(runID: runID, workflowOwnerID: expectedWorkflowOwnerID)
    }

    /// An explicit in-app button may cancel the currently shown workflow.
    /// AppIntent callers still have to supply their own matching owner UUID.
    func cancelFromAppUIJSON() async -> String {
        await cancelJSON(workflowOwnerID: activeWorkflowOwnerID)
    }

    func cancelJSON(workflowOwnerID: String? = nil) async -> String {
        do {
            if let activeWorkflowOwnerID {
                guard try validatedWorkflowOwner(workflowOwnerID) == activeWorkflowOwnerID else {
                    throw RenewalCoreError.workflowOwnerMismatch
                }
            }
            await requestCurrentCancellation(expectedInvocationID: activeInvocation?.id,
                                             expectedWorkflowOwnerID: activeWorkflowOwnerID)
            let snapshot = await (try runtime()).snapshot()
            return PersonalRenewalReply(status: activeInvocation == nil ? "status" : "cancelling",
                                        run: snapshot.current, nativeWorkerDrained: !snapshot.nativeWorkerActive,
                                        nativeValidationCompleted: false).json
        } catch { return await failedReply(error).json }
    }

    private func busyJSON() async -> String {
        let snapshot = await engine?.snapshot()
        return PersonalRenewalReply(status: "busy", run: snapshot?.current,
                                    nativeWorkerDrained: !(snapshot?.nativeWorkerActive ?? false),
                                    nativeValidationCompleted: false).json
    }

    private func reply(status: String, result: RenewalExecutionResult) -> PersonalRenewalReply {
        PersonalRenewalReply(status: status, run: result.run, nativeWorkerDrained: result.nativeWorkerDrained,
                            nativeValidationCompleted: result.infrastructureFailure == nil &&
                                result.nativeWorkerDrained && result.run.nativeValidationCompleted,
                            infrastructureFailure: result.infrastructureFailure)
    }

    private func failedReply(_ error: Error) async -> PersonalRenewalReply {
        let snapshot = await engine?.snapshot()
        let native = error as NSError
        let cancelled = error is CancellationError
        // Never serialize raw userInfo/messages containing private device data.
        return PersonalRenewalReply(status: cancelled ? "cancelledBeforeStart" : "failed", run: snapshot?.current,
                                    nativeWorkerDrained: !(snapshot?.nativeWorkerActive ?? false),
                                    nativeValidationCompleted: false,
                                    errorDomain: native.domain, errorCode: native.code)
    }
}

import Foundation
@preconcurrency import CoreData
import CryptoKit
import SideSign
import RenewalCore

/// Personal renewal uses the existing one-app profile-refresh pipeline. This
/// adapter never installs an IPA, removes an app, or chooses a new identity.
actor RenewalNativeDriver: RenewalDeviceDriver {
    private var activeOperation: NativeOperation?
    private var cancellation: NativeCancellationFlag?
    private let progress: Progress?

    init(progress: Progress? = nil) {
        self.progress = progress
    }

    func resolveTargets() async throws -> [RenewalTarget] {
        guard DatabaseManager.shared.isStarted else { throw NativeRenewalError.databaseNotStarted }
        let context = DatabaseManager.shared.persistentContainer.newBackgroundContext()
        return try await context.perform {
            try [RenewalApp.rustDesk, .sideStore].map { app in
                try Self.resolve(app: app, in: context).target
            }
        }
    }

    func requestNativeCancellation() async {
        cancellation?.request()
        activeOperation?.group.cancel()
        // This is a request only. refreshNative still joins the concrete task.
    }

    func refreshNative(
        target: RenewalTarget,
        beforeInstall: @escaping @Sendable (PreparedProfileSet) async throws -> Void
    ) async throws -> NativeRefreshCompletion {
        guard cancellation == nil else { throw NativeRenewalError.operationAlreadyActive }
        try Task.checkCancellation()
        let operationID = UUID().uuidString
        let flag = NativeCancellationFlag()
        cancellation = flag
        defer {
            activeOperation = nil
            cancellation = nil
        }

        try await ensureMinimuxerReady()
        guard minimuxer.network.isWifiSatisfied else { throw NativeRenewalError.currentWiFiRequired }
        guard try await Self.confirmDeviceIdentity(target) else {
            throw NativeRenewalError.installedIdentityUnverified
        }
        try flag.check()

        let context = DatabaseManager.shared.persistentContainer.newBackgroundContext()
        let operation = try await context.perform {
            let record = try Self.resolve(app: target.app, in: context)
            guard record.target == target else { throw NativeRenewalError.identityChanged }
            let group = RefreshGroup(dbContext: context)
            group.preserveCurrentNetwork = true
            if target.app == .sideStore {
                group.profileRefreshSourceURLs[target.originalBundleIdentifier] = Bundle.Info.activeBundleURL
            }
            let completion = NativeCompletionBox()
            let requiredIDs = record.requiredProfileBundleIdentifiers
            group.completionHandler = { completion.record($0) }
            group.beforeProfileInstallation = { originalID, data in
                try flag.check()
                guard originalID == target.originalBundleIdentifier else {
                    throw NativeRenewalError.identityChanged
                }
                var byUUID: [String: ProfileEvidence] = [:]
                for profile in try data.map(Self.profileEvidence) {
                    if let existing = byUUID[profile.uuid], existing.sha256 != profile.sha256 {
                        throw NativeRenewalError.invalidProfileEvidence
                    }
                    byUUID[profile.uuid] = profile
                }
                let profiles = byUUID.values.sorted { $0.uuid < $1.uuid }
                guard !profiles.isEmpty,
                      Set(profiles.map(\.bundleIdentifier)) == requiredIDs,
                      profiles.allSatisfy({
                          $0.teamIdentifier == target.teamIdentifier &&
                          $0.certificateSHA256.contains(target.signingCertificateSHA256)
                      }),
                      profiles.filter({ $0.bundleIdentifier == target.installedBundleIdentifier }).count == 1,
                      let main = profiles.first(where: { $0.bundleIdentifier == target.installedBundleIdentifier }) else {
                    throw NativeRenewalError.preparedProfileIdentityMismatch
                }
                let receipt = PreparedProfileSet(
                    operationID: operationID, target: target,
                    mainProfileUUID: main.uuid, profiles: profiles
                )
                try await beforeInstall(receipt)
                try flag.check()
            }
            AppManager.shared.refresh([record.app], presentingViewController: nil, dbContext: context, group: group)
            return NativeOperation(group: group, completion: completion)
        }
        activeOperation = operation
        progress?.addChild(operation.group.progress, withPendingUnitCount: 1)
        if flag.isRequested || Task.isCancelled { operation.group.cancel() }
        guard let task = operation.group.activeTask else { throw NativeRenewalError.nativeTaskMissing }

        await withTaskCancellationHandler {
            await task.value
        } onCancel: {
            flag.request()
            operation.group.cancel()
        }
        // No timeout race: all in-flight native FFI work owned by this task has
        // returned before the coordinator can authorize network restoration.
        try operation.completion.requireSuccess(for: target.originalBundleIdentifier)
        try await context.perform {
            if context.hasChanges { try context.save() }
            guard try Self.resolve(app: target.app, in: context).target == target else {
                throw NativeRenewalError.identityChanged
            }
        }
        // A late cancellation must not discard a native success already joined
        // and saved. Core records this completion before stopping further work.
        return NativeRefreshCompletion(operationID: operationID, target: target, completedAt: Date())
    }

    func readDeviceProfiles(target: RenewalTarget) async throws -> DeviceProfileObservation {
        try Task.checkCancellation()
        try await ensureMinimuxerReady()
        guard minimuxer.network.isWifiSatisfied else { throw NativeRenewalError.currentWiFiRequired }
        let context = DatabaseManager.shared.persistentContainer.newBackgroundContext()
        let allowedIDs = try await context.perform {
            let record = try Self.resolve(app: target.app, in: context)
            guard record.target == target else { throw NativeRenewalError.identityChanged }
            return record.allowedBundleIdentifiers
        }
        let presence = try await Self.confirmDeviceIdentity(target)
        try Task.checkCancellation()

        let directory = FileManager.default.temporaryDirectory.appendingPathComponent("RenewalReadback-" + UUID().uuidString, isDirectory: true)
        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: false)
        defer { try? FileManager.default.removeItem(at: directory) }
        let dumpedPath = try await minimuxer.core.dumpProfiles(docsPath: directory.path, mode: .raw)
        let expectedDirectory = directory.appendingPathComponent("Profiles", isDirectory: true).standardizedFileURL
        guard URL(fileURLWithPath: dumpedPath).standardizedFileURL == expectedDirectory else {
            throw NativeRenewalError.profileReadbackIncomplete
        }
        let files = try FileManager.default.contentsOfDirectory(at: expectedDirectory, includingPropertiesForKeys: [.isRegularFileKey])
        var profiles: [ProfileEvidence] = []
        for file in files where file.pathExtension == "mobileprovision" {
            guard try file.resourceValues(forKeys: [.isRegularFileKey]).isRegularFile == true else { continue }
            let data = try Data(contentsOf: file)
            guard data.count <= 2_000_000 else { throw NativeRenewalError.profileReadbackIncomplete }
            // A malformed unrelated profile is not evidence for this target.
            // If an expected profile is missing/malformed, Core cannot match it.
            guard let profile = try? Self.profileEvidence(data), allowedIDs.contains(profile.bundleIdentifier) else { continue }
            profiles.append(profile)
        }
        try Task.checkCancellation()
        return DeviceProfileObservation(
            target: target, profiles: profiles,
            applicationPresenceConfirmed: presence, observedAt: Date()
        )
        // The device metadata supplies bundle + Team, and the device profile
        // supplies certificate binding. It does not read the installed binary's
        // signing certificate; launch/real-use acceptance remains required.
    }

    private struct TargetRecord {
        let app: InstalledApp
        let target: RenewalTarget
        let allowedBundleIdentifiers: Set<String>
        let requiredProfileBundleIdentifiers: Set<String>
    }

    private static func resolve(app kind: RenewalApp, in context: NSManagedObjectContext) throws -> TargetRecord {
        let originalID = kind == .rustDesk ? "com.bearberni.rustdesk.v2" : StoreApp.altstoreAppID
        let request = InstalledApp.fetchRequest()
        request.predicate = NSPredicate(format: "%K == %@", #keyPath(InstalledApp.bundleIdentifier), originalID)
        let records = try context.fetch(request)
        guard records.count == 1, let app = records.first, app.isActive,
              !app.resignedBundleIdentifier.isEmpty,
              let certificate = CertificateManager.shared.getSigningCertificate(for: app),
              let certificateData = certificate.data else {
            throw NativeRenewalError.targetIdentityUnavailable
        }
        if let storedSerial = app.certificateSerialNumber, !storedSerial.isEmpty,
           normalizedSerial(storedSerial) != normalizedSerial(certificate.serialNumber) {
            throw NativeRenewalError.identityChanged
        }
        let certificateSHA256 = digest(certificateData)
        let team: String
        if kind == .sideStore {
            guard let runningBundle = ALTApplication(fileURL: Bundle.Info.activeBundleURL),
                  runningBundle.bundleIdentifier == app.resignedBundleIdentifier,
                  runningBundle.version == app.version,
                  runningBundle.buildVersion == app.buildVersion else {
                throw NativeRenewalError.identityChanged
            }
            let embeddedURL = Bundle.Info.activeBundleURL.appendingPathComponent("embedded.mobileprovision")
            let embedded = try profileEvidence(Data(contentsOf: embeddedURL))
            // DatabaseManager creates a self record without assigning its Team
            // relationship. Use the running signed profile, never a guessed
            // account or the first certificate from a multi-certificate profile.
            guard embedded.bundleIdentifier == app.resignedBundleIdentifier,
                  embedded.certificateSHA256 == [certificateSHA256] else {
                throw NativeRenewalError.embeddedProfileIdentityUnavailable
            }
            if let storedTeam = app.team?.identifier, !storedTeam.isEmpty,
               storedTeam != embedded.teamIdentifier {
                throw NativeRenewalError.identityChanged
            }
            if FileManager.default.fileExists(atPath: app.signingCertificateURL.path) {
                let cachedData = try Data(contentsOf: app.signingCertificateURL)
                guard let cached = ALTX509Certificate(data: cachedData), let cachedDER = cached.data,
                      digest(cachedDER) == certificateSHA256 else {
                    throw NativeRenewalError.identityChanged
                }
            }
            team = embedded.teamIdentifier
        } else {
            guard let storedTeam = app.team?.identifier, !storedTeam.isEmpty else {
                throw NativeRenewalError.targetIdentityUnavailable
            }
            guard ALTApplication(fileURL: app.fileURL) != nil else {
                throw NativeRenewalError.originalAppCacheUnavailable
            }
            team = storedTeam
        }
        let target = RenewalTarget(
            app: kind, originalBundleIdentifier: originalID,
            installedBundleIdentifier: app.resignedBundleIdentifier,
            teamIdentifier: team, signingCertificateSHA256: certificateSHA256,
            installationFingerprint: try installationFingerprint(for: app)
        )
        let identifiers = Set([app.resignedBundleIdentifier] + app.appExtensions.map(\.resignedBundleIdentifier))
        let required = app.useMainProfile ? Set([app.resignedBundleIdentifier]) : identifiers
        return TargetRecord(app: app, target: target, allowedBundleIdentifiers: identifiers, requiredProfileBundleIdentifiers: required)
    }

    private static func confirmDeviceIdentity(_ target: RenewalTarget) async throws -> Bool {
        let context = DatabaseManager.shared.persistentContainer.newBackgroundContext()
        let expectedVersion = try await context.perform {
            let record = try Self.resolve(app: target.app, in: context)
            guard record.target == target else { throw NativeRenewalError.identityChanged }
            return (version: record.app.version, build: record.app.buildVersion)
        }
        let data = try await minimuxer.core.applicationMetadata(bundleID: target.installedBundleIdentifier)
        let metadata = try PropertyListSerialization.propertyList(from: data, options: [], format: nil) as? [String: String]
        let team = metadata?["TeamIdentifier"] ?? metadata?["EntitlementTeamIdentifier"]
        let teamFieldsAgree = metadata?["TeamIdentifier"] == nil || metadata?["EntitlementTeamIdentifier"] == nil ||
            metadata?["TeamIdentifier"] == metadata?["EntitlementTeamIdentifier"]
        return metadata?["CFBundleIdentifier"] == target.installedBundleIdentifier &&
            team == target.teamIdentifier && teamFieldsAgree &&
            !expectedVersion.version.isEmpty && !expectedVersion.build.isEmpty &&
            metadata?["CFBundleShortVersionString"] == expectedVersion.version &&
            metadata?["CFBundleVersion"] == expectedVersion.build
    }

    private static func installationFingerprint(for app: InstalledApp) throws -> String {
        // The official fingerprint identifies cached source structure; it is
        // not a measurement of the device binary. Bind it to the installed DB
        // version/build, which are independently checked against device metadata.
        // A missing source identity remains unknown, so Core cannot auto-skip.
        guard let source = app.appBundleFingerprint, !source.isEmpty,
              !app.version.isEmpty, !app.buildVersion.isEmpty else { return "" }
        let identity = try JSONSerialization.data(withJSONObject: ["renewal-installation-v1", source, app.version, app.buildVersion])
        return digest(identity)
    }

    private static func profileEvidence(_ data: Data) throws -> ProfileEvidence {
        guard let begin = data.range(of: Data("<?xml".utf8)),
              let end = data.range(of: Data("</plist>".utf8), in: begin.lowerBound..<data.endIndex),
              let dictionary = try PropertyListSerialization.propertyList(from: data.subdata(in: begin.lowerBound..<end.upperBound), options: [], format: nil) as? [String: Any],
              let rawUUID = dictionary["UUID"] as? String, let uuid = UUID(uuidString: rawUUID),
              let teams = dictionary["TeamIdentifier"] as? [String], teams.count == 1,
              let prefixes = dictionary["ApplicationIdentifierPrefix"] as? [String], prefixes.count == 1,
              let entitlements = dictionary["Entitlements"] as? [String: Any],
              let applicationIdentifier = entitlements["application-identifier"] as? String,
              applicationIdentifier.hasPrefix(prefixes[0] + "."),
              let certificates = dictionary["DeveloperCertificates"] as? [Data], !certificates.isEmpty,
              let created = dictionary["CreationDate"] as? Date,
              let expires = dictionary["ExpirationDate"] as? Date, expires > created else {
            throw NativeRenewalError.invalidProfileEvidence
        }
        if let entitlementTeam = entitlements["com.apple.developer.team-identifier"] as? String, entitlementTeam != teams[0] {
            throw NativeRenewalError.invalidProfileEvidence
        }
        return ProfileEvidence(
            uuid: uuid.uuidString,
            bundleIdentifier: String(applicationIdentifier.dropFirst(prefixes[0].count + 1)),
            teamIdentifier: teams[0], certificateSHA256: Array(Set(certificates.map(digest))).sorted(),
            createdAt: created, expiresAt: expires, sha256: digest(data)
        )
    }

    private static func digest(_ data: Data) -> String {
        SHA256.hash(data: data).map { String(format: "%02x", $0) }.joined()
    }

    private static func normalizedSerial(_ value: String) -> String {
        let hexadecimal = value.lowercased().filter { $0.isHexDigit }
        return String(hexadecimal.drop(while: { $0 == "0" }))
    }
}

private final class NativeCancellationFlag: @unchecked Sendable {
    private let lock = NSLock()
    private var requested = false
    var isRequested: Bool { lock.withLock { requested } }
    func request() { lock.withLock { requested = true } }
    func check() throws { if isRequested || Task.isCancelled { throw CancellationError() } }
}

private final class NativeOperation: @unchecked Sendable {
    let group: RefreshGroup
    let completion: NativeCompletionBox
    init(group: RefreshGroup, completion: NativeCompletionBox) {
        self.group = group
        self.completion = completion
    }
}

private final class NativeCompletionBox: @unchecked Sendable {
    private let lock = NSLock()
    private var count = 0
    private var errors: [String: Error] = [:]
    private var successfulIDs = Set<String>()

    func record(_ results: [String: Result<InstalledApp, Error>]) {
        lock.withLock {
            count += 1
            for (identifier, result) in results {
                switch result {
                case .success: successfulIDs.insert(identifier)
                case .failure(let error): errors[identifier] = error
                }
            }
        }
    }

    func requireSuccess(for identifier: String) throws {
        try lock.withLock {
            guard count == 1 else { throw NativeRenewalError.invalidNativeCompletion }
            if let error = errors[identifier] { throw error }
            guard successfulIDs == Set([identifier]), errors.isEmpty else { throw NativeRenewalError.invalidNativeCompletion }
        }
    }
}

private enum NativeRenewalError: String, LocalizedError {
    case operationAlreadyActive, targetIdentityUnavailable, identityChanged
    case originalAppCacheUnavailable, installedIdentityUnverified
    case embeddedProfileIdentityUnavailable
    case currentWiFiRequired
    case preparedProfileIdentityMismatch, nativeTaskMissing, invalidNativeCompletion
    case invalidProfileEvidence, profileReadbackIncomplete
    case databaseNotStarted
    var errorDescription: String? { "RenewalNativeDriver: " + rawValue }
}

import SwiftUI
import RenewalCore

@available(iOS 27.0, tvOS 27.0, *)
struct PersonalRenewalView: View {
    @State private var running = false
    @State private var checking = false
    @State private var control: RenewalInvocationControl?
    @State private var report: NativeReport?
    @State private var parseFailed = false

    var body: some View {
        Form {
            Section {
                Text("先连接 LocalDevVPN，再检查准备。开始后会依次续签 RustDesk V2 和 SideStore，并重新读取设备结果。")
                SwiftUI.Button("检查准备") { start(checkOnly: true) }
                    .disabled(running)
                SwiftUI.Button("开始原生续签") { start(checkOnly: false) }
                    .disabled(running)
                if running {
                    ProgressView(checking ? "正在检查准备" : "正在续签并核验")
                }
                SwiftUI.Button("请求取消") {
                    control?.requestCancellation()
                    Task {
                        let value = await PersonalRenewalService.shared.cancelFromAppUIJSON()
                        show(value)
                    }
                }
            } footer: {
                Text("此阶段保持当前网络。取消后请等待结果；系统强制终止时，下次从同一入口重新核对中断状态。")
            }

            if let report {
                Section("本次结果") {
                    Text(report.summary)
                    if let runID = report.run?.id {
                        Text("任务：" + runID).font(.caption).textSelection(.enabled)
                    }
                    ForEach(report.apps, id: \.app) { app in
                        VStack(alignment: .leading, spacing: 4) {
                            Text(label(app.app)).font(.headline)
                            Text(app.requiresReverification ? "待重新核验" : stateLabel(app.state))
                            if app.reusedFromRunID != nil {
                                Text("本轮重新核对后沿用上次已完成的续签结果").font(.caption)
                            }
                            if app.expirationChange == "unchangedOrEarlier" {
                                Text("当前描述文件有效，到期时间未延长").font(.caption)
                            }
                            if let date = app.earliestExpiration {
                                Text("最早到期：" + date.formatted(date: .abbreviated, time: .shortened))
                            }
                            if let date = app.verifiedAt {
                                Text("核验时间：" + date.formatted(date: .abbreviated, time: .shortened))
                                    .font(.caption)
                            }
                            if !app.failureCodes.isEmpty {
                                Text(app.failureCodes.joined(separator: "、")).font(.caption)
                            }
                        }
                    }
                    ForEach(report.readiness ?? [], id: \.app) { item in
                        VStack(alignment: .leading, spacing: 4) {
                            Text(label(item.app)).font(.headline)
                            Text(item.deviceIdentityConfirmed ? "设备上的 App 身份已核对" : "设备上的 App 身份未确认")
                            Text(item.matchingMainProfilePresent ? "当前主描述文件可读取" : "当前主描述文件需要检查")
                            if let date = item.earliestMatchingExpiration {
                                Text("主描述文件到期：" + date.formatted(date: .abbreviated, time: .shortened))
                            }
                        }
                    }
                    if let domain = report.errorDomain {
                        Text("错误代码：\(domain) / \(report.errorCode ?? 0)").font(.caption).textSelection(.enabled)
                    }
                    SwiftUI.Button("重新读取状态") {
                        Task { show(await PersonalRenewalService.shared.statusJSON()) }
                    }
                }
            } else if parseFailed {
                Section { Text("结果无法读取，当前不能确认续签成功。") }
            }
        }
        .navigationTitle("双 App 续签")
        .task { show(await PersonalRenewalService.shared.statusJSON()) }
    }

    private func start(checkOnly: Bool) {
        let invocation = RenewalInvocationControl()
        control = invocation
        checking = checkOnly
        running = true
        Task {
            let progress = Progress(totalUnitCount: checkOnly ? 4 : 3)
            let value: String
            if checkOnly {
                value = await PersonalRenewalService.shared.readinessJSON(progress: progress, control: invocation)
            } else {
                value = await PersonalRenewalService.shared.validateNativeJSON(progress: progress, control: invocation)
            }
            show(value)
            running = false
            control = nil
        }
    }

    private func show(_ json: String) {
        let decoder = JSONDecoder()
        decoder.dateDecodingStrategy = .iso8601
        report = json.data(using: .utf8).flatMap { try? decoder.decode(NativeReport.self, from: $0) }
        parseFailed = report == nil
    }

    private func label(_ app: String) -> String { app == "rustDesk" ? "RustDesk V2" : "SideStore" }

    private func stateLabel(_ state: String) -> String {
        switch state {
        case "notStarted": return "尚未开始"
        case "nativeRunning", "profilesPrepared": return "原生操作中"
        case "nativeCompleted": return "原生操作已结束，等待核验"
        case "verified": return "已核验"
        case "reconciledInstalled": return "中断后的设备状态已核对"
        case "failed": return "失败"
        case "cancelled": return "已取消"
        default: return "状态待核对"
        }
    }

    private struct NativeReport: Decodable {
        let summary: String
        let apps: [App]
        let readiness: [Readiness]?
        let run: Run?
        let errorDomain: String?
        let errorCode: Int?
        struct Run: Decodable { let id: String }
        struct App: Decodable {
            let app: String
            let state: String
            let requiresReverification: Bool
            let earliestExpiration: Date?
            let verifiedAt: Date?
            let expirationChange: String?
            let reusedFromRunID: String?
            let failureCodes: [String]
        }
        struct Readiness: Decodable {
            let app: String
            let deviceIdentityConfirmed: Bool
            let matchingMainProfilePresent: Bool
            let earliestMatchingExpiration: Date?
        }
    }
}
